CNP.IDL:
// Hash: 0eddce77e4efb121810fc76f42dbdd5d6e5dd721d973c98073e5aeff25053388
// Version: 1.176.1
// -----------------------------------END_HEADER
/// Granularity of the geography a measurement window is keyed to.
enum cnpRegionKind : byte {
  /// No geographic restriction — the aggregate covers everywhere the operator
  /// serves.
  GLOBAL,
  /// A country. CODE is ISO 3166-1 alpha-2.
  COUNTRY,
  /// A first-level subdivision. CODE is ISO 3166-2.
  SUBDIVISION,
  /// A metropolitan area or city. CODE is the source's own key.
  METRO,
  /// A ground-segment cell or beam footprint. CODE is the operator's own key.
  CELL,
  /// A point of presence / ground gateway. CODE is the source's own key.
  POINT_OF_PRESENCE,
  /// The source keys by something none of the above describes. CODE and NAME
  /// carry the source's key verbatim.
  OTHER
}

/// Calendar span an aggregate covers.
enum cnpPeriod : byte {
  /// WINDOW_START/WINDOW_STOP are authoritative and match none of the named
  /// periods.
  CUSTOM,
  HOUR,
  DAY,
  WEEK,
  MONTH,
  QUARTER,
  YEAR
}

/// Quantity being aggregated.
enum cnpMetricKind : byte {
  /// Achieved application-layer download rate.
  DOWNLOAD_THROUGHPUT,
  /// Achieved application-layer upload rate.
  UPLOAD_THROUGHPUT,
  /// Round-trip time on an otherwise unloaded path.
  LATENCY_IDLE,
  /// Round-trip time measured while the download test saturates the path.
  LATENCY_LOADED_DOWNLOAD,
  /// Round-trip time measured while the upload test saturates the path.
  LATENCY_LOADED_UPLOAD,
  /// Variation in inter-packet arrival time.
  JITTER,
  /// Fraction of packets lost.
  PACKET_LOSS,
  /// Fraction of the window in which the service was usable.
  AVAILABILITY,
  /// Fraction of the terminal's sky view blocked by terrain or structures.
  OBSTRUCTION,
  /// Round-trip time where the source does not distinguish loaded from idle.
  RTT,
  /// The source publishes a quantity none of the above names.
  /// SOURCE_METRIC_NAME is then required to be non-empty.
  OTHER
}

/// Statistical reduction a single number expresses.
///
/// Named `cnpReduction`, not `cnpStatistic`, so it can never differ from the
/// `CNPStatistic` table by case alone in any generated language tree.
enum cnpReduction : byte {
  MEAN,
  MEDIAN,
  /// PERCENTILE_RANK carries which one.
  PERCENTILE,
  MINIMUM,
  MAXIMUM,
  STANDARD_DEVIATION,
  /// Number of observations, not a value of the metric.
  COUNT
}

/// How the underlying observations were produced.
enum cnpMethod : byte {
  /// NDT7 network-diagnostic protocol measurement.
  NDT7,
  /// A speed test other than NDT7 — a third-party measurement platform, a
  /// CDN-operated test, or an operator-native test.
  SPEED_TEST,
  /// ICMP or UDP echo.
  PING,
  /// Path trace.
  TRACEROUTE,
  /// Telemetry read from the user terminal itself.
  TERMINAL_TELEMETRY,
  /// Bulk HTTP transfer.
  HTTP_DOWNLOAD,
  /// Passive observation of production traffic.
  PASSIVE,
  /// Modelled or simulated rather than measured. A modelled value is not a
  /// measurement and this member is how a consumer refuses to treat it as one.
  MODELED,
  /// The source states a method none of the above names.
  OTHER
}

/// Geography an aggregate is keyed to.
///
/// A separate table so an absent REGION means "the source did not key by
/// geography", which is different from GLOBAL ("the source aggregated across
/// all geographies") and different again from an empty CODE.
table CNPRegion {
  /// Granularity of CODE.
  KIND: cnpRegionKind = OTHER;
  /// The region key, verbatim from the source in the coding scheme KIND
  /// names. Never re-coded between schemes on ingest.
  CODE: string;
  /// Human-readable region name as the source publishes it. Joins to
  /// $CTR for country identity when KIND is COUNTRY.
  NAME: string;
}

/// Where one metric came from and under what terms it may be republished.
table CNPProvenance {
  /// Name of the organization or programme publishing the underlying
  /// measurements, carried verbatim as that publisher states it.
  SOURCE: string (required);
  /// URL of the dataset, endpoint or landing page.
  SOURCE_URL: string;
  /// Dataset, table or API path queried, verbatim, e.g. a fully qualified
  /// warehouse table name or a REST route.
  SOURCE_DATASET: string;
  /// The exact query or request that produced these numbers, so the
  /// aggregate can be replayed rather than trusted.
  SOURCE_QUERY: string;
  /// Source's own identifier for the returned batch, when it issues one.
  SOURCE_RECORD_ID: string;
  /// SHA-256 of the raw source bytes this aggregate was computed from,
  /// lowercase hex.
  SOURCE_SHA256: string;
  /// ISO 8601 UTC time the source was queried.
  RETRIEVED_AT: string;
  /// How the underlying observations were produced.
  METHOD: cnpMethod = OTHER;
  /// Measurement server, vantage point or probe set, when the source names
  /// one. A throughput number without a vantage is not comparable to one
  /// with a different vantage.
  MEASUREMENT_SERVER: string;
  /// SPDX identifier when the source states one, otherwise the licence name
  /// verbatim. EMPTY MEANS UNKNOWN TERMS — never public domain, and never a
  /// grant to republish.
  LICENSE: string;
  /// URL of the licence text.
  LICENSE_URL: string;
  /// Attribution string the licence requires this record and every derived
  /// product to carry downstream.
  ATTRIBUTION: string;
  /// True when the licence forbids commercial use (e.g. CC BY-NC 4.0). A
  /// consumer building a paid surface MUST honour this flag; it is carried
  /// per-source because one $CNP may mix a CC0 lane with a CC BY-NC
  /// cross-check.
  NON_COMMERCIAL_ONLY: bool;
}

/// One number drawn from a metric's distribution.
table CNPStatistic {
  /// Which reduction this number is.
  STATISTIC: cnpReduction = MEAN;
  /// Percentile rank in 0..100 when STATISTIC is PERCENTILE. Meaningless
  /// otherwise and MUST NOT be set.
  PERCENTILE_RANK: double;
  /// The number, expressed in the parent metric's UNITS.
  VALUE: double;
}

/// One aggregated quantity for the parent record's key.
///
/// A metric is a DISTRIBUTION, not a scalar. There is deliberately no
/// `VALUE: double` on this table: a source that publishes only a median
/// encodes exactly one CNPStatistic with STATISTIC MEDIAN, and a consumer can
/// then never mistake it for a mean.
table CNPMetric {
  /// Quantity aggregated.
  KIND: cnpMetricKind = OTHER;
  /// The source's own name for this metric, verbatim. REQUIRED to be
  /// non-empty when KIND is OTHER; recommended always, because it is what
  /// makes the mapping auditable.
  SOURCE_METRIC_NAME: string;
  /// Units of every VALUE under STATISTICS. NORMATIVE and required: "Mbps",
  /// "kbps", "ms", "percent", "fraction", "count". Units are never silently
  /// converted on ingest; a source publishing kbps encodes kbps.
  UNITS: string (required);
  /// The distribution. At least one entry; a metric with none is malformed.
  STATISTICS: [CNPStatistic];
  /// Number of individual measurements aggregated. 0 means the source did
  /// not publish a sample count — it never means zero measurements.
  SAMPLE_COUNT: uint64;
  /// Number of distinct clients, terminals or probes contributing. 0 means
  /// unpublished.
  CLIENT_COUNT: uint64;
  /// Where this metric came from and under what terms.
  PROVENANCE: CNPProvenance (required);
}

/// Constellation Network Performance.
///
/// Aggregated throughput, latency and availability for one satellite
/// constellation's user network, keyed by CONSTELLATION, ASN, REGION and a
/// closed time window. Built for a broadband LEO consumer-terminal lane
/// (one operator ASN measured via NDT7) and shaped so any operator — another
/// LEO constellation, a GEO VSAT provider — or a terrestrial ASN used as a
/// baseline fits the same record.
///
/// KEY, NOT MEASUREMENT. One $CNP is an AGGREGATE over a window. It is not a
/// speed test, not a single client's result, and not a per-satellite link
/// state: $LKS carries the instantaneous state and data rate of ONE named
/// link between two endpoints, and no $LKS can express "the p50 download rate
/// observed by 41,000 terminals in Germany during July".
///
/// NEVER-INVENT-DATA IS ENFORCED BY THE SHAPE. A quantity exists only as a
/// CNPMetric, and CNPMetric carries `UNITS: string (required)` and
/// `PROVENANCE: CNPProvenance (required)`, so there is no encoding for a
/// number that does not state its unit and name its source, query,
/// retrieval time, method and licence. A metric the source did not publish is
/// ABSENT — never zero. `SOURCES` lists every provider consulted for this key,
/// including ones that returned nothing, so a consumer can distinguish "not
/// looked for" from "looked for and empty".
///
/// LICENCE RIDES PER SOURCE. `CNPProvenance.NON_COMMERCIAL_ONLY` exists
/// because a single record may legitimately carry a CC0 open-measurement lane
/// beside a CC BY-NC cross-check from a restricted publisher; the restriction
/// attaches to the metric that inherited it, never to the record as a whole.
table CNP {
  /// Stable identifier for this record.
  ID: string;
  /// Constellation or network name, carried verbatim as its operator states
  /// it. Empty when the record is a terrestrial baseline. Joins to
  /// $LKS.CONSTELLATION and to $CAT by the same name.
  CONSTELLATION: string;
  /// Operating company, when it differs usefully from CONSTELLATION.
  OPERATOR: string;
  /// Autonomous system number of the measured client network, as allocated in
  /// the public routing registry. 0 means the aggregate is not keyed by ASN;
  /// AS 0 is reserved and is never a real measurement key.
  ASN: uint32;
  /// Autonomous system name as the routing registry publishes it.
  AS_NAME: string;
  /// Service tier the source distinguishes, verbatim ("Residential",
  /// "Roam", "Business", "Maritime"). Empty when the source does not
  /// separate tiers — never guessed from the throughput.
  SERVICE_TIER: string;
  /// Geography this aggregate is keyed to. Absent when the source published
  /// no geographic key at all.
  REGION: CNPRegion;
  /// ISO 8601 UTC inclusive start of the aggregation window.
  WINDOW_START: string;
  /// ISO 8601 UTC exclusive end of the aggregation window.
  WINDOW_STOP: string;
  /// Calendar span the window represents.
  AGGREGATION_PERIOD: cnpPeriod = CUSTOM;
  /// The aggregated quantities.
  METRICS: [CNPMetric];
  /// Every source consulted for this key, including those that returned no
  /// metric.
  SOURCES: [CNPProvenance];
  /// ISO 8601 UTC creation time of this record.
  CREATED_AT: string;
  /// ISO 8601 UTC last-update time of this record.
  UPDATED_AT: string;
  /// CID of the $CNP this record replaces when a source restates a window.
  SUPERSEDES_CNP_CID: string;
}

root_type CNP;
file_identifier "$CNP";

CAT.IDL:
// Hash: ca31386aeea83a2033af7c01248dcff7251e14618cd0d08147a0a9839f778619
// Version: 1.0.4
// -----------------------------------END_HEADER
include "../PLD/main.fbs";
include "../LCC/main.fbs";

// Field layout follows the public satellite-catalog fixed-width format.

enum spaceObjectClass: byte {
  /// 0
  PAYLOAD,
  /// 1
  ROCKET_BODY,
  /// 2
  DEBRIS,
  /// 3
  UNKNOWN
}

enum operationalState: byte {
  /// +
  OPERATIONAL,
  /// -
  NONOPERATIONAL,
  /// P
  PARTIALLY_OPERATIONAL,
  /// B
  BACKUP_STANDBY,
  /// S
  SPARE,
  /// X
  EXTENDED_MISSION,
  /// D
  DECAYED,
  /// ?
  UNKNOWN
}

enum dataAvailability: byte {
  /// NCE
  NO_CURRENT_ELEMENTS,
  /// NIE
  NO_INITIAL_ELEMENTS,
  /// NEA
  NO_ELEMENTS_AVAILABLE,
  /// OK
  OK
}

enum orbitRegime: byte {
  /// 0
  ORBIT,
  /// 1
  LANDING,
  /// 2
  IMPACT,
  /// 3
  DOCKED,
  /// 4
  ROUNDTRIP
}

enum massCategory: byte {
  DRY,
  WET
}

/// Catalog Entity Message
table CAT {
  /// Satellite Name(s)
  OBJECT_NAME: string;
  /// International Designator (YYYY-NNNAAA)
  OBJECT_ID: string;
  /// NORAD Catalog Number
  NORAD_CAT_ID: uint;
  /// Object type (Payload, Rocket body, Debris, Unknown)
  OBJECT_TYPE: spaceObjectClass = UNKNOWN;
  /// Operational Status Code
  OPS_STATUS_CODE: operationalState = UNKNOWN;
  /// Ownership, typically country or company
  OWNER: legacyCountryCode;
  /// Launch Date [year-month-day] (ISO 8601)
  LAUNCH_DATE: string;
  /// Launch Site
  LAUNCH_SITE: string;
  /// Decay Date, if applicable [year-month-day] (ISO 8601)
  DECAY_DATE: string;
  /// Orbital period [minutes]
  PERIOD: double;
  /// Inclination [degrees]
  INCLINATION: double;
  /// Apogee Altitude [kilometers]
  APOGEE: double;
  /// Perigee Altitude [kilometers]
  PERIGEE: double;
  /// Radar Cross Section [meters2]; blank if no data available
  RCS: double;
  /// Data status code; blank otherwise
  DATA_STATUS_CODE: dataAvailability;
  /// Orbit center
  ORBIT_CENTER: string;
  /// Orbit type (Orbit, Landing, Impact, Docked to RSO, roundtrip)
  ORBIT_TYPE: orbitRegime;
  /// Deployment Date [year-month-day] (ISO 8601)
  DEPLOYMENT_DATE: string;
  /// Indicates if the object is maneuverable
  MANEUVERABLE: bool;
  /// Size [meters]; blank if no data available
  SIZE: double;
  /// Mass [kilograms]; blank if no data available
  MASS: double;
  /// Mass type (Dry, Wet)
  MASS_TYPE: massCategory = DRY;
  /// Vector of PAYLOADS
  PAYLOADS: [PLD];
  /// Join key to the BUS record describing this object's satellite bus; holds
  /// that record's BUS.ID verbatim. MANUFACTURER, DIM_X/DIM_Y/DIM_Z, DRY_MASS
  /// and WET_MASS are properties of the bus design and live on BUS — they are
  /// NOT duplicated here. Empty when the bus is unknown.
  BUS_ID: string;
}

root_type CAT;
file_identifier "$CAT";

RFS.IDL:
// Hash: 60c5afbb891a311fa59cfd7c609aade71c4c622e08313a8feecca0694a18d5dd
// Version: 1.186.0
// -----------------------------------END_HEADER
include "../RFB/main.fbs";

// RF Surface Material (RFS)
// Description
// The electromagnetic properties of a surface at radio frequencies, attachable
// to arbitrary geometry, so an RF solver can treat a 3D object as an OBSTACLE
// with real material behaviour instead of an opaque blocker.
//
// Division of labour: `$VAM` holds the asset BYTES (glTF mesh, licence,
// review); `$OPP` holds per-object physical truth including OPTICAL specular
// and diffuse reflectivity for solar-radiation-pressure work; `$PNL` holds the
// articulated panel model with the same optical terms. NONE of them carries a
// permittivity, a conductivity, or a frequency-dependent penetration loss —
// optical reflectivity and RF constitutive parameters are different physics
// and cannot be substituted for one another. `$RFS` is that missing surface,
// and it is consumed by the obstruction, reflection, diffraction and
// scattering terms of `$RFL` and by the obstacle set of `$CVP`.
//
// REFERENCE PHYSICS. The parameterisation follows the ITU-R P.2040 treatment
// of building and natural materials: relative permittivity and conductivity
// are frequency dependent and are stated either as a power law
//
//     relative permittivity = A * f^B      conductivity [S/m] = C * f^D
//
// with f in GIGAHERTZ, or as an explicit table of per-frequency samples. Both
// forms may be present; the table wins where it covers the frequency, because
// a measurement beats a fit.
//
// EXTRAPOLATION IS FORBIDDEN. FREQUENCY_MIN_MHZ and FREQUENCY_MAX_MHZ bound
// where this record's parameters mean anything. A solver evaluating outside
// that range MUST refuse the material rather than extrapolate: the power-law
// fits diverge, and a silently extrapolated concrete wall is how a link budget
// becomes fiction.
//
// A SCALAR NEEDS ITS FREQUENCY. The single-value fields are meaningless
// without REFERENCE_FREQUENCY_MHZ, which states the frequency they were
// evaluated or measured at. A permittivity with no frequency is not a
// material property, it is a number.
//
// ABSENT IS NOT ZERO, and an unknown numeric is written NaN — the same rule
// the `$RFL`, `$ACI` and `$CVP` records carry. Zero conductivity is a real
// claim (a perfect dielectric); an omitted field reading back as 0 would make
// every unstated material a perfect dielectric.

/// Material class, in the generic building-and-natural-material vocabulary of
/// the reference physics. Capability classes only: a class is what the surface
/// IS, never who made it. A branded product name belongs in NAME or in
/// RFSProvenance.SOURCE as data, never in this enum.
///
/// ORDINALS ARE WIRE VALUES. New classes are APPENDED ONLY.
enum rfsMaterialClass : byte {
  UNSPECIFIED = 0,
  CONCRETE,
  BRICK,
  PLASTERBOARD,
  WOOD,
  GLASS,
  /// Glass treated to reflect infrared, which also attenuates RF strongly.
  COATED_GLASS,
  CEILING_BOARD,
  CHIPBOARD,
  FLOORBOARD,
  METAL,
  STONE,
  ASPHALT,
  ROOFING_TILE,
  VERY_DRY_GROUND,
  MEDIUM_DRY_GROUND,
  WET_GROUND,
  SOIL,
  SAND,
  VEGETATION,
  FRESH_WATER,
  SEA_WATER,
  ICE,
  SNOW,
  /// Fibre-reinforced polymer structure.
  COMPOSITE,
  /// Carbon-fibre structure, electrically conductive along the fibres.
  CARBON_FIBER_COMPOSITE,
  /// Multi-layer insulation blanket.
  MULTI_LAYER_INSULATION,
  SOLAR_CELL,
  /// Conductive or lossy surface coating.
  COATING,
  /// Surface engineered to absorb incident RF energy.
  ABSORBER,
  /// Frequency-selective or periodic structure whose response is not a bulk
  /// material property.
  ENGINEERED_SURFACE,
  /// The source states a material this enum cannot express. The verbatim name
  /// MUST be preserved in NAME.
  OTHER
}

/// How the surface redistributes energy it does not absorb or transmit.
enum rfsScatteringClass : byte {
  UNSPECIFIED = 0,
  /// Mirror-like; energy leaves at the reflection angle.
  SPECULAR,
  /// Energy is spread across angles.
  DIFFUSE,
  /// A specular lobe over a diffuse background.
  MIXED,
  /// Diffuse with a cosine angular distribution.
  LAMBERTIAN,
  /// Direction-dependent scattering that a single coefficient cannot describe.
  ANISOTROPIC
}

/// Polarization of the incident field, in the plane-of-incidence convention
/// reflection coefficients require. Deliberately NOT `rfPolarization`: that
/// enum describes an emitter's transmitted polarization (LHCP, LINEAR_V),
/// while a reflection coefficient is stated per transverse mode, and conflating
/// the two silently applies the wrong Fresnel coefficient.
enum rfsIncidencePolarization : byte {
  UNSPECIFIED = 0,
  /// Electric field perpendicular to the plane of incidence.
  TRANSVERSE_ELECTRIC,
  /// Electric field parallel to the plane of incidence.
  TRANSVERSE_MAGNETIC,
  CIRCULAR_LEFT,
  CIRCULAR_RIGHT,
  /// Averaged over polarization.
  UNPOLARIZED
}

/// How a property value came to exist. `CLASS_DEFAULT` exists so a value taken
/// from a published class table can be REFUSED where a measurement of THIS
/// surface is required.
enum rfsPropertyMethod : byte {
  UNSPECIFIED = 0,
  /// Measured on this surface or a coupon of its material.
  MEASURED,
  /// Computed from a physical model of the material's composition.
  MODELED,
  /// Taken from a published table for the material class, not this surface.
  CLASS_DEFAULT,
  /// Borrowed from a similar structure or bus family; visibly an
  /// approximation.
  INFERRED_FROM_FAMILY
}

/// What the material is attached to, which selects the standard it joins.
enum rfsGeometryKind : byte {
  UNSPECIFIED = 0,
  /// A mesh or material slot inside a reviewed 3D asset; joins `$VAM`.
  ASSET_MESH,
  /// A named surface of a catalogued object; joins `$OPP.OPPSurface`.
  OBJECT_SURFACE,
  /// An articulated panel; joins `$PNL`.
  PANEL,
  /// A whole catalogued object; joins `$CAT`.
  CATALOG_OBJECT,
  /// A structure at a terrestrial site; joins `$TBS`.
  SITE_STRUCTURE,
  /// A face of a building or other fixed structure.
  BUILDING_FACE,
  /// The ground or sea surface itself.
  TERRAIN_SURFACE,
  /// A primitive solved analytically rather than as a mesh.
  ANALYTIC_SHAPE
}

/// Analytic obstacle primitive, when the obstacle is not a mesh.
enum rfsAnalyticShape : byte {
  UNSPECIFIED = 0,
  PLANE,
  DISK,
  BOX,
  SPHERE,
  ELLIPSOID,
  CYLINDER,
  CONE,
  PARABOLOID,
  /// Convex hull of a point set carried by the geometry it references.
  CONVEX_HULL
}

/// The material's electromagnetic properties at ONE frequency. A table of
/// these beats the power-law fit wherever it covers the frequency.
table RFSFrequencySample {
  /// Frequency this sample is stated at, megahertz — the `$RFB` MHz
  /// convention. A join to `$IQC` (hertz) converts explicitly at the join.
  FREQUENCY_MHZ: double;
  /// Real part of the relative permittivity.
  RELATIVE_PERMITTIVITY_REAL: double;
  /// Imaginary part of the relative permittivity (loss term), stated as a
  /// POSITIVE magnitude.
  RELATIVE_PERMITTIVITY_IMAGINARY: double;
  /// Conductivity, siemens per metre.
  CONDUCTIVITY_S_PER_M: double;
  /// Loss tangent, dimensionless.
  LOSS_TANGENT: double;
  /// Real and imaginary relative permeability. 1.0 and 0.0 for non-magnetic
  /// materials — stated, not assumed.
  RELATIVE_PERMEABILITY_REAL: double;
  RELATIVE_PERMEABILITY_IMAGINARY: double;
  /// Power reflected at normal incidence as a ratio [0-1].
  REFLECTIVITY: double;
  /// Reflection loss at normal incidence, dB (positive).
  REFLECTION_LOSS_DB: double;
  /// Loss through the material at THICKNESS_M, dB (positive).
  TRANSMISSION_LOSS_DB: double;
  /// Attenuation inside the material, dB per metre.
  ATTENUATION_DB_PER_M: double;
}

/// Reflection and transmission at one incidence angle and polarization. The
/// angular dependence of a real surface cannot be carried by a single
/// normal-incidence number.
table RFSReflectionEntry {
  /// Frequency this entry is stated at, megahertz.
  FREQUENCY_MHZ: double;
  /// Angle from the surface normal, degrees [0-90).
  INCIDENCE_ANGLE_DEG: double;
  POLARIZATION: rfsIncidencePolarization = UNSPECIFIED;
  /// Magnitude of the field reflection coefficient [0-1].
  REFLECTION_COEFFICIENT_MAGNITUDE: double;
  /// Phase of the field reflection coefficient, degrees.
  REFLECTION_COEFFICIENT_PHASE_DEG: double;
  /// Reflection loss, dB (positive).
  REFLECTION_LOSS_DB: double;
  /// Loss through the material at this angle, dB (positive).
  TRANSMISSION_LOSS_DB: double;
  /// Power removed from the specular direction by surface roughness, dB.
  SCATTERING_LOSS_DB: double;
}

/// Where and what this material is attached to. A material record with no
/// geometry describes a substance; a material record WITH geometry describes
/// an obstacle a solver can intersect.
table RFSGeometryRef {
  /// Producer-stable identifier of this attachment.
  GEOMETRY_REF_ID: string (required);
  GEOMETRY_KIND: rfsGeometryKind = UNSPECIFIED;
  /// `$VAM` asset identity, copied VERBATIM including the byte hash so the
  /// material can never drift onto a different revision of the mesh.
  VAM_ID: string;
  VARIANT_ID: string;
  ASSET_SHA256: string;
  /// Mesh and primitive inside the asset.
  MESH_NAME: string;
  PRIMITIVE_INDEX: int = -1;
  /// glTF material slot the properties apply to, matching the
  /// `$OPP.OPPSurface` join fields.
  GLTF_MATERIAL_NAME: string;
  GLTF_MATERIAL_INDEX: int = -1;
  /// Explicit face indexes, when the material covers part of a mesh.
  FACE_INDEXES: [uint32];
  /// `$OPP.OPPSurface` surface identifier.
  OPP_SURFACE_ID: string;
  /// `$PNL` panel identifier.
  PANEL_ID: string;
  /// `$CAT` identity, when the obstacle is a catalogued object. 0 when
  /// unbound.
  NORAD_CAT_ID: uint;
  OBJECT_ID: string;
  /// `$TBS.SITE_ID`, when the obstacle is a structure at a terrestrial site.
  TBS_SITE_ID: string;
  /// Producer's own feature identifier for a building, wall or terrain patch.
  FEATURE_ID: string;
  /// Primitive and its dimensions in metres, when GEOMETRY_KIND is
  /// ANALYTIC_SHAPE. The dimension order is the primitive's own convention and
  /// MUST be stated in SHAPE_DIMENSION_NAMES.
  ANALYTIC_SHAPE: rfsAnalyticShape = UNSPECIFIED;
  SHAPE_DIMENSIONS_M: [double];
  SHAPE_DIMENSION_NAMES: [string];
  /// Geodetic placement of a fixed obstacle, degrees and metres. Absent for
  /// an obstacle whose position is joined from `$CAT`, `$TBS` or `$VAM`.
  LATITUDE_DEG: double;
  LONGITUDE_DEG: double;
  ALTITUDE_M: double;
  /// Height above ground of a fixed structure, metres.
  HEIGHT_M: double;
  /// Orientation of the surface normal, degrees east of north and above the
  /// horizon. A wall that faces the wrong way blocks the wrong link.
  NORMAL_AZIMUTH_DEG: double;
  NORMAL_ELEVATION_DEG: double;
}

/// Where these properties came from.
table RFSProvenance {
  METHOD: rfsPropertyMethod = UNSPECIFIED;
  /// The measurement campaign, published table or model. Required: an
  /// unattributed permittivity is not publishable.
  SOURCE: string (required);
  /// The specific table, recommendation or dataset entry within SOURCE.
  SOURCE_REFERENCE: string;
  /// Replayable query that retrieves the source value.
  SOURCE_QUERY: string;
  /// How it was measured (e.g. "free-space transmission", "coaxial probe",
  /// "resonant cavity").
  MEASUREMENT_TECHNIQUE: string;
  /// `$PLG.PLUGIN_ID` / `$PMM.MODULE_ID` that produced modelled values.
  MODULE_ID: string;
  MODULE_VERSION: string;
  MODULE_CONTENT_HASH: string;
  /// Unix ms measured and retrieved.
  MEASURED_AT: uint64;
  RETRIEVED_AT: uint64;
  /// 1-sigma uncertainty of the permittivity and conductivity values, in the
  /// units of the quantity they qualify.
  RELATIVE_PERMITTIVITY_SIGMA: double;
  CONDUCTIVITY_SIGMA_S_PER_M: double;
  /// Licence terms. Empty means UNKNOWN TERMS — never public domain, never a
  /// grant to redistribute.
  LICENSE: string;
  NON_COMMERCIAL_ONLY: bool;
  CITATION: string;
}

/// RF Surface Material
table RFS {
  /// Stable identifier of this material. Joined by
  /// `$RFL.RFLObstruction.MATERIAL_ID` and `$CVP.CVPObstacleRef.MATERIAL_ID`.
  MATERIAL_ID: string (required);
  /// Name as its source states it, verbatim.
  NAME: string;
  MATERIAL_CLASS: rfsMaterialClass = UNSPECIFIED;
  /// Free-text description of the surface, not of its vendor.
  DESCRIPTION: string;

  /// Frequency range over which this record's parameters are valid,
  /// megahertz. A solver MUST refuse to evaluate outside it rather than
  /// extrapolate.
  FREQUENCY_MIN_MHZ: double;
  FREQUENCY_MAX_MHZ: double;

  // ---- Power-law parameterisation, f in GIGAHERTZ ----
  /// relative permittivity = PERMITTIVITY_COEFFICIENT_A * f^PERMITTIVITY_EXPONENT_B
  PERMITTIVITY_COEFFICIENT_A: double;
  PERMITTIVITY_EXPONENT_B: double;
  /// conductivity [S/m] = CONDUCTIVITY_COEFFICIENT_C * f^CONDUCTIVITY_EXPONENT_D
  CONDUCTIVITY_COEFFICIENT_C: double;
  CONDUCTIVITY_EXPONENT_D: double;

  // ---- Single-frequency values ----
  /// Frequency the scalar values below are stated at, megahertz. Without it
  /// they are uninterpretable.
  REFERENCE_FREQUENCY_MHZ: double;
  RELATIVE_PERMITTIVITY_REAL: double;
  /// Loss term, stated as a POSITIVE magnitude.
  RELATIVE_PERMITTIVITY_IMAGINARY: double;
  CONDUCTIVITY_S_PER_M: double;
  LOSS_TANGENT: double;
  /// 1.0 and 0.0 for non-magnetic materials — stated, not assumed.
  RELATIVE_PERMEABILITY_REAL: double;
  RELATIVE_PERMEABILITY_IMAGINARY: double;

  // ---- Bulk response ----
  /// Power reflected at normal incidence as a ratio [0-1].
  REFLECTIVITY: double;
  /// Reflection loss at normal incidence, dB (positive).
  REFLECTION_LOSS_DB: double;
  /// Thickness the transmission and penetration losses are stated for, metres.
  /// A transmission loss without a thickness cannot be rescaled.
  THICKNESS_M: double;
  /// Loss through THICKNESS_M at normal incidence, dB (positive).
  TRANSMISSION_LOSS_DB: double;
  /// Attenuation inside the material, dB per metre.
  ATTENUATION_DB_PER_M: double;
  /// Fraction of incident power absorbed at normal incidence [0-1].
  ABSORPTION_COEFFICIENT: double;

  // ---- Surface ----
  /// RMS surface roughness, metres. Roughness is what decides whether a
  /// surface is a mirror or a scatterer at a given wavelength.
  SURFACE_ROUGHNESS_RMS_M: double;
  /// Correlation length of the roughness, metres.
  ROUGHNESS_CORRELATION_LENGTH_M: double;
  SCATTERING_CLASS: rfsScatteringClass = UNSPECIFIED;
  /// Fraction of non-absorbed power leaving diffusely [0-1].
  DIFFUSE_SCATTERING_COEFFICIENT: double;
  /// Backscatter coefficient, dB.
  BACKSCATTER_COEFFICIENT_DB: double;

  // ---- Conditions the values hold at ----
  /// Temperature the properties were evaluated at, kelvin.
  TEMPERATURE_K: double;
  /// Volumetric moisture content [0-1]. Wet concrete and dry concrete are
  /// different materials at RF.
  MOISTURE_CONTENT_FRACTION: double;
  /// Salinity, practical salinity units, for water surfaces.
  SALINITY_PSU: double;

  // ---- Tabulated detail ----
  /// Per-frequency samples. Where present and covering the frequency, these
  /// take precedence over the power law.
  FREQUENCY_SAMPLES: [RFSFrequencySample];
  /// Angular and polarization dependence.
  REFLECTION_TABLE: [RFSReflectionEntry];

  /// Geometry this material is attached to. A record may attach one material
  /// to several obstacles.
  GEOMETRY: [RFSGeometryRef];

  /// Provenance. Required.
  PROVENANCE: RFSProvenance (required);
  /// Unix ms this record was serialized.
  COMPUTED_AT: uint64;
  /// `$EPM` identifier of the producing node.
  PRODUCER_ID: string;
  /// Ed25519 signature by the producing `$EPM`.
  SIGNATURE: [ubyte];
}

root_type RFS;
file_identifier "$RFS";

