  /// Time difference of arrival (seconds)
  TDOA:double;
  /// TDOA uncertainty (seconds, 1-sigma)
  TDOA_UNC:double;
  /// Frequency difference of arrival (Hz)
  FDOA:double;
  /// FDOA uncertainty (Hz, 1-sigma)
  FDOA_UNC:double;
  /// Reference to raw data file
  RAW_FILE_URI:string;
  /// Event descriptor
  DESCRIPTOR:string;
  /// Associated tags
  TAGS:[string];
}

root_type DOA;
file_identifier "$DOA";

SBM.IDL:
// Hash: d87c836ec91004f3fbe4b79da4ad9c2473c15f5a0cdaa51c2314a13c868833e8
// Version: 1.169.0
// -----------------------------------END_HEADER
/// Breakup event type. Selects the NASA Standard Satellite Breakup Model
/// (SSBM) branch used to generate the fragment population.
/// Append new values only; never reorder or reuse existing values.
enum sbmEventType : byte {
  UNKNOWN,
  EXPLOSION,
  COLLISION
}

/// Parent object class. Selects the SSBM characteristic-length distribution
/// coefficients; spacecraft and rocket bodies fragment differently.
/// Append new values only; never reorder or reuse existing values.
enum sbmObjectClass : byte {
  UNKNOWN,
  SPACECRAFT,
  ROCKET_BODY
}

/// Which parent body a fragment was generated from. Always TARGET for an
/// EXPLOSION event; a COLLISION population carries fragments from both bodies.
/// Append new values only; never reorder or reuse existing values.
enum sbmFragmentOrigin : byte {
  UNKNOWN,
  TARGET,
  IMPACTOR
}

/// One debris fragment produced by a breakup event.
///
/// Vector components are expressed in the parent SBM.REF_FRAME axes.
/// Position and velocity are the fragment's state at SBM.EPOCH, i.e. the
/// parent state plus the ejection delta-V, before any propagation.
table sbmFragment {
  /// Which parent body this fragment came from.
  ORIGIN:sbmFragmentOrigin;
  /// Characteristic length L_c in meters.
  L_C_M:double;
  /// Area-to-mass ratio in square meters per kilogram.
  AM_RATIO_M2_PER_KG:double;
  /// Average cross-sectional area in square meters.
  AREA_M2:double;
  /// Fragment mass in kilograms.
  MASS_KG:double;
  /// Magnitude of the ejection delta-V in meters per second.
  DELTA_V_MAG_M_PER_S:double;
  /// Ejection delta-V X component in meters per second.
  DELTA_V_X_M_PER_S:double;
  /// Ejection delta-V Y component in meters per second.
  DELTA_V_Y_M_PER_S:double;
  /// Ejection delta-V Z component in meters per second.
  DELTA_V_Z_M_PER_S:double;
  /// Fragment position X component in kilometers.
  POSITION_X_KM:double;
  /// Fragment position Y component in kilometers.
  POSITION_Y_KM:double;
  /// Fragment position Z component in kilometers.
  POSITION_Z_KM:double;
  /// Fragment velocity X component in kilometers per second.
  VELOCITY_X_KM_PER_S:double;
  /// Fragment velocity Y component in kilometers per second.
  VELOCITY_Y_KM_PER_S:double;
  /// Fragment velocity Z component in kilometers per second.
  VELOCITY_Z_KM_PER_S:double;
}

/// Satellite Breakup Model
///
/// One SBM record is a single on-orbit fragmentation event — an explosion or
/// a collision — together with the debris population a breakup model produced
/// for it. It carries the model inputs (parent states, masses, relative
/// velocity, object class, cutoff, seed) so the population is reproducible,
/// and the resulting fragments in FRAGMENTS.
///
/// Units on the wire: parent and fragment position are KILOMETERS, parent and
/// fragment velocity are KILOMETERS PER SECOND (matching $OMM, $OEM, $OCM and
/// $CDM state conventions); ejection delta-V, relative velocity and
/// characteristic length are METERS PER SECOND and METERS respectively
/// (matching the breakup-model literature). Every field name states its unit.
///
/// This record describes an ON-ORBIT breakup. Atmospheric reentry breakup and
/// demise stay in $RDM/$REM; a business-loss classification of the event stays
/// in $OOE.
table SBM {
  /// Producer-defined message identifier.
  MESSAGE_ID:string;
  /// Message creation date in ISO 8601 UTC format.
  CREATION_DATE:string;
  /// Creating agency, application, or service.
  ORIGINATOR:string;
  /// Breakup event type.
  EVENT_TYPE:sbmEventType;
  /// Parent object class used to select model coefficients.
  OBJECT_CLASS:sbmObjectClass;
  /// Event epoch in ISO 8601 UTC format. Fragment states are given at this
  /// epoch.
  EPOCH:string;
  /// Time system used by all epochs.
  TIME_SYSTEM:string;
  /// Reference frame for all position, velocity and delta-V components.
  REF_FRAME:string;
  /// Target object name.
  OBJECT_NAME:string;
  /// Target international designator or producer object identifier.
  OBJECT_ID:string;
  /// Target satellite catalog number. Joins to CAT.NORAD_CAT_ID and
  /// OMM.NORAD_CAT_ID. 0 when unbound.
  NORAD_CAT_ID:uint;
  /// Impactor object name. COLLISION events only.
  IMPACTOR_OBJECT_NAME:string;
  /// Impactor satellite catalog number. COLLISION events only. 0 when unbound.
  IMPACTOR_NORAD_CAT_ID:uint;
  /// Target mass in kilograms.
  TARGET_MASS_KG:double;
  /// Target characteristic length in meters.
  TARGET_L_C_M:double;
  /// Impactor mass in kilograms. COLLISION events only.
  IMPACTOR_MASS_KG:double;
  /// Impactor characteristic length in meters. COLLISION events only.
  IMPACTOR_L_C_M:double;
  /// Collision relative velocity in meters per second. COLLISION events only.
  RELATIVE_VELOCITY_M_PER_S:double;
  /// True when the collision energy-to-mass ratio met the catastrophic
  /// threshold and both bodies were fully fragmented.
  CATASTROPHIC:bool;
  /// Parent position X component in kilometers at EPOCH.
  PARENT_POSITION_X_KM:double;
  /// Parent position Y component in kilometers at EPOCH.
  PARENT_POSITION_Y_KM:double;
  /// Parent position Z component in kilometers at EPOCH.
  PARENT_POSITION_Z_KM:double;
  /// Parent velocity X component in kilometers per second at EPOCH.
  PARENT_VELOCITY_X_KM_PER_S:double;
  /// Parent velocity Y component in kilometers per second at EPOCH.
  PARENT_VELOCITY_Y_KM_PER_S:double;
  /// Parent velocity Z component in kilometers per second at EPOCH.
  PARENT_VELOCITY_Z_KM_PER_S:double;
  /// Lower characteristic-length cutoff in meters. Fragments smaller than
  /// this were not generated.
  MIN_LC_M:double;
  /// Random number generator seed. A producer that reports the same
  /// MODEL_NAME, MODEL_VERSION, inputs and SEED must reproduce FRAGMENTS
  /// exactly.
  SEED:uint32;
  /// Breakup model name, e.g. "NASA_SSBM".
  MODEL_NAME:string;
  /// Breakup model implementation version.
  MODEL_VERSION:string;
  /// Number of fragments generated. Equals the length of FRAGMENTS when the
  /// population is carried in this record.
  FRAGMENT_COUNT:uint;
  /// Total parent mass fed to the model in kilograms.
  INPUT_MASS_KG:double;
  /// Total mass carried by the generated fragments in kilograms.
  OUTPUT_MASS_KG:double;
  /// Generated fragment population.
  FRAGMENTS:[sbmFragment];
  /// Free-form model assumptions or limitations.
  ASSUMPTIONS:[string];
  /// Additional comments.
  COMMENT:string;
}

root_type SBM;
file_identifier "$SBM";

NCD.IDL:
// Hash: 69f45a0409d81a1d57267d3667a42f1733091ffa7f779b3c6778080783a376c5
// Version: 0.0.1
// -----------------------------------END_HEADER
/// Native container format class.
///
/// These are FORMAT designations, not products: each names a published or
/// widely implemented container layout, and a capability description states
/// what the layout can express. Reserve 0 so an unset byte never decodes as a
/// real format. Append new members only; never reorder or reuse a value.
enum ncdContainerFormat : ubyte {
  UNSPECIFIED = 0,

  /// Double-precision Array File container carrying Spacecraft and Planet
  /// Kernel segments: a binary file of typed, independently addressed
  /// ephemeris segments, each with an integer target and centre, an integer
  /// reference frame, a numeric segment type, and a contiguous address range
  /// inside the file.
  SPK_DAF = 1,

  /// SP3 version c: fixed-column text container of per-epoch satellite
  /// positions and optional velocities with a clock column, a header block of
  /// accuracy codes, and one uniform epoch interval.
  SP3_C = 2,

  /// SP3 version d: as SP3_C, with an unbounded satellite count and extended
  /// header lines.
  SP3_D = 3,

  /// Code-500 fixed-record binary ephemeris: a header record of packed words
  /// followed by fixed-length data records on a uniform step.
  CODE_500 = 4,

  /// Scenario-epoch ephemeris text container: time-ordered position and
  /// velocity records whose epochs are offsets in seconds from a declared
  /// scenario epoch, qualified by a named coordinate system, a distance unit,
  /// a named interpolation method and an interpolation order.
  SCENARIO_EPOCH_EPHEMERIS_TEXT = 5,

  /// Scenario-epoch attitude text container: the attitude counterpart of
  /// SCENARIO_EPOCH_EPHEMERIS_TEXT, carrying quaternion, Euler or angular
  /// velocity records against the same scenario epoch.
  SCENARIO_EPOCH_ATTITUDE_TEXT = 6,

  /// CCSDS Orbit Ephemeris Message, keyword-value notation.
  CCSDS_OEM_KVN = 7,
  /// CCSDS Orbit Ephemeris Message, XML.
  CCSDS_OEM_XML = 8,
  /// CCSDS Attitude Ephemeris Message, keyword-value notation.
  CCSDS_AEM_KVN = 9,
  /// CCSDS Attitude Ephemeris Message, XML.
  CCSDS_AEM_XML = 10,
  /// CCSDS Tracking Data Message, keyword-value notation.
  CCSDS_TDM_KVN = 11,
  /// CCSDS Tracking Data Message, XML.
  CCSDS_TDM_XML = 12,

  /// A container outside this roster. PROVIDER_DEFINED_FORMAT_NAME states
  /// which; a producer never reuses a neighbouring member instead.
  PROVIDER_DEFINED = 255,
}

/// One independently addressed segment inside a native container.
///
/// A segmented binary ephemeris is not a single span: each segment has its own
/// body pair, frame, numeric type and time bounds, and a reader must choose
/// among them. $OEM carries the STATES; this carries the segment DESCRIPTOR
/// that says which states came from where and what must be written back.
table NCDSegmentDescriptor {
  /// Segment name as recorded in the container.
  NAME: string;
  /// Integer body code of the segment target.
  TARGET_NAIF_ID: int;
  /// Integer body code of the segment centre.
  CENTER_NAIF_ID: int;
  /// Integer reference frame code of the segment.
  FRAME_NAIF_ID: int;
  /// Reference frame name as recorded in the container.
  FRAME_NAME: string;
  /// Numeric segment data type, verbatim. The evaluation rule is a property of
  /// this number (for example, Chebyshev position with fixed interval, or
  /// discrete states with Lagrange interpolation); it is carried as the
  /// container's own integer so a rewrite is exact.
  SEGMENT_TYPE: int;
  /// Segment coverage start, ISO 8601.
  START_EPOCH: string;
  /// Segment coverage stop, ISO 8601.
  STOP_EPOCH: string;
  /// Segment coverage start, seconds past J2000 in the barycentric dynamical
  /// time scale, as stored in the container.
  START_SECONDS_PAST_J2000_TDB: double;
  /// Segment coverage stop, same scale.
  STOP_SECONDS_PAST_J2000_TDB: double;
  /// First addressed element of the segment inside the file.
  INITIAL_ADDRESS: ulong;
  /// Last addressed element of the segment inside the file.
  FINAL_ADDRESS: ulong;
  /// Polynomial degree or record size the segment type parameterises, when the
  /// type carries one.
  POLYNOMIAL_DEGREE: uint;
}

/// Header block of a fixed-column satellite position container (SP3).
table NCDSP3Header {
  /// Record content indicator, e.g. "P" for positions only, "V" with
  /// velocities.
  FILE_TYPE: string;
  /// Satellite system indicator recorded in the header.
  SATELLITE_SYSTEM: string;
  /// Orbit type as recorded, e.g. fitted, extrapolated, broadcast, helmert.
  ORBIT_TYPE: string;
  /// Data used to produce the file, as recorded.
  DATA_USED: string;
  /// Terrestrial reference frame name as recorded.
  COORDINATE_SYSTEM: string;
  /// Producing agency as recorded IN THE FILE. This is observed content, not a
  /// classification.
  AGENCY: string;
  /// Time system as recorded in the header.
  TIME_SYSTEM: string;
  /// Week number of the first epoch in the file's own week counter.
  GPS_WEEK: uint;
  /// Seconds of week of the first epoch.
  SECONDS_OF_WEEK: double;
  /// Modified Julian Day of the first epoch.
  MODIFIED_JULIAN_DAY_START: int;
  /// Fractional day of the first epoch.
  FRACTIONAL_DAY: double;
  /// Uniform interval between epochs, seconds.
  EPOCH_INTERVAL_SECONDS: double;
  /// Number of epochs declared in the header.
  NUMBER_OF_EPOCHS: uint;
  /// Satellite identifiers in header order.
  SATELLITE_IDS: [string];
  /// Per-satellite accuracy exponents, parallel to SATELLITE_IDS. The accuracy
  /// is POSITION_VELOCITY_BASE raised to this power.
  SATELLITE_ACCURACY_EXPONENTS: [int8];
  /// Base for the position and velocity standard-deviation exponents carried
  /// per state in $OEM.
  POSITION_VELOCITY_BASE: double;
  /// Base for the clock bias and clock rate standard-deviation exponents.
  CLOCK_RATE_BASE: double;
  /// Header comment lines in file order.
  COMMENT: [string];
}

/// Parameters of a scenario-epoch text container.
table NCDScenarioEpochContainer {
  /// Epoch that every record offset is measured from, ISO 8601.
  SCENARIO_EPOCH: string;
  /// Time scale the scenario epoch is expressed in.
  TIME_SYSTEM: string;
  /// Distance unit of the records, e.g. "Meters", "Kilometers".
  DISTANCE_UNIT: string;
  /// Named coordinate system of the records.
  COORDINATE_SYSTEM: string;
  /// Named coordinate axes, when stated separately from the system.
  COORDINATE_AXES: string;
  /// Central body of the records.
  CENTRAL_BODY: string;
  /// Named interpolation method, e.g. "Lagrange", "Hermite".
  INTERPOLATION_METHOD: string;
  /// Interpolation order expressed as (samples - 1), which is how these
  /// containers state it. Carried verbatim rather than converted, so a rewrite
  /// reproduces the source exactly.
  INTERPOLATION_SAMPLES_M1: uint;
  /// Number of ephemeris points declared in the container.
  NUMBER_OF_EPHEMERIS_POINTS: uint;
  /// Segment boundary offsets in seconds from SCENARIO_EPOCH, when present.
  SEGMENT_BOUNDARY_TIMES: [double];
}

/// Header words of a fixed-record binary ephemeris container.
table NCDCode500Header {
  /// Object name as recorded in the header.
  SATELLITE_NAME: string;
  /// Container-internal tape or file identifier.
  TAPE_ID: string;
  /// Time system indicator as recorded.
  TIME_SYSTEM_INDICATOR: string;
  /// Coordinate system indicator as recorded.
  COORDINATE_SYSTEM_INDICATOR: int;
  /// Coverage start, ISO 8601.
  START_EPOCH: string;
  /// Coverage stop, ISO 8601.
  STOP_EPOCH: string;
  /// Uniform step between data records, seconds.
  EPOCH_STEP_SECONDS: double;
  /// The header record's packed words in file order, undecoded. A reader that
  /// understands a word decodes it; a rewriter reproduces the record exactly
  /// without having to.
  HEADER_WORDS: [double];
}

/// Native Container Descriptor.
///
/// The file-level facts of an ephemeris, attitude or tracking container that
/// are NOT properties of the messages inside it. $OEM, $AEM and $TDM carry the
/// states, attitudes and observations; none of them can carry the internal
/// file name, the comment area, the segment address ranges, the header accuracy
/// block or the interpolation order the source declared, because those describe
/// the CONTAINER. Without them a read-then-write cycle silently invents header
/// values, and a segmented binary file cannot be reproduced at all.
///
/// ONE record covers every container class rather than one record per format:
/// the file-level facts are the same kind of fact in each, and the
/// format-specific blocks are optional sub-tables selected by FORMAT. Only the
/// block matching FORMAT is populated.
table NCD {
  /// Container format class.
  FORMAT: ncdContainerFormat = UNSPECIFIED;
  /// Format name when FORMAT is PROVIDER_DEFINED. Empty otherwise.
  PROVIDER_DEFINED_FORMAT_NAME: string;
  /// Version of the container format as declared by the file itself.
  FORMAT_VERSION: string;

  /// Producing system or organization as recorded IN THE FILE.
  PRODUCER: string;
  /// Creation date recorded in the file, ISO 8601.
  CREATION_DATE: string;
  /// Originator recorded in the file.
  ORIGINATOR: string;

  /// Container-internal file name, which is stored inside the file and is
  /// independent of the name on disk.
  INTERNAL_FILE_NAME: string;
  /// Free-text comment area carried inside the container, one entry per line,
  /// in file order.
  COMMENT_AREA: [string];

  /// Reference frame name as the container itself spells it, before any
  /// mapping onto $RFM.
  NATIVE_FRAME_NAME: string;
  /// Integer reference frame code as the container stores it.
  NATIVE_FRAME_ID: int;
  /// Time system as the container itself spells it, before any mapping onto
  /// the ratified time-scale vocabulary.
  NATIVE_TIME_SYSTEM: string;

  /// Descriptors of the container's segments, in file order. Empty for a
  /// single-span container.
  SEGMENTS: [NCDSegmentDescriptor];

  /// Header block when FORMAT is SP3_C or SP3_D.
  SP3_HEADER: NCDSP3Header;
  /// Parameters when FORMAT is SCENARIO_EPOCH_EPHEMERIS_TEXT or
  /// SCENARIO_EPOCH_ATTITUDE_TEXT.
  SCENARIO_CONTAINER: NCDScenarioEpochContainer;
  /// Header words when FORMAT is CODE_500.
  CODE_500_HEADER: NCDCode500Header;

  /// Total coverage start across all segments, ISO 8601.
  START_TIME: string;
  /// Total coverage stop across all segments, ISO 8601.
  STOP_TIME: string;

  /// Length of the described container in bytes.
  SOURCE_BYTE_LENGTH: ulong;
  /// SHA-256 of the described container's exact bytes, lowercase hex. This is
  /// what makes the descriptor checkable: a consumer can prove the descriptor
  /// belongs to the file it holds.
  SOURCE_SHA256: string;
  /// Content identifier of the described container when it is addressed by
  /// content rather than by path.
  SOURCE_CID: string;
}

root_type NCD;
file_identifier "$NCD";

GST.IDL:
// Hash: 873e99b02f3f229a2dc2cc48e8276a8b48dea055baa562b122f146f388603660
// Version: 1.166.0
// -----------------------------------END_HEADER
/// Network a tracking station belongs to. Append new values only; never
/// reorder or reuse existing values.
enum gstNetwork : ubyte {
  UNSPECIFIED = 0,
  /// NASA Deep Space Network.
  DSN = 1,
  /// ESA tracking station network.
  ESTRACK = 2,
  /// European VLBI Network.
  EVN = 3,
  /// International Laser Ranging Service.
  ILRS = 4,
  /// International GNSS Service.
  IGS = 5,
  /// A network not covered above.
  OTHER = 6
}

/// Terrestrial reference frame realization the station coordinates are given
/// in. A position without its realization is not usable at the centimetre
/// level. Append new values only.
enum gstFrameRealization : ubyte {
  UNSPECIFIED = 0,
  ITRF93 = 1,
  ITRF2000 = 2,
  ITRF2005 = 3,
  ITRF2008 = 4,
  ITRF2014 = 5,
  ITRF2020 = 6,
  /// A realization not covered above; name it in FRAME_REALIZATION_NAME.
  OTHER = 7
}

/// Antenna mount geometry, which determines how the axis offset is applied.
/// Append new values only.
enum gstAntennaAxisType : ubyte {
  UNSPECIFIED = 0,
  AZ_EL = 1,
  X_Y_EAST = 2,
  X_Y_NORTH = 3,
  HA_DEC = 4,
  /// Fixed / non-steerable.
  FIXED = 5,
  OTHER = 6
}

/// Ground/Tracking Station Definition — the geodetic identity and geometry of
/// one tracking station, sufficient to reduce a radiometric or laser
/// observation taken from it.
///
/// This is deliberately NOT $SEN. $SEN describes an SSA sensor site by
/// latitude/longitude/altitude with tasking plans and statistics; it carries no
/// terrestrial frame realization, no station velocity, no reference epoch, and
/// no antenna axis geometry. Station coordinates without a frame realization
/// and an epoch cannot be propagated for plate motion and are therefore not
/// usable for orbit determination.
table GST {
  /// Stable station identifier as used by the operating network, e.g. "DSS-63".
  STATION_ID: string (required);

  /// Human-readable station name.
  NAME: string;

  /// Operating network.
  NETWORK: gstNetwork = UNSPECIFIED;

  /// IERS DOMES number, when the station has one.
  DOMES_NUMBER: string;

  /// NASA CDP / SLR site number, when the station has one.
  CDP_NUMBER: string;

  /// Terrestrial reference frame realization of POSITION_* and VELOCITY_*.
  FRAME_REALIZATION: gstFrameRealization = UNSPECIFIED;

  /// Free-text realization name, required when FRAME_REALIZATION is OTHER.
  FRAME_REALIZATION_NAME: string;

  /// Epoch at which POSITION_* is valid, ISO 8601. Positions MUST be
  /// propagated to the observation epoch with VELOCITY_* before use.
  REFERENCE_EPOCH: string;

  /// Station position in the stated realization, metres.
  POSITION_X: double;
  POSITION_Y: double;
  POSITION_Z: double;

  /// Station velocity (plate motion) in the stated realization, metres per
  /// year. Zero is a claim that the station does not move, not a default.
  VELOCITY_X: double;
  VELOCITY_Y: double;
  VELOCITY_Z: double;

  /// 1-sigma position uncertainty, metres.
  POSITION_SIGMA_X: double;
  POSITION_SIGMA_Y: double;
  POSITION_SIGMA_Z: double;

  /// Antenna mount geometry.
  ANTENNA_AXIS_TYPE: gstAntennaAxisType = UNSPECIFIED;

  /// Distance between the two mount axes, metres. Zero for an intersecting-axis
  /// mount.
  AXIS_OFFSET_M: double;

  /// Vector from the monument marker to the antenna reference point, metres.
  ECCENTRICITY_X: double;
  ECCENTRICITY_Y: double;
  ECCENTRICITY_Z: double;

  /// Frame the eccentricity vector is expressed in, e.g. "XYZ" (geocentric
  /// Cartesian) or "NEU" (local north-east-up).
  ECCENTRICITY_FRAME: string;

  /// Uplink bands the station can transmit, e.g. ["S", "X", "Ka"].
  TRANSMIT_BANDS: [string];

  /// Downlink bands the station can receive.
  RECEIVE_BANDS: [string];

  /// Station clock offset from the stated time scale, seconds.
  CLOCK_OFFSET_S: double;

  /// Station clock rate, seconds per second.
  CLOCK_RATE_S_PER_S: double;

  /// Time scale the clock terms are referenced to, e.g. "UTC", "TAI".
  CLOCK_TIME_SCALE: string;

  /// Start of the interval over which this definition applies, ISO 8601.
  VALID_FROM: string;

  /// End of the interval over which this definition applies, ISO 8601.
  VALID_TO: string;

  /// Provenance of these coordinates, e.g. "DSN 810-005 rev. E", an ILRS SINEX
  /// file name, or a VLBI station catalogue identifier.
  SOURCE: string;
}

root_type GST;
file_identifier "$GST";

