EPM.IDL:
// Hash: 688ce0a2c87c41154be2374ac5686d7e8c945008972fadd38a74eafdf1204388
// Version: 1.0.7
// -----------------------------------END_HEADER
enum KeyType : byte {
  Signing,
  Encryption
}

enum EntityType : byte {
  User,
  Node
}

/// Represents cryptographic key information.
///
/// The publication paradigm is "literal public keys, not derivation
/// material": a published EPM carries the PUBLIC_KEY bytes that verify
/// the record's SIGNATURE (signing) or encrypt to the entity (encryption),
/// and NOTHING about how those keys were derived. XPUB, KEY_PATH and
/// KEY_ADDRESS are PRIVATE / operational — they belong to the wallet that
/// produced the keys, never to the record a peer resolves.
///
/// Requiredness is PROFILE-ENFORCED, never a flatc `(required)` attribute:
/// a `(required)` on PUBLIC_KEY would make the flatbuffers Verifier reject
/// every pre-flip secp256k1 record that legitimately omitted it (the
/// 2026-07-27 dual-curve regime allowed xpub-derivation for secp at
/// non-hardened paths). A published record is self-describing instead —
/// PUBLIC_KEY present, XPUB/KEY_PATH/KEY_ADDRESS absent — and a conformance
/// checker asserts that profile (see scripts/check-epm-published-profile.mjs).
///
/// Rotation is by republish: a new signing or encryption key means a new
/// PUBLIC_KEY, a re-signed SIGNATURE, and a re-published EPM at the same
/// peer-addressed location. The PeerID (multihash of the libp2p identity
/// pubkey) is the stable anchor across rotations.
table CryptoKey {
  /// Public part of the cryptographic key, in hexadecimal format. AUTHORITATIVE
  /// in a published record: this is the verifying/encrypting key, and no other
  /// field yields it. Required-in-practice (profile-enforced, not flatc
  /// `(required)`) so that pre-flip secp256k1 records without it still decode.
  PUBLIC_KEY: string;
  /// Extended public key, as specified by BIP-32 (hierarchical deterministic
  /// wallets), "Extended keys". PRIVATE / operational: present only in the
  /// wallet that derived the keys, ABSENT from published records. A verifier
  /// never derives a child key from XPUB — the PUBLIC_KEY is the verification
  /// material.
  XPUB: string;
  /// Private part of the cryptographic key in hexidecimal format, should be kept secret
  PRIVATE_KEY: string;
  /// Extended private key, as specified by BIP-32 (hierarchical deterministic wallets), "Extended keys".
  XPRIV: string;
  /// Address generated from the cryptographic key. PRIVATE / operational in a
  /// published EPM: a chain address is bound through a ChainProof attestation,
  /// not carried as a standalone KEY_ADDRESS on the CryptoKey. ABSENT from
  /// published records.
  KEY_ADDRESS: string;
  /// Type of the address generated from the cryptographic key. An address
  /// format tag only — NOT a curve or algorithm designator; the algorithm
  /// lives in ALGORITHM
  ADDRESS_TYPE: string;
  /// Type of the cryptographic key (signing or encryption)
  KEY_TYPE: KeyType;
  /// BIP-32 / SLIP-10 derivation path of this key from the entity root
  /// (e.g., "m/44'/0'/0'/0/0" secp256k1 non-hardened, "m/44'/0'/0'/0'/0'"
  /// ed25519 hardened). PRIVATE / operational: how the key was derived belongs
  /// to the wallet, not to a published record. ABSENT from published records.
  KEY_PATH: string;
  /// Key algorithm/curve (e.g., "ed25519", "secp256k1"). ABSENT means
  /// ed25519: every record published before this field existed verifies
  /// unchanged under that default. The verifier dispatches on ALGORITHM (not
  /// on ADDRESS_TYPE, which is an address-format tag only).
  ALGORITHM: string;
  /// Signature encoding format produced by this key (e.g., "raw-ed25519",
  /// "compact"). ABSENT means the canonical encoding of ALGORITHM
  /// (raw-ed25519 for ed25519, compact for secp256k1)
  ENCODING: string;
}

/// Represents a geographic address
table Address {
  /// Country of the address
  COUNTRY: string;
  /// Region of the address (e.g., state or province)
  REGION: string;
  /// Locality of the address (e.g., city or town)
  LOCALITY: string;
  /// Postal code of the address
  POSTAL_CODE: string;
  /// Street address
  STREET: string;
  /// Post office box number
  POST_OFFICE_BOX_NUMBER: string;
}

/// Proves a blockchain key derives from the same HD wallet as the signing key
table ChainProof {
  /// Chain identifier (e.g., "bitcoin", "ethereum", "solana")
  CHAIN: string;
  /// Derived blockchain address
  ADDRESS: string;
  /// Public key for this chain (hex-encoded)
  PUBLIC_KEY: string;
  /// BIP-44 derivation path (e.g., "m/44'/0'/0'/0/0")
  KEY_PATH: string;
  /// Signature over the attestation payload (hex-encoded)
  SIGNATURE: string;
  /// The canonical payload that was signed (hex-encoded)
  SIGNED_PAYLOAD: string;
  /// Signature algorithm (e.g., "secp256k1-compact-bitcoin", "secp256k1-compact-ethereum", "ed25519")
  ALGORITHM: string;
  /// Signature encoding format (e.g., "compact", "raw-ed25519")
  ENCODING: string;
}

/// Proves control of a DNS domain by the same HD wallet as the signing key —
/// the EPM-record mirror of the DNS TXT wire form (which is deliberately
/// NON-SDS: a base64 FlatBuffer would not fit a 255-byte TXT record). The
/// canonical statement is 6 fixed LF-terminated lines prefixed
/// "sdn-domain-proof/1", and it verifies by BYTE-REPLAY of the verbatim
/// SIGNED_PAYLOAD (ChainProof precedent) — never by JCS.
table DomainProof {
  /// Fully-qualified domain name the proof binds (e.g., "node.example.org")
  DOMAIN: string;
  /// Public key for this proof (hex-encoded)
  PUBLIC_KEY: string;
  /// BIP-32 / SLIP-10 derivation path of the proving key. The signer is the
  /// Ed25519 EPM/publication key at m/44'/0'/0'/0'/0'
  KEY_PATH: string;
  /// Signature over the attestation payload (hex-encoded)
  SIGNATURE: string;
  /// The canonical payload that was signed, verbatim (hex-encoded)
  SIGNED_PAYLOAD: string;
  /// Signature algorithm. ABSENT means ed25519
  ALGORITHM: string;
  /// Signature encoding format. ABSENT means the canonical encoding of
  /// ALGORITHM (raw-ed25519 for ed25519)
  ENCODING: string;
}

/// Entity Profile Message
table EPM {
  /// Distinguished Name of the entity
  DN: string;
  /// Common name of the entity (person or organization)
  LEGAL_NAME: string;
  /// Family name or surname of the person
  FAMILY_NAME: string;
  /// Given name or first name of the person
  GIVEN_NAME: string;
  /// Additional name or middle name of the person
  ADDITIONAL_NAME: string;
  /// Honorific prefix preceding the person's name (e.g., Mr., Dr.)
  HONORIFIC_PREFIX: string;
  /// Honorific suffix following the person's name (e.g., Jr., Sr.)
  HONORIFIC_SUFFIX: string;
  /// Job title of the person
  JOB_TITLE: string;
  /// Occupation of the person
  OCCUPATION: string;
  /// Physical Address
  ADDRESS: Address;
  /// Alternate names for the entity
  ALTERNATE_NAMES: [string];
  /// Email address of the entity
  EMAIL: string;
  /// Telephone number of the entity
  TELEPHONE: string;
  /// Cryptographic keys associated with the entity
  KEYS: [CryptoKey];
  /// Multiformat addresses associated with the entity
  MULTIFORMAT_ADDRESS: [string];
  /// Signature over canonical EPM content (hex), produced by the entity's
  /// signing key under the algorithm declared in SIGNATURE_ALGORITHM
  /// (absent declaration = Ed25519)
  SIGNATURE: string;
  /// Unix timestamp (seconds) when the EPM was signed
  SIGNATURE_TIMESTAMP: int64;
  /// Chain binding proofs linking blockchain keys to the same HD wallet
  CHAIN_PROOFS: [ChainProof];
  /// Type of entity represented by this profile
  ENTITY_TYPE: EntityType = User;
  /// Signature algorithm that produced SIGNATURE (e.g., "ed25519",
  /// "secp256k1"). ABSENT means ed25519 — this single default is what keeps
  /// every EPM signed before this field existed verifying unchanged, so the
  /// field MUST NOT be made required. The signing key is the first CryptoKey
  /// in KEYS with KEY_TYPE Signing whose ALGORITHM matches this declaration
  /// (an absent CryptoKey.ALGORITHM likewise means ed25519)
  SIGNATURE_ALGORITHM: string;
  /// DNS domain binding proofs linking domains to the same HD wallet —
  /// symmetric with CHAIN_PROOFS
  DOMAIN_PROOFS: [DomainProof];
}

root_type EPM;

file_identifier "$EPM";

APP.IDL:
// Hash: 796e00b47708f9f5e8babf42046154bc0cea52f9a7b38f85fa81a5b5a445908f
// Version: 1.151.3
// -----------------------------------END_HEADER
include "../CCT/main.fbs";

/// Application Package Manifest
///
/// An app is a launchable collection of WASM modules, the SDS data types it
/// produces and consumes, the upstream sources it depends on, and its user
/// interface, grouped under one stable identity. Apps run isomorphically in
/// the desktop runtime and the browser; the manifest is the single record a
/// launcher needs to list, verify, and start the app.
///
/// The UI is carried inline: a fully self-contained HTML page (CSS and JS
/// inlined, no external requests) inside a string field, with an explicit
/// content-encoding parameter so the page may be stored as literal UTF-8
/// text, base64, or a compressed base64 form. A page may instead be served
/// by a member module; exactly one of the two mechanisms must be populated
/// per page.
///
/// The page's data contract is described declaratively by DATAFLOW: every
/// unit of data that enters or leaves the running page, the SDS standard it
/// carries, the transport that moves it, and — when applicable — the loaded
/// module method port that produces or consumes it. Standards-only rule:
/// every page payload is an SDS record (a canonical size-prefixed
/// FlatBuffer) or a content identifier pointing at one; the app manifest
/// carries no bespoke page-only data shapes. Locators are content-addressed
/// and IPFS-first: a flow's LOCATOR is a CID resolved through the serving
/// node's IPFS gateway wherever the payload can be published as an immutable
/// object, falling back to a live gossip topic or a same-origin gateway
/// route only for streaming or request-scoped delivery.
///
/// Member modules run isomorphically. A module ref may declare, via
/// RUNTIME_TARGET, that it loads IN THE PAGE through the same module-sdk ABI
/// the SDN nodes use: the page resolves the module bytes by CONTENT_HASH
/// over IPFS and instantiates them in the shared isomorphic JS harness
/// (manifest + plugin_invoke_stream), exactly as a server-side node would.
/// There is no bespoke browser loader; the browser and the node are two
/// hosts of one harness ABI.

/// Content encoding applied to APPUIPage.CONTENT. Append new values only;
/// never reorder or reuse existing values. Decoders must reject an encoding
/// value they do not recognize rather than guessing.
enum appContentEncoding : ubyte {
  /// CONTENT is the literal page text, UTF-8.
  UTF8 = 0,
  /// CONTENT is RFC 4648 standard base64 (with padding) of the page bytes.
  BASE64 = 1,
  /// CONTENT is base64 of the gzip-compressed page bytes.
  BASE64_GZIP = 2,
  /// CONTENT is base64 of the Brotli-compressed page bytes.
  BASE64_BROTLI = 3
}

/// Data flow of a referenced SDS record type relative to the app.
enum appDataDirection : ubyte {
  PRODUCES = 0,
  CONSUMES = 1,
  BOTH = 2
}

/// Kind of upstream source an APPSourceRef names.
enum appSourceKind : ubyte {
  /// REF is an APPModuleRef.ID in the same manifest — one member module is
  /// itself the source for another.
  MODULE = 0,
  /// REF is a URL or endpoint identifier outside the app.
  EXTERNAL_API = 1,
  /// REF is a dataset or catalog identifier.
  DATASET = 2
}

/// Direction of an APPDataflow entry relative to the running page. Distinct
/// from appDataDirection, which is producer/consumer relative to the app as
/// a whole; this enum is page-relative — which way bytes cross the page
/// boundary at runtime. Append new values only; never reorder or reuse
/// existing values.
enum appFlowDirection : ubyte {
  /// Data is delivered into the page for display or module input.
  TO_PAGE = 0,
  /// Data is emitted by the page (a module output or user action) for
  /// publication or upstream consumption.
  FROM_PAGE = 1,
  /// Data crosses in both directions over the same channel.
  BIDIRECTIONAL = 2
}

/// Transport that moves an APPDataflow payload. Locators are content-
/// addressed and IPFS-first: prefer IPFS_CID wherever the payload is an
/// immutable published object, and use the live or request-scoped transports
/// only for streaming or same-origin request/response delivery. Append new
/// values only; never reorder or reuse existing values.
enum appFlowTransport : ubyte {
  /// LOCATOR is a CID; the page fetches the SDS record bytes by content
  /// through the serving node's IPFS gateway.
  IPFS_CID = 0,
  /// LOCATOR is a gossip topic name; live SDS records arrive on the topic
  /// via the node's pubsub bus.
  PUBSUB_TOPIC = 1,
  /// LOCATOR is a same-origin HTTP route template served by the node that
  /// serves the page (used for request-scoped queries and streaming).
  GATEWAY_ROUTE = 2
}

/// Where a member module is instantiated. PAGE and BOTH assert the module
/// loads in the browser through the SAME module-sdk harness ABI the SDN
/// nodes use — page bytes are resolved by APPModuleRef.CONTENT_HASH over
/// IPFS and driven through manifest + plugin_invoke_stream, with no bespoke
/// page loader. Append new values only; never reorder or reuse existing
/// values.
enum appRuntimeTarget : ubyte {
  /// Loads only in the desktop/server node runtime.
  NODE = 0,
  /// Loads in the page through the isomorphic JS harness.
  PAGE = 1,
  /// Loads in both hosts from the same content-addressed bytes and ABI.
  BOTH = 2
}

/// One member WASM module of the app. References module identity; never
/// embeds the module artifact itself (delivery is the module-bundle lane).
table APPModuleRef {
  /// App-local stable reference for this module. Required, unique within
  /// the manifest.
  ID:string (required, key);
  /// Plugin identifier of the module as published in its plugin listing.
  PLUGIN_ID:string;
  /// 64 lowercase hexadecimal characters encoding SHA-256 of the module's
  /// portable (pre-AOT, publication-trailer-stripped) WASM bytes. This is
  /// the identity capability policies and signature policies key on.
  CONTENT_HASH:string;
  /// Module version expected by the app.
  VERSION:string;
  /// Free-text launcher hint, for example primary, worker, or ui-host.
  ROLE:string;
  /// Human-readable summary.
  DESCRIPTION:string;
  /// Per-invocation wall-clock budget override in milliseconds. Zero means
  /// the host runtime default applies.
  MAX_WALL_CLOCK_MS:uint64;
  /// Per-invocation execution-cost (fuel) budget override. Zero means the
  /// host runtime default applies.
  MAX_COST_UNITS:uint64;
  /// Linear-memory ceiling override in 64 KiB WASM pages. Zero means the
  /// host runtime default applies.
  MAX_MEMORY_PAGES:uint32;
  /// Where this module is instantiated. PAGE or BOTH means the module also
  /// loads in the browser: the page resolves its bytes by CONTENT_HASH over
  /// IPFS and instantiates it through the SAME isomorphic module-sdk harness
  /// ABI the SDN nodes use (manifest + plugin_invoke_stream) — never through
  /// a bespoke page-only loader. Defaults to NODE to preserve the prior
  /// node-only behavior of manifests written before this field existed.
  RUNTIME_TARGET:appRuntimeTarget = NODE;
}

/// One SDS record type the app produces and/or consumes. Names an existing
/// spacedatastandards.org schema by its established code; the app manifest
/// defines no data schemas of its own.
table APPDataRef {
  /// App-local stable reference for this data binding. Required, unique
  /// within the manifest.
  ID:string (required, key);
  /// Existing SDS schema code, for example OMM, CDM, or EPM. Required.
  SDS_TYPE:string (required);
  /// Data flow relative to the app.
  DIRECTION:appDataDirection = PRODUCES;
  /// When present, must equal an APPModuleRef.ID in the same manifest — the
  /// member module responsible for this data binding.
  MODULE_ID:string;
  /// Human-readable summary.
  DESCRIPTION:string;
}

/// One upstream data source the app depends on.
table APPSourceRef {
  /// App-local stable reference for this source. Required, unique within
  /// the manifest.
  ID:string (required, key);
  /// Classifies REF.
  KIND:appSourceKind = MODULE;
  /// Source identifier: an APPModuleRef.ID when KIND is MODULE, otherwise a
  /// URL or dataset identifier. Required.
  REF:string (required);
  /// Human-readable summary.
  DESCRIPTION:string;
}

/// One UI page of the app. Exactly one of the two delivery mechanisms must
/// be populated: inline CONTENT (with ENCODING describing its string form),
/// or MODULE_ID plus URL for a page served by a member module. Inline pages
/// must be fully self-contained — CSS and JS inlined, all assets embedded
/// as data URIs, zero external requests.
table APPUIPage {
  /// App-local stable reference for this page. Required, unique within the
  /// manifest.
  ID:string (required, key);
  /// Display title. Falls back to the app NAME when empty.
  TITLE:string;
  /// Human-readable summary. Falls back to the app DESCRIPTION when empty.
  DESCRIPTION:string;
  /// Launcher icon identifier or inline data URI.
  ICON:string;
  /// Launcher accent color, CSS color syntax.
  COLOR:string;
  /// Launcher text color, CSS color syntax.
  TEXT_COLOR:string;
  /// Inlined, self-contained page in the string form declared by ENCODING.
  /// Empty when the page is module-served via MODULE_ID and URL.
  CONTENT:string;
  /// String form of CONTENT.
  ENCODING:appContentEncoding = UTF8;
  /// IANA media type of the decoded page bytes, for example text/html.
  MEDIA_TYPE:string;
  /// 64 lowercase hexadecimal characters encoding SHA-256 of the decoded
  /// page bytes, so a launcher can verify inline content after decoding.
  CONTENT_SHA256:string;
  /// True for the page the launcher opens first. Exactly one page in an
  /// app must set this when UI is present.
  ENTRY:bool;
  /// When module-served, must equal an APPModuleRef.ID in the same
  /// manifest — the member module that serves this page.
  MODULE_ID:string;
  /// When module-served, the path or entrypoint the module serves the page
  /// at.
  URL:string;
}

/// One unit of the page's data contract: a named flow describing what data
/// enters or leaves the running page, the SDS standard it carries, how it is
/// transported, and — when applicable — the loaded module method port bound
/// to it. Standards-only rule: every flow payload is an SDS record (a
/// canonical size-prefixed FlatBuffer) or a CID pointing at one; this table
/// defines no data shapes of its own, it only references an existing
/// spacedatastandards.org schema by its established code. Locators are
/// content-addressed and IPFS-first.
table APPDataflow {
  /// App-local stable name for this flow. Required, unique within the
  /// manifest.
  NAME:string (required, key);
  /// Which way the payload crosses the page boundary at runtime.
  DIRECTION:appFlowDirection = TO_PAGE;
  /// Existing SDS schema code carried by this flow, for example OMM, OEM, or
  /// PNM. Required. Mirrors APPDataRef.SDS_TYPE but named for the standard
  /// the flow carries; the app defines no schema of its own.
  SDS_SCHEMA:string (required);
  /// Transport that moves the payload. Defaults to IPFS_CID per the
  /// content-addressed, IPFS-first rule.
  TRANSPORT:appFlowTransport = IPFS_CID;
  /// Where to fetch or reach the payload, interpreted per TRANSPORT: a CID
  /// for IPFS_CID, a gossip topic name for PUBSUB_TOPIC, or a same-origin
  /// route template for GATEWAY_ROUTE.
  LOCATOR:string;
  /// When present, must equal an APPModuleRef.ID in the same manifest — the
  /// loaded module that produces or consumes this flow. Binds the flow to a
  /// specific module method port together with METHOD_ID and PORT_ID.
  MODULE_ID:string;
  /// When present, the PLG.PLGMethodManifest.METHOD_ID on MODULE_ID that
  /// this flow is bound to.
  METHOD_ID:string;
  /// When present, the PLG.PLGPortManifest.PORT_ID on METHOD_ID that this
  /// flow is bound to.
  PORT_ID:string;
  /// String/compression form of the payload as it crosses the channel,
  /// reusing the page content-encoding vocabulary. For flows carrying
  /// canonical SDS FlatBuffer bytes (or a CID string), UTF8 denotes the raw
  /// bytes/string with no extra wrapper; BASE64, BASE64_GZIP, and
  /// BASE64_BROTLI denote a base64 text wrapper (optionally compressed)
  /// applied when the channel is text-only.
  CONTENT_ENCODING:appContentEncoding = UTF8;
  /// Human-readable summary.
  DESCRIPTION:string;
}

/// Application Package Manifest — one launchable app.
table APP {
  /// Stable app identity, unique per publisher. Required.
  ID:string (required);
  /// Display name.
  NAME:string;
  /// SemVer 2.0.0 app version.
  VERSION:string;
  /// Human-readable summary.
  DESCRIPTION:string;
  /// Member WASM modules. Referential integrity: every MODULE_ID and every
  /// MODULE-kind REF elsewhere in the manifest must resolve into this list.
  MODULES:[APPModuleRef];
  /// SDS record types produced and consumed.
  DATA:[APPDataRef];
  /// Upstream sources depended on.
  SOURCES:[APPSourceRef];
  /// UI pages. Exactly one entry page when nonempty.
  UI:[APPUIPage];
  /// RFC 3339 UTC fixed-millisecond timestamp (YYYY-MM-DDTHH:mm:ss.sssZ)
  /// when the manifest was created.
  CREATED_AT:string;
  /// RFC 3339 UTC fixed-millisecond timestamp (YYYY-MM-DDTHH:mm:ss.sssZ)
  /// when the manifest was last updated.
  UPDATED_AT:string;
  /// The page's declarative data contract: what data enters and leaves the
  /// running page and how. Referential integrity: every MODULE_ID here must
  /// resolve into MODULES, and each MODULE_ID/METHOD_ID/PORT_ID triple must
  /// name a method port advertised by that module's PLG manifest.
  DATAFLOW:[APPDataflow];
  /// App-wide runtime class, reusing appRuntimeTarget. Lets a pulled manifest
  /// self-describe where the app as a whole is meant to run, instead of that
  /// classification being supplied externally at install time. This is the
  /// app-level DEFAULT/DECLARATION only: an individual APPModuleRef.
  /// RUNTIME_TARGET still governs where that specific member module loads and
  /// may specialize away from RUNTIME_CLASS (for example a NODE-class app
  /// with one PAGE-capable module). Defaults to NODE to preserve the prior
  /// node-only assumption of manifests written before this field existed.
  RUNTIME_CLASS:appRuntimeTarget = NODE;
  /// The one ratified $CCT category this app is shelved under, using the same
  /// vocabulary and the same semantics as PLG.PRIMARY_CATEGORY, so a storefront
  /// or library shelf holds apps and modules together without translating
  /// between two classification schemes. RUNTIME_CLASS says WHERE an app runs;
  /// PRIMARY_CATEGORY says WHAT IT DOES. They are independent: a NODE-class app
  /// and a PAGE-class app can share a category.
  /// UNSPECIFIED means the publisher did not classify the app; a consumer
  /// renders it ungrouped and never infers a class.
  PRIMARY_CATEGORY:capabilityClass = UNSPECIFIED;
  /// Every ratified $CCT category this app belongs to, for browse, filter and
  /// per-category counting. An app MAY carry several. If nonempty it MUST
  /// include PRIMARY_CATEGORY. Codes MUST NOT repeat.
  CATEGORIES:[capabilityClass];
}

root_type APP;
file_identifier "$APP";

SDF.IDL:
// Hash: 4e51515796014893d9b317cc4325714edc8d1bdb621e881699e51047a2e1ef70
// Version: 0.0.2
// -----------------------------------END_HEADER
/// Signed Distance Field — detection and containment queries for sensor /
/// geometric volumes.
///
/// Convention for signed-distance values:
///   - Negative values are inside the volume.
///   - Zero is on the boundary.
///   - Positive values are outside the volume.

/// Primitive shape family for an SDF volume.
enum sdfPrimitive : ubyte {
  /// Cone with apex at origin, +Z boresight.
  CONE,
  /// Rectangular pyramid (four planes + range cap).
  RECTANGULAR,
  /// Sphere centered at origin.
  SPHERE,
  /// Cylinder along Z axis.
  CYLINDER,
  /// Plugin-defined custom SDF.
  CUSTOM = 255
}

/// Constructive solid-geometry composition operation for SDFs.
enum sdfOperation : ubyte {
  /// No composition (primitive only).
  NONE,
  /// Union (min of SDFs) — inside either.
  UNION,
  /// Intersection (max of SDFs) — inside both.
  INTERSECTION,
  /// Subtraction (A - B) — inside A but not B.
  SUBTRACTION,
  /// Smooth union with a blend radius.
  SMOOTH_UNION
}

/// Result of a single SDF point-in-volume query (24 bytes, 8-byte aligned).
struct sdfResult {
  /// Entity identifier.
  ENTITY_ID:uint;
  /// Detection flag (1 == inside, 0 == outside).
  DETECTED:uint;
  /// Signed distance (negative inside, zero on boundary, positive outside).
  SIGNED_DISTANCE:double;
  /// Distance to the closest boundary point (always positive).
  CLOSEST_DISTANCE:double;
}

/// Result of a time-range SDF query (40 bytes, 8-byte aligned).
struct sdfTimeRangeResult {
  /// Entity identifier.
  ENTITY_ID:uint;
  /// Flags (reserved).
  FLAGS:uint;
  /// Julian date when the entity entered the volume (0 == never entered).
  ENTRY_TIME:double;
  /// Julian date when the entity exited the volume (0 == still inside).
  EXIT_TIME:double;
  /// Most negative signed distance (closest approach to center).
  MIN_DISTANCE:double;
  /// Total time inside volume (seconds).
  DWELL_TIME:double;
}

/// Conical SDF parameters.
table SDFConical {
  HALF_ANGLE:double;
  /// Inner half-angle for hollow cones (0 == solid).
  INNER_HALF_ANGLE:double;
  /// Minimum range (inner cap distance).
  MIN_RANGE:double;
  /// Maximum range (outer cap distance).
  MAX_RANGE:double;
  /// Use a flat cap (true) or a spherical cap (false).
  FLAT_CAP:bool;
}

/// Rectangular (pyramidal) SDF parameters.
table SDFRectangular {
  X_HALF_ANGLE:double;
  Y_HALF_ANGLE:double;
  MIN_RANGE:double;
  MAX_RANGE:double;
}

/// Spherical SDF parameters.
table SDFSpherical {
  RADIUS:double;
  /// Inner radius for hollow sphere (0 == solid).
  INNER_RADIUS:double;
}

/// Cylindrical SDF parameters.
table SDFCylindrical {
  RADIUS:double;
  HALF_HEIGHT:double;
}

/// Custom SDF defined by a set of unit boundary-direction vectors.
table SDFCustom {
  /// Unit vectors defining the boundary packed as [x0, y0, z0, x1, y1, z1, ...].
  DIRECTIONS:[double];
  MAX_RANGE:double;
}

/// Constructive composition of two SDFs.
table SDFComposition {
  OPERATION:sdfOperation;
  /// First operand (index into SDF.COMPONENTS[]).
  OPERAND_A:uint;
  /// Second operand (index into SDF.COMPONENTS[]).
  OPERAND_B:uint;
  /// Blend radius for smooth operations.
  BLEND_RADIUS:double;
}

/// Single component in a composed SDF.
table SDFComponent {
  PRIMITIVE:sdfPrimitive;
  CONE:SDFConical;
  RECTANGULAR:SDFRectangular;
  SPHERICAL:SDFSpherical;
  CYLINDRICAL:SDFCylindrical;
  CUSTOM:SDFCustom;
}

/// Complete SDF configuration.
table SDFConfig {
  /// Root primitive type (useful when COMPONENTS[] is empty).
  PRIMITIVE:sdfPrimitive;
  /// One or more components that may be combined via COMPOSITIONS[].
  COMPONENTS:[SDFComponent];
  /// Composition tree over COMPONENTS[].
  COMPOSITIONS:[SDFComposition];
  /// World-to-local transform (4x4 column-major, 16 doubles).
  INVERSE_TRANSFORM:[double];
}

/// Batch SDF evaluation request (arena-addressed, zero-copy).
table SDFBatchRequest {
  /// Input buffer offset (arena bytes) where the Vec3[] of world points begins.
  INPUT_OFFSET:uint;
  /// Number of points to evaluate.
  POINT_COUNT:uint;
  /// Entity-ids buffer offset corresponding to each point (optional).
  ENTITY_IDS_OFFSET:uint;
  /// Output buffer offset where sdfResult[] is written.
  OUTPUT_OFFSET:uint;
  /// Inverse-transform buffer offset (4x4 matrix, 128 bytes).
  INVERSE_TRANSFORM_OFFSET:uint;
}

/// Batch SDF evaluation response header.
table SDFBatchResponse {
  /// Number of results written.
  COUNT:uint;
  /// Number of points inside the volume.
  INSIDE_COUNT:uint;
  /// Output offset where sdfResult[] starts.
  OUTPUT_OFFSET:uint;
  /// Error code (0 == success).
  ERROR_CODE:int;
  /// Optional error message when ERROR_CODE != 0.
  ERROR_MESSAGE:string;
}

/// Signed Distance Field envelope message — carries a configuration, a batch
/// request, a batch response, or single / time-range result records.
table SDF {
  CONFIG:SDFConfig;
  BATCH_REQUEST:SDFBatchRequest;
  BATCH_RESPONSE:SDFBatchResponse;
  RESULTS:[sdfResult];
  TIME_RANGE_RESULTS:[sdfTimeRangeResult];
}

root_type SDF;
file_identifier "$SDF";

