TRH.IDL:
// Hash: caca5d61640738a49652afeeaa24bd81fc458e69f4b66e11b02cda8e3dd343ed
// Version: 1.202.0
// -----------------------------------END_HEADER
enum trhHardwareKind : ubyte {
  UNSPECIFIED = 0,
  ANTENNA = 1,
  TRANSMITTER = 2,
  RECEIVER = 3,
  TRANSPONDER = 4
}

enum trhTurnaroundMode : ubyte {
  UNSPECIFIED = 0,
  COHERENT = 1,
  NONCOHERENT = 2,
  REGENERATIVE = 3
}

table TRHAntenna {
  HARDWARE_ID: string (required);
  FREQUENCY_HZ: double;
  BANDWIDTH_HZ: double;
  GAIN_DBI: double;
  PHASE_CENTER_DELAY_SECONDS: double;
}

table TRHTransmitter {
  HARDWARE_ID: string (required);
  FREQUENCY_HZ: double;
  POWER_WATTS: double;
  MODULATION: string;
  HARDWARE_DELAY_SECONDS: double;
  ANTENNA_ID: string;
}

table TRHReceiver {
  HARDWARE_ID: string (required);
  CENTER_FREQUENCY_HZ: double;
  BANDWIDTH_HZ: double;
  SYSTEM_NOISE_TEMPERATURE_KELVIN: double;
  HARDWARE_DELAY_SECONDS: double;
  ANTENNA_ID: string;
}

table TRHTransponder {
  HARDWARE_ID: string (required);
  TURNAROUND_MODE: trhTurnaroundMode = UNSPECIFIED;
  TURNAROUND_NUMERATOR: uint;
  TURNAROUND_DENOMINATOR: uint;
  GROUP_DELAY_SECONDS: double;
  RECEIVER_ID: string;
  TRANSMITTER_ID: string;
}

table TRHHardwareRef {
  HARDWARE_KIND: trhHardwareKind = UNSPECIFIED;
  HARDWARE_ID: string (required);
}

table TRHInstallation {
  OWNER_OBJECT_ID: string (required);
  HARDWARE: [TRHHardwareRef];
  CLOCK_BIAS_SECONDS: double;
  CLOCK_DRIFT_SECONDS_PER_SECOND: double;
}

table TRHAttestation {
  SIGNING_PUBLIC_KEY: string (required);
  SIGNED_AT: string;
  SIGNATURE: [ubyte] (required);
  CANONICAL_JSON_SIGNATURE: [ubyte] (required);
}

/// Tracking Hardware. Installations attach antennas, transmitters, receivers
/// and transponders to either a surface site or a tracked object. Delays are
/// seconds, frequencies hertz, temperatures kelvin and powers watts. JSON
/// projections preserve these IDL-capitalized field names exactly.
table TRH {
  ANTENNAS: [TRHAntenna];
  TRANSMITTERS: [TRHTransmitter];
  RECEIVERS: [TRHReceiver];
  TRANSPONDERS: [TRHTransponder];
  INSTALLATIONS: [TRHInstallation];
  TRACE_ID: string;
  ATTESTATION: TRHAttestation;
}

root_type TRH;
file_identifier "$TRH";

LCF.IDL:
// Hash: c78cace00317c61c64dbd94c42591b0bdb415eff099627660b211cf60d26de7b
// Version: 1.82.0
// -----------------------------------END_HEADER
include "../KRF/main.fbs";

enum licensingConfigMessageType : byte {
  Configure,
  Status
}

enum licensingConfigRole : byte {
  Provider,
  Requester
}

/// Licensing Configuration Frame
table LCF {
  /// Distinguishes configuration inputs from runtime status outputs.
  MESSAGE_TYPE: licensingConfigMessageType = Configure;
  /// Indicates whether the configuration/status applies to server/provider or requester/client behavior.
  ROLE: licensingConfigRole = Provider;
  /// Peer ID advertised by the licensing provider.
  PROVIDER_PEER_ID: string;
  /// Host-managed long-lived signing key used for grant signatures.
  PROVIDER_SIGNING_KEY: KRF;
  /// Host-managed wrapping key used to protect per-publication content keys for requesters.
  PROVIDER_WRAPPING_KEY: KRF;
  /// Optional requester signing key reference for requester-hosted flows.
  REQUESTER_SIGNING_KEY: KRF;
  /// Logical active publication/grant key version.
  ACTIVE_KEY_VERSION: uint32;
  /// Runtime expiry in unix milliseconds, or 0 if unbounded.
  EXPIRES_AT: uint64;
  /// Maximum accepted requester/provider clock skew in milliseconds.
  MAX_CLOCK_SKEW_MS: uint64;
  /// Challenge time-to-live in milliseconds.
  CHALLENGE_TTL_MS: uint64;
  /// Optional capability token bytes returned with successful grants.
  CAPABILITY_TOKEN: [ubyte];
  /// Whether the runtime has been initialized successfully.
  INITIALIZED: bool = false;
  /// Whether the runtime needs issuer key rotation or refreshed configuration.
  NEEDS_ROTATION: bool = false;
  /// Optional machine-readable status code for status/error responses.
  STATUS_CODE: string;
  /// Optional human-readable status or error message.
  STATUS_MESSAGE: string;
}

root_type LCF;
file_identifier "$LCF";

PRR.IDL:
// Hash: 02dd420890310222b88786aa1a99e171422ffa047e85e79e902aaacbcb5b3cbf
// Version: 1.145.0
// -----------------------------------END_HEADER
/// Peer Registry Record - Durable trusted-peer registry state for an SDN node.
///
/// PRR records describe one libp2p peer entry in a node's local peer registry.
/// The current registry is a projection over the latest PRR records by PEER_ID,
/// with deleted records acting as tombstones.
enum peerRegistryTrustCategory : byte {
  Untrusted,
  Limited,
  Standard,
  Trusted,
  Admin
}

/// String metadata key/value attached to a peer registry entry.
table PRRMetadataEntry {
  /// Metadata key.
  KEY: string;
  /// Metadata value.
  VALUE: string;
}

table PRR {
  /// libp2p peer ID.
  PEER_ID: string (required);
  /// Known libp2p/IPFS multiaddresses for this peer.
  MULTIFORMAT_ADDRESS: [string];
  /// Trust level assigned to this peer by the local registry.
  TRUST_LEVEL: peerRegistryTrustCategory = Standard;
  /// Optional display name.
  NAME: string;
  /// Optional organization name.
  ORGANIZATION: string;
  /// Peer group names this peer belongs to.
  GROUPS: [string];
  /// Operator notes for this peer.
  NOTES: string;
  /// Unix timestamp in milliseconds when this peer was added.
  ADDED_AT: uint64;
  /// Unix timestamp in milliseconds when this peer was last observed.
  LAST_SEEN: uint64;
  /// Unix timestamp in milliseconds when this peer last connected.
  LAST_CONNECTED: uint64;
  /// Number of successful connections observed by this node.
  CONNECTION_COUNT: uint64;
  /// Number of messages received from this peer.
  MESSAGES_RECEIVED: uint64;
  /// Number of messages sent to this peer.
  MESSAGES_SENT: uint64;
  /// Number of bytes received from this peer.
  BYTES_RECEIVED: uint64;
  /// Number of bytes sent to this peer.
  BYTES_SENT: uint64;
  /// Optional EPM.fbs bytes for the peer identity profile.
  EPM_DATA: [ubyte];
  /// Optional vCard projection for compatibility views.
  VCARD_DATA: string;
  /// Additional peer metadata as string key/value entries.
  METADATA: [PRRMetadataEntry];
  /// Unix timestamp in milliseconds when this registry record was last updated.
  UPDATED_AT: uint64;
  /// True when this record tombstones the peer from the current registry.
  DELETED: bool;
  /// Peer ID of the node/provider that issued this registry record.
  PROVIDER_PEER_ID: string;
  /// Provider signature over the peer registry record.
  PROVIDER_SIGNATURE: [ubyte];
}

root_type PRR;
file_identifier "$PRR";

SHW.IDL:
// Hash: 967b270c817b95d0f721afe754839b6b874b0ea1a94757851b27f9f6e01164ad
// Version: 0.0.3
// -----------------------------------END_HEADER
/// Shader Wire — wire contract for GLSL / WebGL shader plugins that compile
/// and expose parameterized fragments that a host injects into its own
/// pipeline. Carries compile request + response, a uniform description
/// table, and the injection-point enum a host consumes to know where to
/// splice a shader fragment into its stage graph.

/// Shader stage into which a compiled fragment should be injected.
enum glslStage : ubyte {
  VERTEX,
  FRAGMENT,
  COMPUTE,
  GEOMETRY,
  TESS_CONTROL,
  TESS_EVALUATION
}

/// Logical location inside a host pipeline where a compiled shader
/// fragment is meant to be spliced. A host maps these onto its own
/// concrete splice points.
enum shaderHookPoint : ubyte {
  NONE,
  VERTEX_PRE_TRANSFORM,
  VERTEX_POST_TRANSFORM,
  FRAGMENT_PRE_SHADE,
  FRAGMENT_POST_SHADE,
  FRAGMENT_FINAL_COLOR,
  POSTPROCESS
}

/// Scalar / vector type of a uniform value.
enum shaderUniformType : ubyte {
  FLOAT,
  VEC2,
  VEC3,
  VEC4,
  INT,
  IVEC2,
  IVEC3,
  IVEC4,
  UINT,
  UVEC2,
  UVEC3,
  UVEC4,
  BOOL,
  BVEC2,
  BVEC3,
  BVEC4,
  MAT2,
  MAT3,
  MAT4,
  SAMPLER_2D,
  SAMPLER_CUBE,
  SAMPLER_2D_ARRAY
}

/// Uniform descriptor — name + type + optional default value.
table SHWUniform {
  UNIFORM_NAME:string;
  UNIFORM_TYPE:shaderUniformType;
  /// Optional human-readable description.
  UNIFORM_DESCRIPTION:string;
  /// Optional default value encoded as bytes in the native type layout.
  UNIFORM_DEFAULT_VALUE:[uint8];
}

/// Compile request — one shader source (typically a fragment of a
/// larger stage) plus metadata for the host splice.
table SHWCompileRequest {
  /// Logical shader name (used in logs and uniform prefixing).
  SHADER_NAME:string;
  /// Target GLSL stage.
  SHADER_STAGE:glslStage;
  /// Intended injection point in the host pipeline.
  SHADER_INJECTION_POINT:shaderHookPoint;
  /// GLSL source (or preprocessed chunk).
  SHADER_SOURCE:string;
  /// GLSL version string (for example `300 es`).
  GLSL_VERSION:string;
  /// Expected uniforms declared by the source.
  SHADER_UNIFORMS:[SHWUniform];
}

/// Compile response — whether the shader compiled, with diagnostics.
table SHWCompileResponse {
  SHADER_NAME:string;
  /// Whether compilation succeeded.
  COMPILE_SUCCESS:bool;
  /// Optional GLSL info log.
  INFO_LOG:string;
  /// Optional compiled binary (if the compiler emits one).
  COMPILED_BINARY:[uint8];
  /// Echo of the uniforms the compiler actually linked.
  LINKED_UNIFORMS:[SHWUniform];
}

/// Shader Wire envelope — carries either a compile request or a compile
/// response across the runtime boundary.
table SHW {
  COMPILE_REQUEST:SHWCompileRequest;
  COMPILE_RESPONSE:SHWCompileResponse;
}

root_type SHW;
file_identifier "$SHW";

