TXS.IDL:
// Hash: 71f1faf48968806d432809e871c417ca430e72cf4f9a80cd013e36b1068c10dd
// Version: 1.197.0
// -----------------------------------END_HEADER
// Terrestrial Transmitter Site (TXS)
// Description
// One record describes ONE fixed terrestrial radio TRANSMITTING FACILITY as
// reconciled from every source the publisher consulted: where the facility
// stands and on whose authority that position is asserted, what structure
// carries the antennas, and every emission the facility is documented to
// radiate — frequency, bandwidth, emission designator, power, antenna
// bearing and polarization.
//
// Division of labour. `$TBS` is a terrestrial CELLULAR base-station site and
// is addressed by a mobile numbering plan (country, network, area and cell
// codes) that a broadcast, utility or public-safety transmitter does not
// possess; it is not this record and this record is not it. `$RFE` is an
// emission-LIMIT mask curve, `$RFB` is an emitter's static band capability
// with no position, `$RFL` is a computed link-budget time series, `$GST` is a
// geodetic tracking station, `$SIT` is an operational site in the
// space-operations sense, and `$RFO`/`$DOA`/`$GEL` are observations and fused
// geolocation solutions of an emitter. None of them can hold a licensed
// terrestrial transmitter's position, service class, station identity and
// emission list together. `$STX` carries the SCHEDULE — one row per
// transmission window — and joins to this record by SITE_ID.
//
// POSITION AUTHORITY IS FIRST CLASS. A regulator-published coordinate, an
// international coordination filing, a survey, a direction-finding fix and a
// listener community's assertion are different epistemic objects, and a
// consumer that cannot tell them apart will render an OSINT-grade guess with
// the same weight as a licence record. POSITION_AUTHORITY states the class of
// the assertion, POSITION_UNCERTAINTY_M states the envelope, POSITION_DISPUTED
// states that credible sources disagree, and PRIOR_POSITIONS retains positions
// the facility is asserted to have vacated. Provider agreement counts in
// CONSENSUS measure corroboration, never authority; both are published.
//
// Unknown values are ABSENT — never zero, never a placeholder, never carried
// across from a neighbouring facility. A facility cannot be re-serialized
// unattributed: SOURCES and CONSENSUS are both required.
//
// The standard names no provider, dataset, operator, or facility. Source and
// authority identity is DATA, carried verbatim in provenance entries.

/// Radiocommunication service class a transmitting facility operates under.
///
/// Members name interoperable service classes only, never an operator, a
/// programme, or a network. A publisher encodes the class ITS SOURCE STATES
/// and never re-derives one from frequency alone. Ordinals are wire values:
/// append only; never reorder or reuse.
enum txsServiceClass : byte {
  /// The source publishes no service class. Every service field defaults here
  /// so an unset field can never be read as a real class.
  UNSPECIFIED = 0,
  /// Sound broadcasting on the low-frequency broadcasting allocations.
  LONG_WAVE_BROADCAST,
  /// Sound broadcasting on the medium-frequency broadcasting allocations.
  MEDIUM_WAVE_BROADCAST,
  /// Sound broadcasting on the high-frequency broadcasting allocations,
  /// including transmissions directed at audiences outside the transmitting
  /// administration.
  SHORT_WAVE_BROADCAST,
  /// Frequency-modulated sound broadcasting on the very-high-frequency
  /// broadcasting allocations.
  FM_SOUND_BROADCAST,
  /// Digitally multiplexed sound broadcasting, terrestrial.
  DIGITAL_SOUND_BROADCAST,
  /// Terrestrial television broadcasting, analogue or digital.
  TELEVISION_BROADCAST,
  /// Fixed service operated by or for an armed service.
  MILITARY_FIXED,
  /// Fixed service operated by a non-broadcast, non-military user for its own
  /// operational traffic.
  UTILITY_FIXED,
  /// Aeronautical mobile or aeronautical fixed service.
  AERONAUTICAL,
  /// Maritime mobile or maritime fixed service.
  MARITIME,
  /// Land mobile service supporting emergency response and public protection.
  PUBLIC_SAFETY_LAND_MOBILE,
  /// Land mobile service operated by a private or commercial user.
  LAND_MOBILE_PRIVATE,
  /// Amateur service, including unattended propagation beacons.
  AMATEUR,
  /// Standard-frequency and time-signal service.
  TIME_AND_FREQUENCY_STANDARD,
  /// Radionavigation service, including terrestrial hyperbolic and
  /// non-directional navigation aids.
  RADIONAVIGATION,
  /// Radiolocation service, including over-the-horizon and surface-wave
  /// installations.
  RADIOLOCATION,
  /// Meteorological aids or meteorological broadcast.
  METEOROLOGICAL,
  /// Space operations, space research or satellite feeder-link earth-station
  /// transmission from a terrestrial facility.
  SPACE_OPERATIONS_UPLINK,
  /// Service authorized for experiment or development.
  EXPERIMENTAL,
  /// The source states a service this enum does not model. The source's own
  /// term is retained verbatim in the provenance entry, never discarded.
  OTHER
}

/// The class of authority behind the published position of a facility.
///
/// This is an EPISTEMIC statement, not a quality score: it says who asserted
/// the coordinate and in what capacity. Ordinals are wire values: append only;
/// never reorder or reuse.
enum txsPositionAuthorityClass : byte {
  /// The publisher does not state how the position was established. POSITION
  /// AUTHORITY defaults here so an unset field can never be read as a
  /// regulator's coordinate.
  UNSPECIFIED = 0,
  /// A spectrum regulator or licensing administration publishes the coordinate
  /// in its own licence or assignment record.
  REGULATOR_PUBLISHED,
  /// An international frequency coordination register or notification filing
  /// carries the coordinate.
  COORDINATION_FILING,
  /// The licensee or facility operator publishes the coordinate itself.
  LICENSEE_PUBLISHED,
  /// The coordinate was surveyed or measured on site by a party independent of
  /// the licensee.
  SURVEYED_INDEPENDENT,
  /// The coordinate was read off imagery or a mapping product by the publisher
  /// or a cited source.
  DERIVED_FROM_IMAGERY,
  /// The coordinate is the result of radio direction finding, time- or
  /// frequency-difference-of-arrival geolocation, or another observation-based
  /// fix. The fused solution itself belongs in `$GEL`.
  INFERRED_FROM_OBSERVATION,
  /// The coordinate is asserted by an observer community or an enthusiast
  /// compilation with no regulator, licensee or survey behind it. It is
  /// publishable and it is never interchangeable with a licence coordinate.
  COMMUNITY_ASSERTED,
  /// A community assertion the sources themselves report as superseded — the
  /// facility is believed to have moved, and the coordinate describes where it
  /// formerly stood.
  COMMUNITY_ASSERTED_HISTORICAL,
  /// The facility is documented to exist and no party publishes a position at
  /// all. LATITUDE and LONGITUDE are ABSENT in this case; they are never
  /// filled with a region centroid.
  UNDISCLOSED
}

/// Antenna-supporting structure capability class. Ordinals are wire values:
/// append only; never reorder or reuse.
enum txsStructureClass : byte {
  UNSPECIFIED = 0,
  GUYED_MAST,
  SELF_SUPPORTING_TOWER,
  MONOPOLE,
  ROOFTOP_OR_BUILDING,
  CURTAIN_ARRAY,
  LOG_PERIODIC,
  DIPOLE_OR_WIRE,
  VERTICAL_RADIATOR,
  DISH_REFLECTOR,
  LOOP_OR_LOADED_ELEMENT,
  UNDERGROUND_OR_CONCEALED,
  TRANSPORTABLE,
  OTHER
}

/// Operating state of a facility as its sources state it. Ordinals are wire
/// values: append only; never reorder or reuse.
enum txsOperationalStatus : byte {
  UNSPECIFIED = 0,
  /// Radiating on a regular or continuous basis.
  OPERATIONAL,
  /// Radiating irregularly or only for part of the year.
  INTERMITTENT,
  /// Licensed and standing, but not currently radiating.
  SILENT,
  /// Authorization withdrawn or surrendered; structure may still stand.
  DECOMMISSIONED,
  /// Structure removed.
  DEMOLISHED,
  /// Authorized or announced, not yet radiating.
  PLANNED,
  /// Sources agree the operation moved to a different facility.
  RELOCATED
}

/// Modulation capability class of one emission. The ITU emission designator in
/// EMISSION_DESIGNATOR is authoritative whenever both are present; this enum
/// exists so a consumer can filter without parsing designators. Ordinals are
/// wire values: append only; never reorder or reuse.
enum txsModulationClass : byte {
  UNSPECIFIED = 0,
  UNMODULATED_CARRIER,
  ON_OFF_KEYED_CARRIER,
  AMPLITUDE_DOUBLE_SIDEBAND,
  AMPLITUDE_SINGLE_SIDEBAND_FULL_CARRIER,
  AMPLITUDE_SINGLE_SIDEBAND_REDUCED_CARRIER,
  AMPLITUDE_SINGLE_SIDEBAND_SUPPRESSED_CARRIER,
  AMPLITUDE_VESTIGIAL_SIDEBAND,
  AMPLITUDE_INDEPENDENT_SIDEBAND,
  FREQUENCY_MODULATION,
  PHASE_MODULATION,
  FREQUENCY_SHIFT_KEYING,
  PHASE_SHIFT_KEYING,
  QUADRATURE_AMPLITUDE,
  ORTHOGONAL_FREQUENCY_DIVISION_MULTIPLEX,
  PULSED,
  SPREAD_SPECTRUM,
  OTHER
}

/// Polarization of the radiated field. Ordinals are wire values: append only;
/// never reorder or reuse.
enum txsPolarization : byte {
  UNSPECIFIED = 0,
  VERTICAL,
  HORIZONTAL,
  MIXED,
  SLANT,
  CIRCULAR_RIGHT_HAND,
  CIRCULAR_LEFT_HAND,
  ELLIPTICAL
}

/// How independent source reports for one facility were reduced to the one
/// published position. Ordinals are wire values: append only; never reorder or
/// reuse.
enum txsMergeMethod : byte {
  /// The publisher does not state how the reports were reduced. METHOD
  /// defaults here so an unset field can never be read as a real method.
  UNSPECIFIED = 0,
  /// Exactly one source reported the facility; nothing was reconciled.
  SINGLE_SOURCE,
  /// A declared precedence ranking over publishing authorities selected the
  /// winning report.
  AUTHORITY_PRECEDENCE,
  /// The report with the most recent publication or observation window won.
  MOST_RECENT,
  /// The report backed by the largest independent observation count won.
  HIGHEST_SAMPLE_COUNT,
  /// The published position is computed from the agreeing reports and belongs
  /// to no single source.
  CENTROID
}

/// Replayable provenance for ONE source's report of ONE facility, emission, or
/// scheduled transmission.
///
/// Every source consulted gets its own entry, including sources that returned
/// nothing, so a consumer can tell "not looked for" from "looked for and
/// returned nothing". Source identity is DATA: PROVIDER_ID and AUTHORITY carry
/// verbatim what that source states about itself.
table TXSProvenance {
  /// Publisher-stable, lowercase identifier for the consulted source, unique
  /// within the publisher's own source registry. Never a display name and
  /// never a URL.
  PROVIDER_ID:string (required);
  /// The authority under which that source publishes, verbatim as the source
  /// states it: a spectrum regulator, an international coordination register,
  /// a licensee, a monitoring service, or an observer compilation. Never
  /// inferred by the publisher.
  AUTHORITY:string;
  /// Replayable URL identifying the source material.
  SOURCE_URL:string;
  /// The exact query, filter, or request parameters used, so the same rows can
  /// be recovered by repeating the fetch.
  SOURCE_QUERY:string;
  /// RFC 3339 UTC fixed-millisecond retrieval timestamp.
  RETRIEVED_AT:string (required);
  /// Redistribution terms verbatim. Required: there is no encoding for a
  /// redistributed record whose terms are unstated. A source that publishes no
  /// terms is recorded as publishing no terms; unknown terms are never public
  /// domain and never an implied grant.
  LICENSE:string (required);
  /// URL of the full licence text as that source publishes it.
  LICENSE_URL:string;
  /// Attribution text the licence requires a redistributor to display.
  ATTRIBUTION:string;
  /// The licence forbids commercial use. Rides PER SOURCE because one record
  /// may merge an open-terms lane beside a non-commercial cross-check, and the
  /// strictest consulted lane governs any derived product.
  NON_COMMERCIAL_ONLY:bool = false;
  /// This source's own row, record, licence or file identifier, verbatim.
  NATIVE_ID:string;
  /// The class of authority this particular source speaks with about position.
  /// Published per source because a record may merge a regulator lane with a
  /// community lane; the record-level POSITION_AUTHORITY states which class the
  /// PUBLISHED coordinate came from.
  POSITION_AUTHORITY:txsPositionAuthorityClass = UNSPECIFIED;
  /// Position this source reported, in decimal degrees on WGS 84, before
  /// reconciliation. Retained unrounded so the merge stays auditable. Absent
  /// when the source was consulted and reported no position.
  REPORTED_LATITUDE:double;
  REPORTED_LONGITUDE:double;
  /// This source's report materially contributed to the published record.
  /// False marks a source that was consulted and either returned nothing or
  /// was outvoted; its entry is published either way.
  CONTRIBUTED:bool = false;
}

/// How one facility's independent source reports were reduced to the single
/// published position, and how strongly those reports agreed.
///
/// Agreement is CORROBORATION and is never authority: five compilations that
/// copied one another agree perfectly and establish nothing. Read this table
/// beside POSITION_AUTHORITY, never instead of it.
table TXSConsensus {
  METHOD:txsMergeMethod = UNSPECIFIED;
  /// Sources queried for this facility, including those that returned nothing.
  /// Never fewer than the number of SOURCES entries.
  PROVIDERS_CONSULTED:uint;
  /// Sources whose reported position fell within the publisher's agreement
  /// threshold. A value of 1 means the published position rests on a single
  /// report and was never independently corroborated.
  PROVIDERS_AGREEING:uint;
  /// Sources whose reported position fell OUTSIDE that threshold and were not
  /// reconciled. Non-zero is the machine-readable form of a contested
  /// position and is published alongside POSITION_DISPUTED.
  PROVIDERS_DISAGREEING:uint;
  /// PROVIDER_ID of the report the merge selected, copied verbatim from the
  /// matching SOURCES entry. Absent when METHOD is CENTROID: a computed
  /// position belongs to no single source.
  WINNING_PROVIDER_ID:string;
  /// Greatest surface distance in metres between any two agreeing reported
  /// positions. Zero is meaningful only when PROVIDERS_AGREEING is 1.
  POSITION_SPREAD_M:double;
  /// The publisher's own confidence in the merged position, on [0,1]. Never a
  /// source's figure and never a probability from a model this standard does
  /// not name.
  CONFIDENCE:double;
  /// RFC 3339 UTC fixed-millisecond instant at which the merge was performed.
  MERGED_AT:string;
}

/// A position the facility is asserted to have occupied and vacated, retained
/// so a relocation never silently rewrites history.
table TXSPriorPosition {
  /// Decimal degrees on WGS 84.
  LATITUDE:double;
  LONGITUDE:double;
  /// Class of authority behind THIS coordinate, which is frequently weaker
  /// than the authority behind the current one.
  POSITION_AUTHORITY:txsPositionAuthorityClass = UNSPECIFIED;
  /// One-sigma-equivalent horizontal envelope in metres, as the source states
  /// it. Zero means unpublished.
  POSITION_UNCERTAINTY_M:double;
  /// RFC 3339 UTC bounds over which the facility is asserted to have occupied
  /// this position. Either bound is absent when unpublished.
  VALID_FROM:string;
  VALID_UNTIL:string;
  /// PROVIDER_ID of the SOURCES entry asserting this position.
  PROVIDER_ID:string;
}

/// One documented emission of one facility: a carrier or channel the facility
/// is stated to radiate, with the power and antenna terms published for it.
///
/// A facility radiating many carriers carries many entries; a facility whose
/// frequency changes by season or hour carries the documented set here and the
/// time-bounded usage in `$STX`. Unknown terms are ABSENT.
table TXSEmission {
  /// Publisher-stable identifier for this emission within its facility record.
  EMISSION_ID:string;
  /// Assigned or nominal centre frequency in kilohertz. Kilohertz is the base
  /// unit for this family because it spans the low-frequency broadcasting
  /// allocations to the microwave allocations without unit switching; a
  /// consumer joining to `$RFB` or `$TBS`, which carry megahertz, or to
  /// `$IQC`, which carries hertz, converts at the join, explicitly. Zero means
  /// unpublished.
  FREQUENCY_KHZ:double;
  /// Necessary or occupied bandwidth in kilohertz as the source states it.
  /// Zero means unpublished.
  BANDWIDTH_KHZ:double;
  /// ITU emission designator verbatim, e.g. the necessary-bandwidth and
  /// class-of-emission string a licence record carries. Authoritative over
  /// MODULATION whenever both are present.
  EMISSION_DESIGNATOR:string;
  MODULATION:txsModulationClass = UNSPECIFIED;
  POLARIZATION:txsPolarization = UNSPECIFIED;
  /// Service class of THIS emission when it differs from the facility's.
  SERVICE:txsServiceClass = UNSPECIFIED;
  /// Transmitter output power at the antenna feed, kilowatts. Zero means
  /// unpublished. Never derived from radiated power.
  TRANSMITTER_POWER_KW:double;
  /// Effective radiated power referenced to a half-wave dipole, kilowatts.
  /// Zero means unpublished.
  EFFECTIVE_RADIATED_POWER_KW:double;
  /// Equivalent isotropically radiated power, kilowatts. Zero means
  /// unpublished. Published alongside, never instead of, the dipole-referenced
  /// figure: the two differ by the dipole gain and this standard never
  /// converts between them.
  EIRP_KW:double;
  /// Antenna centre of radiation above ground level, metres. Zero means
  /// unpublished.
  ANTENNA_HEIGHT_AGL_M:double;
  /// Main-lobe bearing, degrees clockwise from true north. Absent for a
  /// non-directional emission; a non-directional emission is stated by
  /// OMNIDIRECTIONAL, never by a bearing of zero.
  ANTENNA_AZIMUTH_DEG:double;
  /// The emission is radiated without a preferred bearing.
  OMNIDIRECTIONAL:bool = false;
  /// Half-power beamwidth in degrees. Zero means unpublished.
  BEAMWIDTH_DEG:double;
  /// Antenna gain in decibels referenced to an isotropic radiator. Zero means
  /// unpublished; a real 0 dBi figure is published as a source term in
  /// provenance rather than being indistinguishable from absence.
  ANTENNA_GAIN_DBI:double;
  /// Station identification radiated on this emission, verbatim: a callsign, a
  /// spoken or keyed identifier, or the identity string the source publishes.
  /// Never synthesized.
  STATION_IDENTITY:string;
  STATUS:txsOperationalStatus = UNSPECIFIED;
  /// RFC 3339 UTC bounds of the authorization or documented use of this
  /// emission. Either bound is absent when unpublished.
  VALID_FROM:string;
  VALID_UNTIL:string;
}

/// Terrestrial Transmitter Site.
table TXS {
  /// Publisher-stable identifier for this facility, unique within its record
  /// set. Never a source's own identifier and never a coordinate string.
  ID:string (required);
  /// Winning source's native facility identifier, copied verbatim from the
  /// SOURCES entry named by CONSENSUS.WINNING_PROVIDER_ID. Never a substitute
  /// for ID and never stable across sources.
  NATIVE_ID:string;
  /// Facility or structure name verbatim when a source publishes one. Never
  /// synthesized from coordinates, licensee, or nearest settlement.
  SITE_NAME:string;
  /// Station identification the facility as a whole answers to, verbatim: a
  /// callsign, an assigned station identifier, or the identifier an observer
  /// community records. Per-emission identity lives in
  /// EMISSIONS[].STATION_IDENTITY.
  STATION_IDENTITY:string;
  /// Licensee, operator or responsible administration name verbatim as the
  /// cited source states it. A display name, never an identifier: consumers
  /// must not treat it as a stable key.
  LICENSEE:string;
  /// Licence, assignment or authorization identifier verbatim.
  LICENSE_ID:string;
  /// Primary service class of the facility. Individual emissions may state
  /// their own.
  SERVICE:txsServiceClass = UNSPECIFIED;
  STATUS:txsOperationalStatus = UNSPECIFIED;
  /// ISO 3166-1 alpha-2 country code, uppercase, as the source states it.
  COUNTRY_CODE:string;
  /// Administrative subdivision or locality verbatim as the source states it.
  ADMIN_AREA:string;
  /// Published facility position, decimal degrees on WGS 84, produced by the
  /// merge described in CONSENSUS. ABSENT when no source publishes a position:
  /// a region centroid is never substituted. Per-source positions before
  /// reconciliation live in SOURCES[].REPORTED_LATITUDE/REPORTED_LONGITUDE and
  /// are never overwritten by this value.
  LATITUDE:double;
  LONGITUDE:double;
  /// The class of authority behind LATITUDE/LONGITUDE. A consumer that renders
  /// a position without reading this field is rendering an unlabelled claim.
  POSITION_AUTHORITY:txsPositionAuthorityClass = UNSPECIFIED;
  /// Horizontal envelope in metres within which the facility is asserted to
  /// lie, as the publisher states it. Zero means unpublished — never that the
  /// position is exact.
  POSITION_UNCERTAINTY_M:double;
  /// Credible consulted sources place the facility in materially different
  /// locations, or a source states the position is contested. The published
  /// coordinate remains the publisher's best merge; this flag forbids a
  /// consumer from presenting it as settled.
  POSITION_DISPUTED:bool = false;
  /// Positions the facility is asserted to have vacated, most recent first.
  PRIOR_POSITIONS:[TXSPriorPosition];
  /// Ground elevation at the facility, metres above mean sea level as the
  /// source states it. Zero means unpublished.
  GROUND_ELEVATION_AMSL_M:double;
  /// Overall height of the antenna-supporting structure above ground level,
  /// metres. Distinct from any emission's antenna height. Zero means
  /// unpublished.
  STRUCTURE_HEIGHT_AGL_M:double;
  STRUCTURE:txsStructureClass = UNSPECIFIED;
  /// Number of antenna-supporting structures at the facility. Zero means
  /// unpublished.
  STRUCTURE_COUNT:uint;
  /// Every emission the facility is documented to radiate.
  EMISSIONS:[TXSEmission];
  /// RFC 3339 UTC fixed-millisecond bounds of the documentation or observation
  /// window backing the published record.
  FIRST_OBSERVED:string;
  LAST_OBSERVED:string;
  /// Every source consulted for this facility, including sources that returned
  /// nothing. Required: a facility with no named sources is not publishable.
  SOURCES:[TXSProvenance] (required);
  /// How the entries in SOURCES were reduced to the published position.
  /// Required: a published position always states the rule that produced it,
  /// including SINGLE_SOURCE.
  CONSENSUS:TXSConsensus (required);
}

root_type TXS;
file_identifier "$TXS";

CVP.IDL:
// Hash: 76bc173a3d96aa6393a878867cf101a86b3f63d78690dc10ff6104a69d94a204
// Version: 1.186.0
// -----------------------------------END_HEADER
include "../RFL/main.fbs";

// Coverage Geometry (CVP)
// Description
// The durable coverage POLYGON: the packed ring geometry of a footprint,
// threshold contour, interference zone, union or gap region, stated with the
// metric and threshold that defines it, the epoch or interval it holds over,
// the generation it belongs to, the emitters that contributed, the receiver
// set it was evaluated for, the grid it was extracted from, and the
// uncertainty of both the level and the boundary.
//
// Division of labour: `$CVG` is an H3-indexed grid of figures of merit — it
// has cells and statistics and NO geometry, so a contour drawn from it cannot
// be published, only recomputed. `$CVP` is the geometry: rings a consumer can
// render, intersect, or serve without re-running the analysis. `$RFL` holds
// the per-link samples the field was built from; `$ACI` holds the intervals.
// A `$CVP` record MAY name the `$CVG` grid it was contoured from, and names
// the 3D obstacles that clipped it through `$RFS` materials rather than
// leaving a bitten-out footprint unexplained.
//
// PACKED RINGS. Vertices live in three parallel arrays; RING_OFFSETS carves
// them into rings; RING_POLYGON_INDEXES groups rings into polygons; RING_ROLES
// says which ring is an outer boundary and which is a hole. One record can
// therefore carry a whole multi-polygon coverage field in four small arrays
// instead of a tree of tables.
//
// GEOMETRY RULES, at the IDL and not left to the renderer:
//   - RING_OFFSETS has exactly RING_COUNT + 1 entries; ring r spans vertex
//     indexes [RING_OFFSETS[r], RING_OFFSETS[r+1]). The last entry equals the
//     vertex count.
//   - Rings are IMPLICITLY CLOSED. The first vertex is NOT repeated at the
//     end; a producer that repeats it publishes a degenerate edge.
//   - A ring has at least 3 vertices.
//   - OUTER rings wind counter-clockwise, INNER (hole) rings clockwise, seen
//     from outside the ellipsoid.
//   - A ring MUST NOT cross the ±180° meridian. A coverage region that spans
//     it is split into two rings of the same polygon, each terminating at the
//     meridian. Longitudes are in [-180, 180].
//   - Vertices are geodetic degrees on the ellipsoid named by
//     ALTITUDE_REFERENCE, never projected coordinates.
//
// ABSENT IS NOT ZERO, and a numeric field whose value is unknown is written
// NaN — the same rule the `$RFL` and `$ACI` records carry. A zero-area
// polygon, a 0 dB level and a 0 m uncertainty are all real claims.

/// Whether a ring bounds coverage or punches a hole in it.
///
/// `UNSPECIFIED` holds ordinal 0 deliberately, and a consumer MUST refuse a
/// ring that does not state its role rather than assume OUTER: assuming turns
/// a keep-out hole into a coverage claim.
enum cvpRingRole : byte {
  UNSPECIFIED = 0,
  OUTER,
  INNER
}

/// What the polygons of this record represent.
enum cvpGeometryKind : byte {
  UNSPECIFIED = 0,
  /// The boundary where the metric meets THRESHOLD_VALUE.
  THRESHOLD_CONTOUR,
  /// A set of iso-level contours; POLYGON_LEVEL_VALUES carries each level.
  ISO_METRIC_CONTOUR,
  /// The instantaneous beam or antenna footprint on the surface.
  FOOTPRINT,
  /// The horizon or terrain mask boundary for one endpoint.
  HORIZON_MASK,
  /// The region in which a stated interference criterion is exceeded.
  INTERFERENCE_ZONE,
  /// The union of many contributing footprints or contours.
  UNION_COVERAGE,
  /// The intersection of many contributing footprints or contours.
  INTERSECTION_COVERAGE,
  /// The region NOT covered — a gap, stated as geometry rather than left to
  /// be inferred by subtracting a coverage polygon from the globe.
  GAP_REGION,
  /// A region a transmitter is prohibited from illuminating.
  KEEP_OUT_ZONE
}

/// The surface the vertex altitudes are referenced to.
enum cvpAltitudeReference : byte {
  UNSPECIFIED = 0,
  WGS84_ELLIPSOID,
  MEAN_SEA_LEVEL,
  /// Draped on terrain from the dataset named in
  /// CVPProvenance.TERRAIN_DATASET.
  TERRAIN,
  /// A constant altitude plane; the value is in FIXED_ALTITUDE_M.
  FIXED_ALTITUDE
}

/// The part an emitter played in producing this geometry.
enum cvpEmitterRole : byte {
  UNSPECIFIED = 0,
  /// The wanted signal.
  WANTED,
  /// An interferer degrading the wanted signal.
  INTERFERER,
  /// An intermediate relay in a multi-hop chain.
  RELAY
}

/// An emitter that contributed to this geometry. Identity and the few
/// parameters that determine the boundary; everything else is joined from
/// `$RFB` and `$RFE`.
table CVPEmitterRef {
  /// Producer-stable emitter identifier within this record.
  EMITTER_ID: string (required);
  EMITTER_ROLE: cvpEmitterRole = UNSPECIFIED;
  /// `$RFE.ID` — the parametric emitter description.
  RFE_ID: string;
  /// `$RFB.ID` — the band specification.
  RFB_ID: string;
  /// `$CAT.NORAD_CAT_ID` when the emitter is on orbit. 0 when unbound.
  NORAD_CAT_ID: uint;
  /// `$CAT.OBJECT_ID` international designator.
  OBJECT_ID: string;
  /// `$TBS.SITE_ID` when the emitter is a terrestrial site.
  TBS_SITE_ID: string;
  /// Beam and channel within the emitter.
  ID_BEAM: string;
  CHANNEL_ID: string;
  /// Carrier centre frequency, megahertz — the `$RFB` convention.
  CENTER_FREQUENCY_MHZ: double;
  /// EIRP toward boresight used in the evaluation, dBW.
  EIRP_DBW: double;
  /// Polarization, defaulted to UNKNOWN explicitly because `rfPolarization`
  /// ordinal 0 is LHCP.
  POLARIZATION: rfPolarization = UNKNOWN;
  /// Emitter position at EPOCH, when the geometry is instantaneous. Geodetic
  /// degrees and metres. Absent means "join it from the source record" — a
  /// stale copied position is worse than none.
  LATITUDE_DEG: double;
  LONGITUDE_DEG: double;
  ALTITUDE_M: double;
  /// Weight of this emitter's contribution to a union or aggregate [0-1].
  CONTRIBUTION_WEIGHT: double;
}

/// A receiver the coverage was evaluated FOR. Coverage is never absolute: a
/// -110 dBW contour means one thing for a 60 cm terminal and another for a
/// 12 m dish, so the assumed receiver is part of the record.
table CVPReceiverRef {
  RECEIVER_ID: string (required);
  ENDPOINT_KIND: rflEndpointKind = UNSPECIFIED;
  /// `$GST.STATION_ID`, `$SIT` or `$TBS.SITE_ID`, per ENDPOINT_KIND.
  GST_STATION_ID: string;
  SIT_ID: string;
  TBS_SITE_ID: string;
  /// Receive antenna gain assumed, dBi.
  ANTENNA_GAIN_DBI: double;
  /// System noise temperature assumed, kelvin.
  SYSTEM_NOISE_TEMPERATURE_K: double;
  /// Figure of merit assumed, dB/K.
  GAIN_TO_NOISE_TEMPERATURE_DB_PER_K: double;
  /// Minimum elevation the receiver can work at, degrees.
  MIN_ELEVATION_DEG: double;
  /// Polarization, defaulted to UNKNOWN explicitly.
  POLARIZATION: rfPolarization = UNKNOWN;
  /// Receiver group this receiver belongs to, matching
  /// `$RFL.RFLLink.RECEIVER_GROUP_ID`.
  RECEIVER_GROUP_ID: string;
}

/// A 3D obstacle that shaped this coverage boundary. A footprint clipped by
/// buildings, a spacecraft structure or terrain is a claim about those
/// objects; publishing the obstacle set with its `$RFS` materials is what
/// makes the clipped boundary reproducible.
table CVPObstacleRef {
  /// Producer's identifier for the obstacle instance.
  OBSTACLE_ID: string (required);
  /// `$RFS.MATERIAL_ID` of the surface. Absent means the obstacle was treated
  /// as an opaque blocker with no material physics — which a consumer is
  /// entitled to know.
  MATERIAL_ID: string;
  /// `$RFS.RFSGeometryRef.GEOMETRY_REF_ID` of the exact geometry used.
  GEOMETRY_REF_ID: string;
  /// `$VAM` asset identity of the obstacle mesh.
  VAM_ID: string;
  VARIANT_ID: string;
  /// `$CAT` identity when the obstacle is a catalogued object. 0 when unbound.
  NORAD_CAT_ID: uint;
  OBJECT_ID: string;
  /// `$TBS.SITE_ID` when the obstacle is a structure at a terrestrial site.
  TBS_SITE_ID: string;
  /// How the obstacle acted on the field.
  INTERACTION: rflObstacleInteraction = UNSPECIFIED;
  /// Geodetic placement of a fixed obstacle, degrees and metres.
  LATITUDE_DEG: double;
  LONGITUDE_DEG: double;
  ALTITUDE_M: double;
  HEIGHT_M: double;
}

/// How wrong this geometry can be. A contour with no uncertainty is a drawing,
/// not a measurement.
table CVPUncertainty {
  /// 1-sigma horizontal position uncertainty of the boundary, metres. Applies
  /// to every vertex unless VERTEX_POSITION_UNCERTAINTY_M is present.
  HORIZONTAL_POSITION_M: double;
  /// 1-sigma uncertainty of the level the contour was drawn at, in
  /// LEVEL_UNCERTAINTY_UNITS.
  LEVEL_UNCERTAINTY: double;
  LEVEL_UNCERTAINTY_UNITS: string;
  /// Confidence the stated uncertainties correspond to [0-1], e.g. 0.68.
  CONFIDENCE: double;
  /// Tolerance the contour extractor converged to, in the metric's units.
  EXTRACTION_TOLERANCE: double;
  /// Simplification tolerance applied to the rings, metres. A simplified ring
  /// is not the computed boundary and MUST say so.
  SIMPLIFICATION_TOLERANCE_M: double;
  /// How the uncertainty was established (e.g. "grid resolution bound",
  /// "Monte Carlo over emitter state covariance").
  METHOD: string;
}

/// Where this geometry came from.
table CVPProvenance {
  METHOD: rflMethod = UNSPECIFIED;
  /// Producing system, dataset or campaign. Required.
  SOURCE: string (required);
  /// Replayable query or scenario reference.
  SOURCE_QUERY: string;
  /// Propagator that produced the emitter geometry. A MODELED or HYBRID
  /// product MUST name it.
  PROPAGATOR_ID: string;
  PROPAGATOR_VERSION: string;
  PROPAGATOR_CONFIGURATION: string;
  /// `$PLG.PLUGIN_ID` / `$PMM.MODULE_ID` that produced the rings.
  MODULE_ID: string;
  MODULE_VERSION: string;
  MODULE_CONTENT_HASH: string;
  /// Per-term model bindings for the metric that was contoured, reusing the
  /// `$RFL` binding so a footprint and the samples behind it cite the same
  /// models.
  MODELS: [RFLModelBinding];
  /// Algorithm that turned the sampled field into rings (e.g. "marching
  /// squares", "alpha shape", "H3 cell union").
  CONTOUR_ALGORITHM: string;
  /// Environment and terrain datasets the evaluation used.
  ENVIRONMENT_DATASET: string;
  TERRAIN_DATASET: string;
  /// Dataset the 3D obstacles and their materials were drawn from.
  OBSTACLE_DATASET: string;
  /// Unix ms computed and retrieved.
  COMPUTED_AT: uint64;
  RETRIEVED_AT: uint64;
  /// Licence terms. Empty means UNKNOWN TERMS.
  LICENSE: string;
  NON_COMMERCIAL_ONLY: bool;
  CITATION: string;
}

/// Coverage Geometry
table CVP {
  /// Stable identifier of this geometry product.
  COVERAGE_ID: string (required);
  /// Display name.
  NAME: string;
  /// Analysis or scenario grouping identifier shared with the `$RFL` samples
  /// and `$ACI` intervals of the same study.
  SCENARIO_ID: string;
  GEOMETRY_KIND: cvpGeometryKind = UNSPECIFIED;

  /// The metric the rings contour.
  METRIC: rflBudgetTerm = UNSPECIFIED;
  /// Units of the metric and of POLYGON_LEVEL_VALUES.
  METRIC_UNITS: string;
  /// The threshold the boundary was drawn at, for a THRESHOLD_CONTOUR.
  THRESHOLD_VALUE: double;
  THRESHOLD_UNITS: string;
  THRESHOLD_COMPARISON: rflComparison = UNSPECIFIED;

  /// Instantaneous epoch, seconds since 1970-01-01T00:00:00 in TIME_SYSTEM.
  /// Set for FOOTPRINT and other instantaneous products; NaN for aggregates.
  EPOCH: double;
  /// Interval this geometry holds over, same encoding. Set for aggregated
  /// products (union over a window, availability contour); NaN for
  /// instantaneous ones. A product that states neither EPOCH nor an interval
  /// is untethered in time and MUST be refused.
  INTERVAL_START: double;
  INTERVAL_STOP: double;
  /// Time scale all epochs in this record are expressed in. Defaults to UTC
  /// explicitly: `timingStandard` ordinal 0 is GMST.
  TIME_SYSTEM: timingStandard = UTC;

  /// Monotonic generation of this coverage product within its COVERAGE_ID
  /// lineage. A streaming producer increments it per emission; a consumer
  /// holding a higher generation MUST NOT be overwritten by a lower one.
  GENERATION: uint64;
  /// COVERAGE_ID this record replaces, when the lineage was re-identified.
  SUPERSEDES_COVERAGE_ID: string;

  // ---- Packed rings ----
  /// Vertex longitudes, geodetic degrees in [-180, 180].
  VERTEX_LONGITUDE_DEG: [double] (required);
  /// Vertex latitudes, geodetic degrees in [-90, 90]. Same length as
  /// VERTEX_LONGITUDE_DEG.
  VERTEX_LATITUDE_DEG: [double] (required);
  /// Vertex altitudes, metres above ALTITUDE_REFERENCE. Absent when the
  /// geometry lies on the reference surface.
  VERTEX_ALTITUDE_M: [double];
  ALTITUDE_REFERENCE: cvpAltitudeReference = UNSPECIFIED;
  /// The constant altitude, metres, when ALTITUDE_REFERENCE is FIXED_ALTITUDE.
  FIXED_ALTITUDE_M: double;
  /// Ring start indexes; RING_COUNT + 1 entries, last equals the vertex count.
  RING_OFFSETS: [uint32] (required);
  /// Polygon each ring belongs to. Same length as RING_COUNT.
  RING_POLYGON_INDEXES: [uint32] (required);
  /// Role of each ring. Same length as RING_COUNT.
  RING_ROLES: [cvpRingRole] (required);
  /// Number of polygons; equals max(RING_POLYGON_INDEXES) + 1 and is published
  /// so an empty coverage field (zero polygons, zero rings) is representable
  /// and distinguishable from an unpopulated record.
  POLYGON_COUNT: uint32;
  /// Metric value each polygon is drawn at, in METRIC_UNITS. Same length as
  /// POLYGON_COUNT. Carried for ISO_METRIC_CONTOUR; for a THRESHOLD_CONTOUR
  /// every entry equals THRESHOLD_VALUE.
  POLYGON_LEVEL_VALUES: [double];
  /// 1-sigma uncertainty of each polygon's level, same units and length.
  POLYGON_LEVEL_UNCERTAINTIES: [double];
  /// Surface area enclosed by each polygon, square kilometres.
  POLYGON_AREA_KM2: [double];
  /// Per-vertex 1-sigma horizontal uncertainty, metres. Same length as the
  /// vertex arrays. Absent means CVPUncertainty.HORIZONTAL_POSITION_M governs
  /// the whole boundary.
  VERTEX_POSITION_UNCERTAINTY_M: [double];

  // ---- Source grid ----
  /// Grid the field was sampled on before contouring, e.g. "H3" or
  /// "GEODETIC_LATLON". A contour is never finer than the grid behind it.
  GRID_SCHEME: string;
  /// Grid resolution in the scheme's own convention (H3 resolution 0-15).
  GRID_RESOLUTION: uint8;
  /// Grid spacing in degrees, for a geodetic lat/lon grid.
  GRID_SPACING_DEG: double;
  /// Number of grid cells evaluated.
  GRID_CELL_COUNT: uint64;
  /// `$CVG.COVERAGE_ID` of the figure-of-merit grid this geometry was
  /// contoured from, when one was published.
  CVG_COVERAGE_ID: string;
  /// `$RFL.RFL_ID` of the sample set the field was evaluated from, when one
  /// was published.
  RFL_ID: string;
  /// `$ACI.ACI_ID` of the interval set an availability or gap product was
  /// aggregated from, when one was published.
  ACI_ID: string;

  // ---- Participants ----
  /// Emitters that contributed. Required: coverage with no stated emitter is
  /// an unattributable claim about the sky.
  CONTRIBUTING_EMITTERS: [CVPEmitterRef] (required);
  /// Identifier of the receiver set this coverage is stated for.
  RECEIVER_SET_ID: string;
  /// The receivers themselves, when the set is enumerable.
  RECEIVERS: [CVPReceiverRef];
  /// 3D obstacles that clipped or shaped the boundary, each naming the `$RFS`
  /// material that produced its effect.
  CONTRIBUTING_OBSTACLES: [CVPObstacleRef];
  /// Identifier of the obstacle set used, when it is published as a set rather
  /// than enumerated here.
  OBSTACLE_SET_ID: string;

  /// The condition that bounds the boundary — why the contour is where it is.
  LIMITING_CONSTRAINT: rflConstraint = UNSPECIFIED;
  /// Verbatim description, required when LIMITING_CONSTRAINT is OTHER.
  LIMITING_CONSTRAINT_NOTE: string;

  /// Uncertainty of level and boundary.
  UNCERTAINTY: CVPUncertainty;
  /// Provenance. Required.
  PROVENANCE: CVPProvenance (required);
  /// Unix ms this record was serialized.
  COMPUTED_AT: uint64;
  /// `$EPM` identifier of the producing node.
  PRODUCER_ID: string;
  /// Ed25519 signature by the producing `$EPM`.
  SIGNATURE: [ubyte];
}

root_type CVP;
file_identifier "$CVP";

SDR.IDL:
// Hash: 34a8f4ac3b5b7043add8ee49977baa17bfb63c1cd3a53b2ae64490e7743eb88b
// Version: 0.0.2
// -----------------------------------END_HEADER
/// Sensor Detection Report — runtime I/O contract for sensor detection
/// plugins. Distinct from SNR (sensor hardware catalog) and SEN (sensor
/// maintenance log); SDR carries per-frame target states, configuration,
/// and detection results.

/// Sensor category for a report.
enum sensorCategory : ubyte {
  RADAR,
  ELECTRO_OPTICAL,
  INFRARED,
  ACOUSTIC,
  RF,
  LIDAR,
  CUSTOM = 255
}

/// Sensor operational-state bit flags.
enum sensorOperationalFlags : uint (bit_flags) {
  ACTIVE,
  TRACK_MODE,
  SEARCH_MODE,
  JAMMED,
  SLEWING,
  CALIBRATING
}

/// Detection result bit flags.
enum detectionResultFlags : uint (bit_flags) {
  VALID,
  TRACKED,
  MARGINAL,
  IN_CLUTTER,
  JAMMED,
  SIDELOBE,
  MERGED
}

/// Target state input (40 bytes, 8-byte aligned).
struct targetState {
  /// Target position X in ECEF (meters).
  POS_X:double;
  /// Target position Y in ECEF (meters).
  POS_Y:double;
  /// Target position Z in ECEF (meters).
  POS_Z:double;
  /// Radar cross section (m^2).
  RCS:double;
  /// Unique target identifier.
  TARGET_ID:uint;
  /// Target flags (reserved).
  FLAGS:uint;
}

/// Detection result output (48 bytes, 8-byte aligned).
struct detectionResult {
  /// Index of target in input array.
  TARGET_INDEX:uint;
  /// Detection flag (1 == detected, 0 == not detected).
  DETECTED:uint;
  /// Range to target (meters).
  RANGE:double;
  /// Signal-to-noise ratio (dB).
  SNR:double;
  /// Doppler shift (Hz).
  DOPPLER:double;
  /// Probability of detection (0.0 – 1.0).
  PROBABILITY:double;
  /// Detection flags (detectionResultFlags bitfield).
  FLAGS:uint;
  /// Reserved for future use.
  RESERVED:uint;
}

/// Radar sensor configuration.
table SDRRadarConfig {
  /// Operating frequency (Hz).
  FREQUENCY:double;
  /// Transmit power (W).
  POWER:double;
  /// Antenna gain (dB).
  GAIN:double;
  /// Receiver bandwidth (Hz).
  BANDWIDTH:double;
  /// Noise figure (dB).
  NOISE_FIGURE:double;
  /// System losses (dB).
  SYSTEM_LOSS:double;
  /// Pulse repetition frequency (Hz).
  PRF:double;
  /// Pulse width (seconds).
  PULSE_WIDTH:double;
  /// Detection threshold SNR (dB).
  DETECTION_THRESHOLD:double;
  /// Minimum detection range (meters).
  MIN_RANGE:double;
  /// Maximum detection range (meters).
  MAX_RANGE:double;
}

/// Generic sensor configuration.
table SDRSensorConfig {
  CATEGORY:sensorCategory;
  /// Sensor position in ECEF (meters) — X.
  POS_X:double;
  /// Sensor position in ECEF (meters) — Y.
  POS_Y:double;
  /// Sensor position in ECEF (meters) — Z.
  POS_Z:double;
  /// Sensor orientation as quaternion (W, X, Y, Z).
  ORIENT_W:double;
  ORIENT_X:double;
  ORIENT_Y:double;
  ORIENT_Z:double;
  /// Radar-specific config when CATEGORY == RADAR.
  RADAR:SDRRadarConfig;
  /// Operational flags.
  FLAGS:sensorOperationalFlags;
}

/// Batch detection request (arena-addressed, zero-copy).
table SDRBatchRequest {
  /// Sensor position in ECEF (meters) — X.
  SENSOR_POS_X:double;
  SENSOR_POS_Y:double;
  SENSOR_POS_Z:double;
  /// Sensor orientation as quaternion (W, X, Y, Z).
  SENSOR_ORIENT_W:double;
  SENSOR_ORIENT_X:double;
  SENSOR_ORIENT_Y:double;
  SENSOR_ORIENT_Z:double;
  /// Input buffer offset where targetState[] starts.
  INPUT_OFFSET:uint;
  /// Number of targets in the input buffer.
  TARGET_COUNT:uint;
  /// Output buffer offset where detectionResult[] is written.
  OUTPUT_OFFSET:uint;
  /// Current time as a Julian date.
  EPOCH:double;
}

/// Batch detection response header.
table SDRBatchResponse {
  /// Number of detection results written.
  COUNT:uint;
  /// Number of targets detected (SNR >= threshold).
  DETECTED_COUNT:uint;
  /// Offset in arena where detectionResult[] starts.
  OUTPUT_OFFSET:uint;
  /// Error code (0 == success).
  ERROR_CODE:int;
  /// Error message when ERROR_CODE != 0.
  ERROR_MESSAGE:string;
}

/// Compact single-frame detection input used by pluggable sensor models that
/// do not drive arena-backed batches.
table SDRSingleInput {
  /// Target position in ECEF (meters) — X.
  TARGET_POS_X:double;
  TARGET_POS_Y:double;
  TARGET_POS_Z:double;
  /// Sensor position in ECEF (meters) — X.
  SENSOR_POS_X:double;
  SENSOR_POS_Y:double;
  SENSOR_POS_Z:double;
  /// Radar cross section (m^2).
  RCS:double;
  /// Sensor operating frequency (Hz).
  FREQUENCY:double;
  /// Transmit power (W).
  TX_POWER:double;
  /// Unix timestamp (milliseconds since epoch).
  TIMESTAMP_MS:ulong;
}

/// Compact single-frame detection result.
table SDRSingleResult {
  DETECTED:bool;
  /// Range to target (meters).
  RANGE:double;
  /// Signal-to-noise ratio (dB).
  SNR:double;
  /// Azimuth angle to target (radians).
  AZIMUTH:double;
  /// Elevation angle to target (radians).
  ELEVATION:double;
  /// Range rate / Doppler velocity (m/s).
  RANGE_RATE:double;
  /// Detection timestamp (milliseconds since epoch).
  TIMESTAMP_MS:ulong;
  /// Track identifier (0 if not tracking).
  TRACK_ID:uint;
}

/// Sensor Detection Report envelope message.
table SDR {
  CONFIG:SDRSensorConfig;
  BATCH_REQUEST:SDRBatchRequest;
  BATCH_RESPONSE:SDRBatchResponse;
  SINGLE_INPUT:SDRSingleInput;
  SINGLE_RESULT:SDRSingleResult;
}

root_type SDR;
file_identifier "$SDR";

DFH.IDL:
// Hash: a6155b3ad1a4ea6cd57d7efcad9a9ea81f39ae9a23e0e712c4f8de03580daf49
// Version: 0.0.3
// -----------------------------------END_HEADER
/// GEO Drift History Record
