  /// Longitude oscillation amplitude in degrees
  LONGITUDE_AMPLITUDE:double;
  /// Eccentricity
  ECCENTRICITY:double;
  /// Inclination in degrees
  INCLINATION:double;
}

/// GEO Drift History
table DFH {
  /// Unique identifier
  ID:string;
  /// Satellite number
  SAT_NO:uint32;
  /// Object designator
  OBJECT_DESIGNATOR:string;
  /// Object common name
  OBJECT_NAME:string;
  /// History start time (ISO 8601)
  START_TIME:string;
  /// History end time (ISO 8601)
  END_TIME:string;
  /// Current effective until date (ISO 8601)
  EFFECTIVE_UNTIL:string;
  /// Current drift rate in degrees/day
  DRIFT_RATE:double;
  /// Current mean longitude in degrees East
  MEAN_LONGITUDE:double;
  /// Longitude slot center in degrees East (if station-keeping)
  SLOT_CENTER:double;
  /// Longitude slot half-width in degrees
  SLOT_HALF_WIDTH:double;
  /// Whether object is actively station-keeping
  STATION_KEEPING:bool;
  /// Historical drift records
