  /// Final position Y component (km).
  R2_Y:double;
  /// Final position Z component (km).
  R2_Z:double;
  /// Time of flight (seconds). Must be greater than zero.
  TOF_SEC:double;
  /// Central-body gravitational parameter (km^3/s^2). Must be greater than zero.
