QRP.IDL:
// Hash: a280c96b15827928d4ee27fae810065c22510d33111dbfa2908d0cc0db751255
// Version: 1.207.0
// -----------------------------------END_HEADER
/// Query Page (QRP)
/// Description
/// The one request, page-header and error frame for every paged, searched or
/// aggregated read of standards records over a stream of size-prefixed
/// records. A request names the standard, the selection (SQL, search text or
/// field filters), the lane (provider, source, batch, producer, origin), an
/// epoch window and a page. A page header precedes RECORD_COUNT record frames
/// of the named standard and accounts honestly for what was scanned: PARTIAL is
/// true when a bounded scan returned before covering every stored record, so a
/// reader never waits and never mistakes a bounded page for the whole set. An
/// error is exactly one frame with KIND Error; the HTTP status stays honest
/// beside it. Cursors are opaque strings issued by the serving node.

/// Role of a frame. Append new values only; never reorder or reuse existing
/// values.
enum qrpKind : byte {
  Request,
  Page,
  Error
}

/// Outcome of a page. Append new values only; never reorder or reuse existing
/// values.
enum qrpStatus : byte {
  Ok,
  /// A bounded scan returned before covering every stored record.
  Partial,
  /// The store is busy; retry after RETRY_AFTER_MS.
  Busy,
  /// The serving snapshot is not warm yet; retry after RETRY_AFTER_MS.
  Cold,
  Error
}

/// Comparison operator of a field filter. Append new values only; never
/// reorder or reuse existing values.
enum qrpFilterOp : byte {
  Eq,
  Ne,
  Lt,
  Lte,
  Gt,
  Gte,
  Contains,
  In
}

/// One field filter of a request.
table QRPFilter {
  FIELD: string;
  OP: qrpFilterOp = Eq;
  /// Value as text; for In, values separated by commas.
  VALUE: string;
}

/// One column descriptor of a page, in record field order.
table QRPColumn {
  NAME: string;
  /// Scalar type of the field as declared in the standard, e.g. "string",
  /// "double", "int64", "bool", "enum".
  TYPE: string;
  /// Unit of the field when the standard declares one, else empty.
  UNIT: string;
  /// True when the serving node can order the page by this column.
  SORTABLE: bool;
  /// True when the serving node holds an index on this column.
  INDEXED: bool;
}

/// Query Page - request, page header or error frame.
table QRP {
  KIND: qrpKind = Request;
  STATUS: qrpStatus = Ok;
  /// Stable error code when STATUS is Error, Busy or Cold.
  ERROR_CODE: string;
  /// Human-readable detail for an error, warning or partial page.
  MESSAGE: string;
  /// Milliseconds a client should wait before retrying; 0 = no advice.
  RETRY_AFTER_MS: uint32;
  /// Standard code of the records selected, e.g. "OMM".
  SCHEMA_NAME: string;
  /// File identifier of the record frames that follow a page header.
  FILE_IDENTIFIER: string;
  /// SQL selection over the standard's table, when the lane accepts SQL.
  SQL: string;
  /// Free-text search over the standard's indexed text fields.
  SEARCH: string;
  FILTERS: [QRPFilter];
  SORT_FIELD: string;
  SORT_DESC: bool;
  PROVIDER_ID: string;
  SOURCE_NAME: string;
  BATCH_ID: string;
  /// Restrict to records whose producer is this peer.
  PRODUCER_PEER_ID: string;
  /// Restrict to records retrieved from this upstream origin.
  ORIGIN_ID: string;
  /// Epoch window, Unix milliseconds; 0 = unbounded.
  FROM_EPOCH_MS: int64;
  TO_EPOCH_MS: int64;
  /// 1-based page number requested or served.
  PAGE: uint32;
  /// Page size requested or served.
  LIMIT: uint32;
  /// Opaque cursor of this page.
  CURSOR: string;
  /// Opaque cursor of the next page; empty when this is the last page.
  NEXT_CURSOR: string;
  /// Record frames that follow this page header.
  RECORD_COUNT: uint32;
  /// Records matching the selection when known; 0 = unknown.
  TOTAL_COUNT: uint64;
  /// Records the serving node scanned to build this page.
  SCANNED: uint64;
  /// Records the serving node holds for the standard.
  STORED: uint64;
  /// True when a bounded scan returned before covering every stored record.
  PARTIAL: bool;
  /// True when the page was cut at a byte or row budget.
  TRUNCATED: bool;
  /// Unix milliseconds the serving numbers were last true.
  AS_OF_MS: int64;
  /// True when the page was served from a stale snapshot.
  STALE: bool;
  /// Milliseconds the serving node spent producing the page.
  ELAPSED_MS: uint32;
  /// Unix milliseconds when the page was generated.
  GENERATED_AT_MS: int64;
  /// Entity tag of the page for conditional requests.
  ETAG: string;
  /// Content identifier named by a request or a reply (record, manifest,
  /// archive).
  CID: string;
  /// Archive identifier named by a request or a reply.
  ARCHIVE_ID: string;
  COLUMNS: [QRPColumn];
}

root_type QRP;
file_identifier "$QRP";

TMS.IDL:
// Hash: 562adbee5bb4a54b04c26ca715faee9e18695774956c4e2373fb072b4526ec2a
// Version: 1.191.0
// -----------------------------------END_HEADER
include "../TRK/main.fbs";

// Track Model State (TMS)
// Description
// The propagatable model state of one live air or maritime track: position,
// motion, the identifier of the dead-reckoning model that extrapolates it,
// the model's parameters, and the innovation-gate and staleness policy the
// publisher applied. This is the OMM/TLE paradigm generalized off-orbit —
// the record is MODEL STATE, not a position report: a consumer propagates it
// through a pluggable propagator port and receives an update only when a new
// observation disagrees with the model beyond the published gate.
//
// ONE standard carries both domains: `ENVIRONMENT` (the `$TRK`
// trackEnvironment enum, reused verbatim) is the domain axis; air and
// maritime tracks propagate under the same contract and forking the code
// would fork the propagation contract for no schema difference. `$TRK`
// itself is a fused tactical contact report and carries no model, epoch
// basis, or gate; the two join on track identity, they never substitute.
//
// IDENTIFIERS ARE SCHEME-TAGGED. Transponder and station identity systems
// are never field names; each identity rides as an IDENTIFIERS entry whose
// SCHEME token names the identity system verbatim and whose VALUE is the
// identifier verbatim. The standard names no identity system.
//
// ABSENT IS NOT ZERO. A numeric field whose value is unknown is written
// NaN. A ground speed of 0, a vertical rate of 0 and a heading of 0 are all
// real claims.

/// One parameter of the propagation model, stated by name so a model
/// registry can evolve without schema change.
table TMSModelParameter {
  /// Parameter name within the MODEL_ID model's own registry, verbatim.
  NAME:string (required);
  /// Parameter value.
  VALUE:double;
  /// Units of VALUE, verbatim. Required: a unitless parameter states so
  /// explicitly (e.g. "1").
  UNITS:string (required);
}

/// One identity the track is known by in a named identity scheme.
table TMSIdentifier {
  /// Identity scheme token, verbatim (the identity system's own name).
  /// Never a field name and never normalized by the publisher.
  SCHEME:string (required);
  /// The identifier within that scheme, verbatim.
  VALUE:string (required);
}

/// Dataset lineage and redistribution terms for one track model state.
///
/// Required on every record: a redistributed track whose feed, epoch, and
/// licence are unstated is not publishable. The standard names no feed,
/// provider, or site.
table TMSProvenance {
  /// Publisher-stable, lowercase identifier for the feed or dataset this
  /// state was derived from, unique within the publisher's own dataset
  /// registry. Never a display name and never a URL.
  DATASET_ID:string (required);
  /// The feed or dataset's own name, verbatim as its publisher states it.
  DATASET_NAME:string;
  /// Replayable URL of the feed or dataset as published.
  DATASET_URL:string;
  /// RFC 3339 UTC fixed-millisecond epoch of the dataset edition or feed
  /// session this state was derived from.
  DATASET_EPOCH:string (required);
  /// Content identifier of the exact dataset artifact, when one exists.
  DATASET_CID:string;
  /// Replayable URL identifying the source material within the dataset.
  SOURCE_URL:string;
  /// The exact query, filter, or subscription used.
  SOURCE_QUERY:string;
  /// RFC 3339 UTC fixed-millisecond retrieval timestamp of the observation
  /// this state was updated from.
  RETRIEVED_AT:string (required);
  /// Redistribution terms verbatim. Unknown terms are never public domain
  /// and never an implied grant.
  LICENSE:string (required);
  /// URL of the full licence text as the source publishes it.
  LICENSE_URL:string;
  /// Attribution text the licence requires a redistributor to display.
  ATTRIBUTION:string;
  /// The licence forbids commercial use.
  NON_COMMERCIAL_ONLY:bool = false;
  /// The licence obliges derived works to carry the same terms.
  SHARE_ALIKE:bool = false;
  /// The source's own identifier for the track or observation stream this
  /// state was derived from, verbatim.
  NATIVE_ID:string (required);
  /// RFC 3339 UTC instant the source last modified or emitted the
  /// underlying observation, as the source states it.
  NATIVE_MODIFIED:string;
}

/// Track Model State
table TMS {
  /// Publisher-stable identifier for this state record.
  ID:string (required);
  /// Publisher-stable identifier of the track this state belongs to, held
  /// constant across every state update of the same track.
  TRACK_ID:string;
  /// Domain the track moves in. The `$TRK` enum reused verbatim; ordinal 0
  /// is SPACE, so a publisher MUST set this field — it is defaulted to
  /// UNKNOWN explicitly so an unset field can never be read as SPACE.
  ENVIRONMENT:trackEnvironment = UNKNOWN;
  /// RFC 3339 UTC fixed-millisecond epoch this state is valid at. The
  /// propagation origin: every kinematic field below is stated at EPOCH.
  EPOCH:string (required);

  // ---- Kinematic state at EPOCH ----
  /// Latitude, decimal degrees on WGS 84, positive north.
  LATITUDE:double;
  /// Longitude, decimal degrees on WGS 84, positive east, in [-180, 180].
  LONGITUDE:double;
  /// Altitude, metres above the WGS 84 ellipsoid. NaN for a surface track
  /// whose source publishes no altitude.
  ALTITUDE_M:double;
  /// Speed over ground, metres per second.
  GROUND_SPEED_MPS:double;
  /// Velocity components, metres per second, local NED-derived axes:
  /// north, east, and up. Published when the source or filter resolves
  /// them; NaN otherwise.
  VELOCITY_NORTH_MPS:double;
  VELOCITY_EAST_MPS:double;
  VELOCITY_UP_MPS:double;
  /// Heading, degrees true, [0, 360): the direction the vehicle points.
  HEADING_DEG:double;
  /// Course over ground, degrees true, [0, 360): the direction it moves.
  COURSE_DEG:double;
  /// Turn rate, degrees per second, positive clockwise seen from above.
  TURN_RATE_DPS:double;
  /// Vertical rate, metres per second, positive up.
  VERTICAL_RATE_MPS:double;

  // ---- Propagation model ----
  /// Identifier of the dead-reckoning or motion model that extrapolates
  /// this state, a key into the publisher's model registry. Required: a
  /// state with no model is a position report, which this record is not.
  MODEL_ID:string (required);
  /// Parameters of that model, named per its own registry.
  MODEL_PARAMETERS:[TMSModelParameter];
  /// RFC 3339 UTC instant beyond which the publisher no longer stands
  /// behind propagation of this state.
  PROPAGATION_VALID_UNTIL:string;
  /// 1-sigma horizontal position uncertainty at EPOCH, metres.
  POSITION_UNCERTAINTY_M:double;

  // ---- Innovation gate and staleness policy ----
  /// Gate in standard deviations: an observation whose innovation exceeds
  /// this many sigma of POSITION_UNCERTAINTY_M breached the model and
  /// produced this update.
  INNOVATION_GATE_SIGMA:double;
  /// Gate as an absolute distance, metres, when the publisher gates on
  /// distance rather than sigma.
  INNOVATION_GATE_DISTANCE_M:double;
  /// Publisher's stated tolerance, metres, within which propagation of this
  /// state is considered to agree with truth.
  TOLERANCE_M:double;
  /// Track status. The `$TRK` enum reused verbatim; ordinal 0 is ACTIVE,
  /// so a publisher MUST set this field on every record — an unset field
  /// reads as ACTIVE and a consumer cannot distinguish the two.
  TRACK_STATUS:TrkTrackStatus = ACTIVE;
  /// Seconds after LAST_UPDATE_EPOCH at which a consumer MUST mark the
  /// track stale.
  STALE_AFTER_S:double;
  /// Seconds after LAST_UPDATE_EPOCH at which a consumer MUST drop the
  /// track.
  DROP_AFTER_S:double;
  /// RFC 3339 UTC fixed-millisecond epoch of the last source observation
  /// that updated this track — the staleness clock origin. EPOCH may lag it
  /// when the publisher re-emits a keepalive state.
  LAST_UPDATE_EPOCH:string;

  /// Every identity the track is known by, scheme-tagged.
  IDENTIFIERS:[TMSIdentifier];
  /// Feed lineage and licence. Required.
  SOURCE:TMSProvenance (required);
}

root_type TMS;
file_identifier "$TMS";

NUM.IDL:
// Hash: 1f74c19a776f826ac31ebf88531a244afea55581a12edf6b3a6455b50a9fd34c
// Version: 1.113.5
// -----------------------------------END_HEADER
// Shared numerical utility records for reusable math modules.

enum numOperationCode : byte {
  UNKNOWN = 0,
  /// Solve for a scalar root using Newton-Raphson iteration.
  NEWTON_RAPHSON = 1,
  /// Linearly interpolate one scalar between two scalar samples.
  LINEAR_INTERPOLATION = 2,
  /// Bilinearly interpolate one scalar from four rectangular-corner samples.
  BILINEAR_INTERPOLATION = 3,
  /// Generate a bounded Gauss-Markov random sequence and summary statistics.
  GAUSS_MARKOV_SEQUENCE = 4
}

enum numFunctionCode : byte {
  UNKNOWN = 0,
  /// f(x) = x * x - TARGET_VALUE, with derivative f'(x) = 2 * x.
  QUADRATIC_MINUS_CONSTANT = 1
}

enum numResultStatus : byte {
  /// Operation completed.
  OK = 0,
  /// Request fields are missing, non-finite, or numerically invalid.
  INVALID_INPUT = 1,
  /// The requested operation or function is not supported.
  UNSUPPORTED_OPERATION = 2,
  /// Iteration did not reach ACCURACY within MAX_ITERATIONS.
  DID_NOT_CONVERGE = 3
}

enum numDiscretizeRoundDirection : byte {
  /// Round magnitude toward zero before restoring sign.
  TO_ZERO = 0,
  /// Round magnitude away from zero before restoring sign.
  FROM_ZERO = 1,
  /// Round magnitude to the nearest least-significant-bit multiple before restoring sign.
  NEAR = 2
}

/// Request for one scalar numerical root-solving operation.
table NUMRootSolveRequest {
  OPERATION:numOperationCode;
  FUNCTION:numFunctionCode;
  INITIAL_ESTIMATE:double;
  TARGET_VALUE:double;
  ACCURACY:double;
  MAX_ITERATIONS:uint32;
  TRACE_ID:string;
}

/// Result of one scalar numerical root-solving operation.
table NUMRootSolveResult {
  STATUS:numResultStatus;
  ERROR_MESSAGE:string;
  ROOT:double;
  RESIDUAL:double;
  ITERATIONS:uint32;
  TRACE_ID:string;
}

/// Request for component-wise vector saturation.
table NUMVectorSaturateRequest {
  /// Input vector to clamp.
  STATE:[double];
  /// Per-component lower bounds. Length must match STATE.
  LOWER_BOUNDS:[double];
  /// Per-component upper bounds. Length must match STATE.
  UPPER_BOUNDS:[double];
  /// Optional trace/correlation identifier.
  TRACE_ID:string;
}

/// Result of one component-wise vector saturation operation.
table NUMVectorSaturateResult {
  STATUS:numResultStatus;
  ERROR_MESSAGE:string;
  /// Saturated output vector.
  SATURATED_STATE:[double];
  /// Caller trace/correlation identifier copied from the request when present.
  TRACE_ID:string;
}

/// Request for component-wise vector discretization.
table NUMVectorDiscretizeRequest {
  /// Input vector to quantize.
  STATE:[double];
  /// Per-component least-significant-bit size. Length must match STATE.
  LSB:[double];
  /// Rounding direction used before the original sign is restored.
  ROUND_DIRECTION:numDiscretizeRoundDirection;
  /// When true, PREVIOUS_ERROR is added to STATE before discretization.
  CARRY_ERROR:bool;
  /// Optional prior discretization error vector from an earlier result.
  PREVIOUS_ERROR:[double];
  /// Optional trace/correlation identifier.
  TRACE_ID:string;
}

/// Result of one component-wise vector discretization operation.
table NUMVectorDiscretizeResult {
  STATUS:numResultStatus;
  ERROR_MESSAGE:string;
  /// Quantized output vector.
  DISCRETIZED_STATE:[double];
  /// Input-minus-output error after any requested carried error was applied.
  DISCRETIZATION_ERROR:[double];
  /// Caller trace/correlation identifier copied from the request when present.
  TRACE_ID:string;
}

/// Request for one scalar interpolation operation.
table NUMScalarInterpolationRequest {
  /// LINEAR_INTERPOLATION or BILINEAR_INTERPOLATION.
  OPERATION:numOperationCode;
  /// First x-coordinate bound.
  X1:double;
  /// Second x-coordinate bound.
  X2:double;
  /// First y-coordinate bound for bilinear interpolation.
  Y1:double;
  /// Second y-coordinate bound for bilinear interpolation.
  Y2:double;
  /// Linear interpolation value at X1.
  VALUE1:double;
  /// Linear interpolation value at X2.
  VALUE2:double;
  /// Bilinear corner value at X1,Y1.
  Z11:double;
  /// Bilinear corner value at X1,Y2.
  Z12:double;
  /// Bilinear corner value at X2,Y1.
  Z21:double;
  /// Bilinear corner value at X2,Y2.
  Z22:double;
  /// X coordinate to interpolate.
  INTERPOLATION_X:double;
  /// Y coordinate to interpolate for bilinear interpolation.
  INTERPOLATION_Y:double;
  /// Optional trace/correlation identifier.
  TRACE_ID:string;
}

/// Result of one scalar interpolation operation.
table NUMScalarInterpolationResult {
  STATUS:numResultStatus;
  ERROR_MESSAGE:string;
  /// Interpolated scalar value.
  VALUE:double;
  /// Caller trace/correlation identifier copied from the request when present.
  TRACE_ID:string;
}

/// Request for one first-order Gauss-Markov random sequence.
table NUMGaussMarkovRequest {
  /// GAUSS_MARKOV_SEQUENCE.
  OPERATION:numOperationCode;
  /// Number of scalar states per sample.
  DIMENSION:uint32;
  /// Number of post-warmup samples used in the result statistics.
  SAMPLE_COUNT:uint32;
  /// Number of initial state propagations excluded from the result statistics.
  WARMUP_COUNT:uint32;
  /// Seed for the standard-normal generator.
  RNG_SEED:uint32;
  /// Row-major DIMENSION x DIMENSION state propagation matrix.
  PROPAGATION_MATRIX:[double];
  /// Row-major DIMENSION x DIMENSION standard-normal noise mixing matrix.
  NOISE_MATRIX:[double];
  /// Per-state symmetric bounds. Values <= 0 disable clamping for that state.
  STATE_BOUNDS:[double];
  /// When true, emit flattened sample-major states in SAMPLES.
  EMIT_SAMPLES:bool;
  /// Optional trace/correlation identifier.
  TRACE_ID:string;
}

/// Result of one first-order Gauss-Markov random sequence.
table NUMGaussMarkovResult {
  STATUS:numResultStatus;
  ERROR_MESSAGE:string;
  /// Post-warmup per-state sample means.
  MEAN:[double];
  /// Post-warmup per-state sample standard deviations with n - 1 denominator.
  STANDARD_DEVIATION:[double];
  /// Post-warmup per-state minima.
  MINIMUM:[double];
  /// Post-warmup per-state maxima.
  MAXIMUM:[double];
  /// State after the final generated sample.
  FINAL_STATE:[double];
  /// Optional flattened sample-major state history.
  SAMPLES:[double];
  /// Caller trace/correlation identifier copied from the request when present.
  TRACE_ID:string;
}

/// Numerical utility envelope.
table NUM {
  ROOT_SOLVE_REQUEST:NUMRootSolveRequest;
  ROOT_SOLVE_RESULT:NUMRootSolveResult;
  VECTOR_SATURATE_REQUEST:NUMVectorSaturateRequest;
  VECTOR_SATURATE_RESULT:NUMVectorSaturateResult;
  VECTOR_DISCRETIZE_REQUEST:NUMVectorDiscretizeRequest;
  VECTOR_DISCRETIZE_RESULT:NUMVectorDiscretizeResult;
  SCALAR_INTERPOLATION_REQUEST:NUMScalarInterpolationRequest;
  SCALAR_INTERPOLATION_RESULT:NUMScalarInterpolationResult;
  GAUSS_MARKOV_REQUEST:NUMGaussMarkovRequest;
  GAUSS_MARKOV_RESULT:NUMGaussMarkovResult;
}

root_type NUM;
file_identifier "$NUM";

NST.IDL:
// Hash: 3a3f956fc69b8dc74c11d6db599bf870e08c362b1ed6c1086ab5e47fd4bb8889
// Version: 1.207.0
// -----------------------------------END_HEADER
/// Node Status Record (NST)
/// Description
/// Presence and identity of the peers a node knows about, as a node reports
/// them to operator dashboards: who the peer is (its identity record fields),
/// how it can be reached, whether it is online, where it is, which software
/// and standards versions it runs, and how the row reached the board. The
/// SOURCE field is the provenance of the row itself so an operator can always
/// answer "how did this peer get here?": declared in configuration, pinned by
/// an operator, or seen on a live connection. A set carries every row the
/// emitting node currently admits and the emitting node's own row.

/// One known peer as reported by the emitting node.
table NSTNode {
  /// Peer identifier (multihash, base58).
  PEER_ID: string;
  /// Distinguished name from the peer's identity record.
  DN: string;
  ORGANIZATION: string;
  TRUST_LEVEL: string;
  ROLE: string;
  AGENT_VERSION: string;
  /// Multiformat addresses the peer is known by.
  MULTIFORMAT_ADDRESS: [string];
  /// Unix seconds of last observation; 0 = never.
  LAST_SEEN: int64;
  IS_ONLINE: bool;
  /// Round-trip latency to the peer, milliseconds; 0 = unknown.
  LATENCY_MS: float;
  /// Full vCard 4.0 text derived from the peer's identity record.
  VCARD: string;
  /// Resolved coordinates; 0,0 = unresolved.
  LAT: float;
  LON: float;
  GEO_COUNTRY: string;
  GEO_CITY: string;
  /// True on the node emitting this set.
  IS_SELF: bool;
  /// Seconds since the emitting process started (self only).
  UPTIME_S: int64;
  SUITE_VERSION: string;
  STANDARDS_VERSION: string;
  /// How this row reached the board: exactly one of "config" (declared in the
  /// node's configuration), "pinned" (pinned by an operator) or "connected"
  /// (seen right now on a live connection).
  SOURCE: string;
  /// True for configuration and operator pins; a pinned peer keeps its row
  /// while unreachable.
  PINNED: bool;
  /// For SOURCE "config" the configuration key an operator can edit; for
  /// SOURCE "pinned" the operator's own note. Never a manufactured label.
  PIN_NOTE: string;
  /// Peers this peer is currently connected to, for the connection graph.
  CONNECTED_PEER_IDS: [string];
  /// Signing public key from the peer's identity record.
  SIGNING_PUBLIC_KEY: string;
  /// Encryption public key from the peer's identity record.
  ENCRYPTION_PUBLIC_KEY: string;
  /// Content identifier of the peer's identity record.
  EPM_CID: string;
  /// Version of the content-addressed storage daemon the peer runs.
  STORAGE_DAEMON_VERSION: string;
  /// Onion-service address when the peer is reachable over an anonymity
  /// network.
  ONION_ADDRESS: string;
}

/// Node Status Record - the set of peers a node reports.
table NST {
  NODES: [NSTNode];
  /// Unix milliseconds when this set was generated.
  GENERATED_AT: int64;
  /// Peer identifier of the emitting node.
  SOURCE_PEER_ID: string;
}

root_type NST;
file_identifier "$NST";

