OEM.IDL:
// Hash: 7a7c258d63755676bc73a25f858ec8636a9797f3bcd7c09dfafa16d359135289
// Version: 1.1.4
// -----------------------------------END_HEADER
include "../RFM/main.fbs";
include "../TIM/main.fbs";
include "../CAT/main.fbs";
include "../PPE/main.fbs";

// Orbit Ephemeris Message (OEM)
// Description
// Orbit information may be exchanged between two participants by sending an
// ephemeris in the form of a series of state vectors (Cartesian vectors providing position and
// velocity, and optionally accelerations) using an Orbit Ephemeris Message (OEM). The
// message recipient must have a means of interpolating across these state vectors to obtain the
// state at an arbitrary time contained within the span of the ephemeris.
// CCSDS Reference documentation: 502x0b2c1e2.

// =============================================================================
// EPHEMERIS DATA FORMAT OPTIONS
// =============================================================================
//
// The OEM supports TWO mutually exclusive formats for ephemeris data:
//
// ┌─────────────────────────────────────────────────────────────────────────────┐
// │ OPTION 1: COMPACT FORMAT (Row-Major Array) - RECOMMENDED FOR UNIFORM STEPS │
// ├─────────────────────────────────────────────────────────────────────────────┤
// │ Use when: Time steps are uniform (constant interval between epochs)        │
// │                                                                             │
// │ Required fields:                                                            │
// │   - START_TIME: Epoch of first state vector (ISO 8601)                     │
// │   - STEP_SIZE: Time interval between states in seconds (must be > 0)       │
// │   - EPHEMERIS_DATA: Flat array of doubles in row-major order               │
// │   - STATE_VECTOR_SIZE: Number of components per state (6 or 9)             │
// │                                                                             │
// │ Array layout (row-major):                                                   │
// │   [x0, y0, z0, xdot0, ydot0, zdot0,  ← State at START_TIME                 │
// │    x1, y1, z1, xdot1, ydot1, zdot1,  ← State at START_TIME + STEP_SIZE     │
// │    x2, y2, z2, xdot2, ydot2, zdot2,  ← State at START_TIME + 2*STEP_SIZE   │
// │    ...]                                                                     │
// │                                                                             │
// │ With acceleration (STATE_VECTOR_SIZE = 9):                                  │
// │   [x0, y0, z0, xdot0, ydot0, zdot0, xddot0, yddot0, zddot0,                │
// │    x1, y1, z1, xdot1, ydot1, zdot1, xddot1, yddot1, zddot1,                │
// │    ...]                                                                     │
// │                                                                             │
// │ Time reconstruction:                                                        │
// │   epoch[i] = START_TIME + (i * STEP_SIZE)                                  │
// │   where i = 0, 1, 2, ... (length(EPHEMERIS_DATA) / STATE_VECTOR_SIZE - 1)  │
// │                                                                             │
// │ Benefits: ~10x smaller payload, faster parsing, cache-friendly iteration   │
// └─────────────────────────────────────────────────────────────────────────────┘
//
// ┌─────────────────────────────────────────────────────────────────────────────┐
// │ OPTION 2: VERBOSE FORMAT (Structured Lines) - FOR NON-UNIFORM STEPS        │
// ├─────────────────────────────────────────────────────────────────────────────┤
// │ Use when: Time steps are irregular or you need self-describing data        │
// │                                                                             │
// │ Required fields:                                                            │
// │   - EPHEMERIS_DATA_LINES: Array of ephemerisDataLine tables                │
// │   - STEP_SIZE: Should be 0 or omitted to indicate non-uniform steps        │
// │                                                                             │
// │ Each ephemerisDataLine contains:                                            │
// │   - EPOCH: Explicit timestamp for this state (ISO 8601)                    │
// │   - X, Y, Z: Position components (km)                                      │
// │   - X_DOT, Y_DOT, Z_DOT: Velocity components (km/s)                        │
// │   - X_DDOT, Y_DDOT, Z_DDOT: Optional acceleration (km/s²)                  │
// │                                                                             │
// │ Benefits: Self-describing, supports irregular time spacing, easier debug   │
// └─────────────────────────────────────────────────────────────────────────────┘
//
// VALIDATION RULES:
// 1. If STEP_SIZE > 0, EPHEMERIS_DATA must be populated and EPHEMERIS_DATA_LINES
//    should be empty or ignored by parsers.
// 2. If STEP_SIZE == 0 or is omitted, EPHEMERIS_DATA_LINES must be populated
//    and EPHEMERIS_DATA should be empty or ignored by parsers.
// 3. Do NOT populate both formats simultaneously.
// 4. EPHEMERIS_DATA length must be divisible by STATE_VECTOR_SIZE.
// 5. STATE_VECTOR_SIZE must be 6 (pos+vel) or 9 (pos+vel+accel).
//
// =============================================================================

/// A single ephemeris data line (for non-uniform time steps only)
/// Use this format when time intervals between states are irregular.
/// For uniform time steps, use the compact EPHEMERIS_DATA array instead.
table ephemerisDataLine {
  /// Epoch time, in ISO 8601 UTC format (required for non-uniform steps)
  EPOCH:string;
  /// Position vector X-component km
  X:double;
  /// Position vector Y-component km
  Y:double;
  /// Position vector Z-component km
  Z:double;
  /// Velocity vector X-component km/s
  X_DOT:double;
  /// Velocity vector Y-component km/s
  Y_DOT:double;
  /// Velocity vector Z-component km/s
  Z_DOT:double;
  /// Optional: Acceleration vector X-component km/s²
  X_DDOT:double;
  /// Optional: Acceleration vector Y-component km/s²
  Y_DDOT:double;
  /// Optional: Acceleration vector Z-component km/s²
  Z_DDOT:double;

  // ───────────────────────────────────────────────────────────────────────────
  // APPENDED. Per-state clock and accuracy columns. Append-only: never reorder.
  //
  // These are the SP3-d position/velocity record columns that have no CCSDS OEM
  // equivalent. An OEM alone cannot be written back out as an SP3 file without
  // them: the clock column is mandatory in every SP3 position record, and the
  // per-coordinate standard-deviation exponents are how SP3 states accuracy.
  // All are optional; an OEM that omits them is unchanged.
  // ───────────────────────────────────────────────────────────────────────────

  /// Satellite clock bias (offset), microseconds. SP3 position-record clock
  /// column. The SP3 bad/absent sentinel 999999.999999 is NOT stored; omit the
  /// field instead.
  CLOCK_BIAS_MICROSECONDS:double;
  /// Satellite clock rate of change, 1e-4 microseconds per second. SP3
  /// velocity-record clock-rate column. Sentinel 999999.999999 is not stored.
  CLOCK_RATE_MICROSECONDS_PER_SECOND:double;
  /// Standard deviation of CLOCK_BIAS_MICROSECONDS, picoseconds.
  CLOCK_BIAS_SIGMA_PICOSECONDS:double;
  /// Standard deviation of CLOCK_RATE_MICROSECONDS_PER_SECOND,
  /// 1e-4 picoseconds per second.
  CLOCK_RATE_SIGMA_PICOSECONDS_PER_SECOND:double;

  /// Per-coordinate position standard-deviation EXPONENTS, SP3 base**n form:
  /// sigma = POS_VEL_BASE**n, with the position base from the SP3 header and
  /// the result in mm. These are the raw SP3 exponent columns, kept as
  /// exponents so an SP3 round-trip is exact; a consumer that wants a linear
  /// sigma raises the header base to this power.
  X_SIGMA_EXPONENT:int8;
  Y_SIGMA_EXPONENT:int8;
  Z_SIGMA_EXPONENT:int8;
  /// Per-coordinate velocity standard-deviation exponents, result in
  /// 1e-4 mm/s. Same base**n rule.
  X_DOT_SIGMA_EXPONENT:int8;
  Y_DOT_SIGMA_EXPONENT:int8;
  Z_DOT_SIGMA_EXPONENT:int8;
}

/// Position/Velocity Covariance Matrix Line
table covarianceMatrixLine {
  /// Epoch
  EPOCH:string;
  /// Covariance matrix [1,1] km**2
  CX_X:double;
  /// Covariance matrix [2,1] km**2
  CY_X:double;
  /// Covariance matrix [2,2] km**2
  CY_Y:double;
  /// Covariance matrix [3,1] km**2
  CZ_X:double;
  /// Covariance matrix [3,2] km**2
  CZ_Y:double;
  /// Covariance matrix [3,3] km**2
  CZ_Z:double;
  /// Covariance matrix [4,1] km**2/s
  CX_DOT_X:double;
  /// Covariance matrix [4,2] km**2/s
  CX_DOT_Y:double;
  /// Covariance matrix [4,3] km**2/s
  CX_DOT_Z:double;
  /// Covariance matrix [4,4] km**2/s**2
  CX_DOT_X_DOT:double;
  /// Covariance matrix [5,1] km**2/s
  CY_DOT_X:double;
  /// Covariance matrix [5,2] km**2/s
  CY_DOT_Y:double;
  /// Covariance matrix [5,3] km**2/s
  CY_DOT_Z:double;
  /// Covariance matrix [5,4] km**2/s**2
  CY_DOT_X_DOT:double;
  /// Covariance matrix [5,5] km**2/s**2
  CY_DOT_Y_DOT:double;
  /// Covariance matrix [6,1] km**2/s
  CZ_DOT_X:double;
  /// Covariance matrix [6,2] km**2/s
  CZ_DOT_Y:double;
  /// Covariance matrix [6,3] km**2/s
  CZ_DOT_Z:double;
  /// Covariance matrix [6,4] km**2/s**2
  CZ_DOT_X_DOT:double;
  /// Covariance matrix [6,5] km**2/s**2
  CZ_DOT_Y_DOT:double;
  /// Covariance matrix [6,6] km**2/s**2
  CZ_DOT_Z_DOT:double;
}

/// OEM Ephemeris Data Block
table ephemerisDataBlock {
  // ─────────────────────────────────────────────────────────────────────────────
  // METADATA SECTION (common to both formats)
  // ─────────────────────────────────────────────────────────────────────────────

  /// Plain-Text Comment
  COMMENT:string;
  /// Satellite name for the first object
  OBJECT: CAT;
  /// Origin of reference frame (EARTH, MARS, MOON, etc.)
  CENTER_NAME:string;
  /// Name of the reference frame (TEME, EME2000, etc.)
  REFERENCE_FRAME:RFM;
  /// Epoch of reference frame, if not intrinsic to the definition of the reference frame
  REFERENCE_FRAME_EPOCH:string;
  /// Reference frame for the covariance matrix
  COV_REFERENCE_FRAME:RFM;
  /// Time system used for the orbit state and covariance matrix. (UTC)
  TIME_SYSTEM:timingStandard;
  /// Start of TOTAL time span covered by ephemeris data and covariance data (ISO 8601)
  START_TIME:string;
  /// Optional start USEABLE time span covered by ephemeris data (ISO 8601)
  USEABLE_START_TIME:string;
  /// Optional end of USEABLE time span covered by ephemeris data (ISO 8601)
  USEABLE_STOP_TIME:string;
  /// End of TOTAL time span covered by ephemeris data and covariance data (ISO 8601)
  STOP_TIME:string;
  /// Recommended interpolation method for ephemeris data.
  /// Supported methods: Hermite, Linear, Lagrange, Chebyshev.
  /// When set to "Chebyshev", parsers should use POLYNOMIAL_POSITION_RECORDS
  /// for high-fidelity polynomial interpolation instead of interpolating across
  /// discrete state vectors.
  INTERPOLATION:string;
  /// Recommended interpolation degree for ephemeris data
  INTERPOLATION_DEGREE:uint;

  // ─────────────────────────────────────────────────────────────────────────────
  // COMPACT FORMAT (Row-Major Array) - Use when STEP_SIZE > 0
  // ─────────────────────────────────────────────────────────────────────────────
  // For uniform time steps, use this efficient representation.
  // Time for state i: epoch[i] = START_TIME + (i * STEP_SIZE)
  // Array layout: [x0,y0,z0,xdot0,ydot0,zdot0, x1,y1,z1,xdot1,ydot1,zdot1, ...]
  // ─────────────────────────────────────────────────────────────────────────────

  /// Time interval between ephemeris states in seconds.
  /// If > 0: Use compact EPHEMERIS_DATA array (times are implicit).
  /// If 0 or omitted: Use EPHEMERIS_DATA_LINES with explicit epochs.
  STEP_SIZE:double;

  /// Number of components per state vector in EPHEMERIS_DATA array.
  /// 6 = position + velocity (X, Y, Z, X_DOT, Y_DOT, Z_DOT)
  /// 9 = position + velocity + acceleration (adds X_DDOT, Y_DDOT, Z_DDOT)
  /// Only used when STEP_SIZE > 0. Default is 6.
  STATE_VECTOR_SIZE:uint8 = 6;

  /// Compact ephemeris data as row-major array of doubles.
  /// Only used when STEP_SIZE > 0.
  /// Layout: [x0,y0,z0,xdot0,ydot0,zdot0, x1,y1,z1,xdot1,ydot1,zdot1, ...]
  /// Units: position in km, velocity in km/s, acceleration in km/s²
  /// Length must be divisible by STATE_VECTOR_SIZE.
  /// Number of states = length(EPHEMERIS_DATA) / STATE_VECTOR_SIZE
  EPHEMERIS_DATA:[double];

  // ─────────────────────────────────────────────────────────────────────────────
  // VERBOSE FORMAT (Structured Lines) - Use when STEP_SIZE == 0 or omitted
  // ─────────────────────────────────────────────────────────────────────────────
  // For non-uniform time steps, use this self-describing format where each
  // state vector includes its own timestamp.
  // ─────────────────────────────────────────────────────────────────────────────

  /// Array of ephemeris data lines with explicit epochs.
  /// Only used when STEP_SIZE == 0 or omitted (non-uniform time steps).
  /// Each line contains its own EPOCH timestamp.
  EPHEMERIS_DATA_LINES:[ephemerisDataLine];

  // ─────────────────────────────────────────────────────────────────────────────
  // COVARIANCE DATA (optional, applies to both formats)
  // ─────────────────────────────────────────────────────────────────────────────

  /// Array of covariance matrix lines (optional)
  COVARIANCE_MATRIX_LINES:[covarianceMatrixLine];

  // ─────────────────────────────────────────────────────────────────────────────
  // POLYNOMIAL INTERPOLATION (optional, supplements both formats)
  // ─────────────────────────────────────────────────────────────────────────────
  // When INTERPOLATION is set to "Chebyshev", these records provide polynomial
  // coefficients for continuous, high-fidelity position evaluation between
  // discrete state vectors. Each record covers a time segment; together they
  // should span [START_TIME, STOP_TIME].
  //
  // This is an alternative to interpolating across discrete state vectors and
  // is especially useful for high-precision applications where the generating
  // ephemeris was produced by numerical integration (e.g., HPOP).
  // ─────────────────────────────────────────────────────────────────────────────

  /// Optional polynomial position records for high-fidelity interpolation.
  /// Used when INTERPOLATION is "Chebyshev". Each record covers a time segment with
  /// polynomial coefficients for continuous position (and optionally velocity) evaluation.
  /// See PPE schema for record structure and evaluation procedure.
  POLYNOMIAL_POSITION_RECORDS:[PPEPositionRecord];

  // ───────────────────────────────────────────────────────────────────────────
  // APPENDED. NAIF integer body codes. Append-only: never reorder.
  //
  // OBJECT and CENTER_NAME are text. An SPK segment descriptor is not: it
  // stores INTEGER NAIF codes for the target and the centre, and there is no
  // ratified text-to-code mapping to recover them from a name ($CAT carries no
  // NAIF id). Without these an OEM cannot be written to an SPK at all, and a
  // read SPK cannot state which bodies it referenced without guessing.
  // Precedent: BODY_NAIF_ID (schema/MDS/main.fbs),
  // CENTRAL_BODY_NAIF_ID (schema/SHC/main.fbs).
  // ───────────────────────────────────────────────────────────────────────────

  /// NAIF integer code of the ephemeris target (SPK segment target).
  OBJECT_NAIF_ID:int;
  /// NAIF integer code of the ephemeris centre, matching CENTER_NAME
  /// (SPK segment centre).
  CENTER_NAIF_ID:int;
}

/// Orbit Ephemeris Message
table OEM {
  /// OEM Header
  /// Classification marking of the data in IC/CAPCO Portion-marked format.
  CLASSIFICATION: string;
  /// OEM Version
  CCSDS_OEM_VERS:double;
  /// Creation Date
  CREATION_DATE:string;
  /// Originator
  ORIGINATOR:string;

  /// Array of ephemeris data blocks
  EPHEMERIS_DATA_BLOCK:[ephemerisDataBlock];
}

root_type OEM;
file_identifier "$OEM";

TAB.IDL:
// Hash: 126e277db5ca4feb3857f58b5295275abed97ebeb69989fab1e5ad64ee61fd7f
// Version: 0.0.4
// -----------------------------------END_HEADER
/// Typed Arena Buffer — descriptor for a schema-tagged payload frame moving
/// through an arena-backed plugin stream. Carries enough identity for a
/// receiver to dispatch on schema without inspecting the payload bytes.

/// Logical payload wire format for a stream frame or an accepted port type.
enum payloadWireFormat : ubyte {
  /// Body is a FlatBuffer with the root + file identifier stated in FLATBUFFER_TYPE_REF.
  FLATBUFFER,
  /// Body is a raw aligned binary chunk (for example zero-copy structs).
  ALIGNED_BINARY
}

/// Buffer mutability contract advertised by a stream port.
enum bufferMutability : ubyte {
  /// Buffer is immutable after produce.
  IMMUTABLE,
  /// Buffer may be written in place by the owner (single writer).
  SINGLE_WRITER_MUTABLE,
  /// Buffer is append-only (rings / logs).
  APPEND_ONLY
}

/// Buffer ownership contract advertised by a stream port.
enum bufferOwnership : ubyte {
  /// Arena / host owns the backing bytes; receiver must not free.
  HOST_OWNED,
  /// Plugin owns the backing bytes; host must not free.
  PLUGIN_OWNED,
  /// Ownership transfers with the frame (hand-off semantics).
  TRANSFERRED
}

/// Payload-schema identity for a stream frame or an accepted port type.
table FlatBufferTypeRef {
  /// Logical schema name (for example `OMM.fbs` or `OCM.fbs`).
  SCHEMA_NAME:string;
  /// Optional 4-byte FlatBuffer file identifier.
  FILE_IDENTIFIER:string;
  /// Optional semver or schema revision string.
  SCHEMA_VERSION:string;
  /// Optional root type name within the schema.
  ROOT_TYPE:string;
  /// Optional schema hash bytes for stronger compatibility checks.
  SCHEMA_HASH:[ubyte];
  /// True when this port/type set accepts any FlatBuffer frame.
  ACCEPTS_ANY_FLATBUFFER:bool = false;
  /// Logical wire format for this accepted type.
  WIRE_FORMAT:payloadWireFormat = FLATBUFFER;
  /// Fixed string length for aligned-binary string fields, when applicable.
  FIXED_STRING_LENGTH:uint16;
  /// Byte length for fixed-size aligned-binary records, when applicable.
  BYTE_LENGTH:uint;
  /// Required start alignment for aligned-binary records, when applicable.
  REQUIRED_ALIGNMENT:uint16;
}

/// Typed Arena Buffer — one descriptor for a payload slot in a shared arena.
table TAB {
  /// Byte offset of the payload body within the arena.
  OFFSET:uint;
  /// Byte length of the payload body.
  SIZE:uint;
  /// Required start alignment of the payload body (in bytes).
  ALIGNMENT:uint;
  /// Wire format for the body.
  WIRE_FORMAT:payloadWireFormat;
  /// Optional payload schema identity.
  TYPE_REF:FlatBufferTypeRef;
  /// Mutability contract for the slot.
  MUTABILITY:bufferMutability;
  /// Ownership contract for the slot.
  OWNERSHIP:bufferOwnership;
  /// Optional opaque frame identifier for stream bookkeeping.
  FRAME_ID:ulong;
  /// Optional port identifier for frames that route to/from a named
  /// input or output port on a method (maps to
  /// `PLG.PLGPortManifest.PORT_ID`). Empty for arena frames that carry
  /// no port routing hint.
  PORT_ID:string;
}

root_type TAB;
file_identifier "$TAB";

CES.IDL:
// Hash: faa9ecbe08da77927b04bfecad8a94cd6fa7a34dca4045c1d1a65c3af26d1663
// Version: 1.168.1
// -----------------------------------END_HEADER
/// Row element encoding used by a CES or QEM vector table.
enum cesVectorEncoding : byte {
  INT8,
  FLOAT32
}

/// Sentence/document pooling method an embedding encoder used.
/// Append new values only; never reorder or reuse existing values.
/// MIN and MAX are reserved: flatc synthesises a MIN/MAX sentinel pair for
/// every enum, so a member of either name makes the generated C++ and Swift
/// uncompilable. MAX_POOL carries the element-wise maximum pooling method and
/// keeps ordinal 2, which is the wire value.
enum cesPoolingKind : byte {
  MEAN,
  CLS,
  MAX_POOL,
  UNKNOWN
}

/// Row-vector normalization applied before quantization.
enum cesNormalizationKind : byte {
  NONE,
  L2
}

/// Similarity function rows are intended to be compared with.
enum cesSimilarityKind : byte {
  DOT_PRODUCT,
  COSINE,
  EUCLIDEAN
}

/// One catalog object's dense embedding row.
table CESObjectVector {
  /// Joins to CAT.NORAD_CAT_ID / OMM.NORAD_CAT_ID. 0 when unbound.
  NORAD_CAT_ID: uint32;
  /// International designator. Joins to CAT.OBJECT_ID.
  OBJECT_ID: string;
  /// Row values when the parent CES.ENCODING is INT8. Length equals
  /// CES.DIMENSIONS.
  VECTOR_INT8: [int8];
  /// Per-row dequantization scale: original value ~= VECTOR_INT8[i] * SCALE.
  /// Unused when ENCODING is FLOAT32.
  SCALE: float32;
  /// Row values when the parent CES.ENCODING is FLOAT32. Length equals
  /// CES.DIMENSIONS.
  VECTOR_FLOAT32: [float32];
}

/// Catalog Embedding Shard.
///
/// One CES publishes the dense semantic-search vector table for one dataset
/// update: one row per catalog object, alongside that update's $OMM shard and
/// $DPM manifest (DPMAsset.ASSET_KIND = EMBEDDING_SHARD). Vectors are
/// L2-normalised at the encoder's output; similarity between two rows, or
/// between a row and a query vector produced by a paired $QEM, is dot
/// product (equivalent to cosine similarity for unit-norm vectors).
///
/// A consumer MUST compare MODEL_ID, MODEL_VERSION, MODEL_WEIGHTS_SHA256,
/// POOLING_METHOD and TEMPLATE_VERSION against a QEM record before trusting
/// cross-encoding similarity between a query vector and CES rows; a mismatch
/// on any one field means the two vector spaces are not comparable.
table CES {
  /// Joins to DPM.DATASET_ID for the publication this shard belongs to.
  DATASET_ID: string;
  /// Joins to DPM.UPDATE_ID for the specific update this shard was computed
  /// against.
  UPDATE_ID: string;
  /// Fixed embedding dimensionality shared by every row (e.g. 384).
  DIMENSIONS: uint32;
  /// Row element encoding used across ROWS.
  ENCODING: cesVectorEncoding = INT8;
  /// Row-vector normalization applied before quantization.
  NORMALIZATION: cesNormalizationKind = L2;
  /// Similarity function rows are intended to be compared with.
  SIMILARITY: cesSimilarityKind = DOT_PRODUCT;
  /// Encoder model identifier/name.
  MODEL_ID: string;
  /// Encoder model version.
  MODEL_VERSION: string;
  /// SHA-256 of the encoder weights, lowercase hex. Same convention as
  /// DPMAsset.BYTE_SHA256.
  MODEL_WEIGHTS_SHA256: string;
  /// Sentence/document pooling method the encoder used.
  POOLING_METHOD: cesPoolingKind = MEAN;
  /// Version of the text template documents were rendered from before
  /// encoding. Must match a QEM's TEMPLATE_VERSION for compatible retrieval.
  TEMPLATE_VERSION: string;
  /// One row per catalog object.
  ROWS: [CESObjectVector];
}

root_type CES;
file_identifier "$CES";

BSP.IDL:
// Hash: 0b5e65ffed2fecd1834e569b92284da23314468c2d5493acbeb054c25a7c1efb
// Version: 0.0.2
// -----------------------------------END_HEADER
enum bspInterpolationStatus : byte {
  /// Interpolation completed.
  OK,
  /// The request is missing required waypoint, time, order, or sample data.
  INVALID_INPUT,
  /// The requested polynomial order is outside the supported B-spline range.
  UNSUPPORTED_ORDER,
  /// The interpolation linear system is singular or numerically unstable.
  SINGULAR_SYSTEM
}

/// Three coordinate arrays sharing one time vector.
table BSPVector3Series {
  /// Sample or waypoint time tags in seconds.
  T:[double];
  /// Coordinate 1 samples.
  X1:[double];
  /// Coordinate 2 samples.
  X2:[double];
  /// Coordinate 3 samples.
  X3:[double];
}

/// Request for one 3D B-spline interpolation.
table BSPInterpolationRequest {
  /// Waypoint times and coordinates. T, X1, X2, and X3 must have equal length.
  WAYPOINTS:BSPVector3Series;
  /// Number of equally spaced output samples.
  SAMPLE_COUNT:uint;
  /// Polynomial order of the B-spline basis.
  POLYNOMIAL_ORDER:ushort;
  /// Whether X_DOT_0 contains the first derivative at the first waypoint.
  HAS_X_DOT_0:bool;
  /// Optional first derivative at the first waypoint, length 3.
  X_DOT_0:[double];
  /// Whether X_DOT_N contains the first derivative at the last waypoint.
  HAS_X_DOT_N:bool;
  /// Optional first derivative at the last waypoint, length 3.
  X_DOT_N:[double];
  /// Whether X_D_DOT_0 contains the second derivative at the first waypoint.
  HAS_X_D_DOT_0:bool;
  /// Optional second derivative at the first waypoint, length 3.
  X_D_DOT_0:[double];
  /// Whether X_D_DOT_N contains the second derivative at the last waypoint.
  HAS_X_D_DOT_N:bool;
  /// Optional second derivative at the last waypoint, length 3.
  X_D_DOT_N:[double];
  /// Optional trace/correlation identifier.
  TRACE_ID:string;
}

/// Result of one 3D B-spline interpolation.
table BSPInterpolationResult {
  /// Interpolation status.
  STATUS:bspInterpolationStatus;
  /// Optional error detail when STATUS is not OK.
  ERROR_MESSAGE:string;
  /// Output sample positions.
  SAMPLES:BSPVector3Series;
  /// First derivative of coordinate 1 at each output sample.
  XD1:[double];
  /// First derivative of coordinate 2 at each output sample.
  XD2:[double];
  /// First derivative of coordinate 3 at each output sample.
