  // ---- Published envelope figures ----
  /// Maximum endurance, seconds, as the source publishes it.
  MAXIMUM_ENDURANCE_S:double;
  /// Maximum range, metres, as the source publishes it.
  MAXIMUM_RANGE_M:double;
