RFB.IDL:
// Hash: 59c60bc1b2ea74493068a0e374ba11f8a24ac505b7d955fdc8670c7fbcfab88e
// Version: 0.0.6
// -----------------------------------END_HEADER
include "../LKS/main.fbs";

/// Band designation carried by an emitter record.
///
/// Two naming systems coexist here on purpose. `UHF`, `SHF`, `EHF` and the
/// members below `OTHER` are ITU-R V.431 decade bands; `L` through `Q` are the
/// IEEE 521 letter bands. They OVERLAP by construction (an 8.4 GHz downlink is
/// both `X` and `SHF`). A publisher encodes the designation ITS SOURCE STATES —
/// never a re-derivation from CENTER_FREQ, and never both.
///
/// ORDINALS ARE WIRE VALUES. New members are APPENDED ONLY. Members added after
/// `OTHER` are therefore out of frequency order in the declaration; that is
/// deliberate and permanent. Reordering this enum silently re-labels every
/// $RFB record ever published.
enum rfBandDesignation : byte {
  UHF,
  L,
  S,
  C,
  X,
  KU,
  K,
  KA,
  V,
  W,
  Q,
  EHF,
  /// The source states a designation this enum cannot express. The verbatim
  /// designation MUST be preserved in NAME.
  OTHER,
  /// ITU-R V.431 very high frequency, 30–300 MHz. Appended 1.177.0.
  VHF,
  /// ITU-R V.431 high frequency, 3–30 MHz. Appended 1.177.0.
  HF,
  /// ITU-R V.431 medium frequency, 300 kHz–3 MHz. Appended 1.177.0.
  MF,
  /// ITU-R V.431 low frequency, 30–300 kHz. Appended 1.177.0.
  LF,
  /// ITU-R V.431 very low frequency, 3–30 kHz. Appended 1.177.0.
  VLF,
  /// ITU-R V.431 super high frequency, 3–30 GHz. Appended 1.177.0 to close the
  /// decade ladder between the pre-existing UHF and EHF members.
  SHF
}

enum rfPolarization : byte {
  LHCP,
  RHCP,
  LINEAR_H,
  LINEAR_V,
  DUAL,
  CROSS,
  UNKNOWN
}

/// Operational state of a single emitter.
enum rfTransmitterState : byte {
  UNKNOWN,
  ACTIVE,
  INACTIVE,
  INVALID
}

/// RF Band Specification
///
/// UNITS ARE NORMATIVE. Every frequency field in this table is MHz. Sources
/// that publish Hz (as open transmitter databases commonly do) MUST divide by
/// 1e6 before encoding; sources
/// that publish kHz MUST divide by 1e3. BAUD is baud (symbols per second),
/// never kilobaud. Encoding a Hz value into a MHz field is a defect, not a
/// convention.
///
/// One RFB record carries exactly one LINK_DIRECTION. A transceiver or
/// transponder is therefore represented as TWO RFB records — one UPLINK and
/// one DOWNLINK — sharing ID_TRANSMITTER, each carrying its own MODE,
/// FREQ_MIN, FREQ_MAX and CENTER_FREQ.
table RFB {
  /// Unique identifier
  ID:string;
  /// Parent entity identifier
  ID_ENTITY:string;
  /// Band name or designation
  NAME:string;
  /// RF band designation
  BAND:rfBandDesignation;
  /// Operating mode
  MODE:string;
  /// Band purpose (e.g., TT&C, PAYLOAD, BEACON)
  PURPOSE:string;
  /// Minimum frequency (MHz)
  FREQ_MIN:double;
  /// Maximum frequency (MHz)
  FREQ_MAX:double;
  /// Center frequency (MHz)
  CENTER_FREQ:double;
  /// Bandwidth (MHz)
  BANDWIDTH:double;
  /// Peak antenna gain (dBi)
  PEAK_GAIN:double;
  /// Edge-of-coverage gain (dBi)
  EDGE_GAIN:double;
  /// Antenna beamwidth (degrees)
  BEAMWIDTH:double;
  /// Polarization
  POLARIZATION:rfPolarization;
  /// Effective radiated power (dBW)
  ERP:double;
  /// Effective isotropic radiated power (dBW)
  EIRP:double;
  /// NORAD catalog number of the spacecraft carrying this emitter. Joins to
  /// CAT.NORAD_CAT_ID. 0 when unbound.
  NORAD_CAT_ID:uint;
  /// Identifier of the physical transmitter, transceiver or transponder this
  /// record describes (e.g. an upstream transmitter database's UUID). Uplink
  /// and downlink
  /// records of the same device share this value.
  ID_TRANSMITTER:string;
  /// Direction of this emission relative to the spacecraft.
  LINK_DIRECTION:linkCategory;
  /// Symbol rate in baud (symbols per second), NOT kilobaud.
  BAUD:double;
  /// Regulatory/ITU service designation (e.g. Amateur, Earth Exploration).
  SERVICE:string;
  /// Operational state of this emitter.
  XMT_STATUS:rfTransmitterState = UNKNOWN;
  /// True when the modulation sideband is inverted.
  INVERT:bool;
  /// IARU frequency-coordination state (e.g. IARU Coordinated, Uncoordinated).
  IARU_COORDINATION:string;
  /// Attribution/citation string the source license requires this record to
  /// carry downstream.
  CITATION:string;
}

root_type RFB;
file_identifier "$RFB";

