/// ORDINAL FREEZE -- APPEND ONLY, FOREVER.
/// A member's position IS its wire value: flatc writes it into the
/// Record.value_type byte of every $REC ever serialized, including the
/// publication trailer of every protected module artifact. Inserting,
/// reordering or removing a member silently re-points every record ever
/// written at the wrong standard. This has already happened three times;
/// inserting $PGM mid-union (c1580d4700, 2026-07-08) moved $PNM 113 -> 114
/// and broke protected-plugin decryption fleet-wide for three weeks.
/// New standards are APPENDED at the end. A retired standard is deprecated
/// in place, never deleted -- an ordinal is never reused.
/// Contract: schema/REC/RECORDTYPE_ORDINALS.json
/// Guard:    node scripts/checkRecordTypeOrdinals.mjs
/// Records written before 2026-07-08 are only decodable via Record.standard,
/// which is the sole discriminator that has never shifted.
union RecordType {
  ACL, ACM, ACR, ACW,
  AEM, ANI, AOF, APM,
  ARM, AST, ATD, ATM,
  BAL, BEM, BMC, BOV,
  BSP, BUS, CAQ, CAT,
  CDM, CFP, CHN, CLT,
  CMS, COM, COT, CRD,
  CRM, CSM, CTR, CZM,
  DFH, DMG, DOA, DPM,
  DSS, EME, ENC, ENV,
  EOO, EOP, EPM, ESL,
  ETM, EWR, FCS, FPC,
  FRM, GDI, GEO, GJN,
  GNO, GPX, GRV, GVH,
  HEL, HFC, HYP, IDM,
  ION, IRO, KMF, KML,
  KRF, LAM, LCC, LCF,
  LCH, LDM, LGR, LKS,
  LMO, LMR, LMS, LND,
  LNE, LPF, LWK, MBL,
  MET, MFE, MNF, MNV,
  MPE, MSL, MST, MTI,
  NAV, NUM, OBD, OBT,
  OCM, OEM, OMM, OOA,
  OOB, OOD, OOE, OOI,
  OOL, OON, OOS, OOT,
  OPM, OSM, PCF, PHY,
  PGM, PIV, PLD, PLG,
  PLK, PNM, PPE, PRG,
  PRR, PRW, PUR, RAF,
  RBK, RCF, RDM, RDO,
  REM, REV, RFB, RFE,
  RFM, RFO, ROC, SAR,
  SCM, SDF, SDL, SDR,
  SEN, SEO, SEV, SHW,
  SIT, SKI, SNR, SNW,
  SOI, SON, SPP, SPW,
  SRI, STF, STR, STV,
  SWR, TAB, TCF, TDM,
  TIM, TKG, TME, TMF,
  TNR, TPN, TRE, TRK,
  TRN, VCM, WPN, WTH,
  XTC, SCV, FSM, FSP,
  SCC, SCN, VST, ENT,
  VAM, APP, CMT, SCX,
  CVG, PKB, RPT, STO,
  SUB, WKS, CPS, FSB,
  FSO, GST, MDP, MDS,
  PNL, SHC, CES, QEM,
  SBM, PMM, OPP, IQC,
  CNP, CMR, TBS, CCT,
  ACI, CVP, RFL, RFS,
  TRS, GNP, DTT, AVL,
  TFN, TMS, VEP, EGP,
  APL, EMC, EPF, GEL,
