// Hash: 47db78e20924ce2c1683a34ef2f3725c758e0e914c752dfed460e5246f7ceab0
// Version: 0.0.2
// -----------------------------------END_HEADER
/// Sensor Runtime Wire — arena-addressed batch request / response envelopes
/// for sensor detection plugins. Complements the already-published `SDR`
/// (Sensor Detection Report, which carries per-frame configuration +
/// single-frame + detection-result payload shapes). SNW is the runtime
/// transport that moves a batch of target states into a sensor and pulls a
/// batch of detection results back out across a JS ↔ WASM boundary.
///
/// Persistent sensor hardware catalog → SDS `SNR`.
/// Sensor maintenance event log → SDS `SEN`.
/// Per-plugin wire contract + config + compact single-frame → SDS `SDR`.

enum snwErrorCode : int {
  OK,
  UNKNOWN,
  UNKNOWN_SENSOR,
  INVALID_EPOCH,
  OUTPUT_BUFFER_OVERFLOW,
  NOT_INITIALIZED
}

/// Batch target detection request.
///
/// Sensor position and orientation are passed inline (not via an arena
/// offset) because they are small and uniform across a batch. The target
/// stream lives at INPUT_OFFSET as a tightly packed array of `targetState`
/// structs from SDR; the output detection stream is written to
/// OUTPUT_OFFSET as a tightly packed array of SDR `detectionResult` structs.
table SNWBatchRequest {
  /// Sensor-configuration identifier assigned during sensor registration.
  SENSOR_ID:uint;
  /// Sensor position in ECEF (meters).
  SENSOR_POS_X:double;
  SENSOR_POS_Y:double;
  SENSOR_POS_Z:double;
  /// Sensor orientation as a unit quaternion (W, X, Y, Z).
  SENSOR_ORIENT_W:double;
  SENSOR_ORIENT_X:double;
  SENSOR_ORIENT_Y:double;
  SENSOR_ORIENT_Z:double;
  /// Byte offset in the arena where the targetState[] input stream begins.
  INPUT_OFFSET:uint;
  /// Required start alignment for INPUT_OFFSET (bytes).
  INPUT_ALIGNMENT:uint;
  /// Number of target records at INPUT_OFFSET.
  TARGET_COUNT:uint;
  /// Byte offset in the arena where the detectionResult[] output stream
  /// will be written.
  OUTPUT_OFFSET:uint;
  /// Required start alignment for OUTPUT_OFFSET (bytes).
  OUTPUT_ALIGNMENT:uint;
  /// Current time as a Julian date.
  EPOCH:double;
}

/// Batch target detection response header.
table SNWBatchResponse {
  /// Number of detection records written to OUTPUT_OFFSET.
  COUNT:uint;
  /// Number of targets whose SNR met the detection threshold.
  DETECTED_COUNT:uint;
  /// Byte offset where the detectionResult[] stream starts.
  OUTPUT_OFFSET:uint;
  /// Error code (0 == OK).
  ERROR_CODE:snwErrorCode;
  /// Optional error message when ERROR_CODE != OK.
  ERROR_MESSAGE:string;
}

/// Sensor Runtime Wire envelope — carries either a batch request or a batch
/// response across the runtime boundary.
table SNW {
  BATCH_REQUEST:SNWBatchRequest;
  BATCH_RESPONSE:SNWBatchResponse;
}

root_type SNW;
file_identifier "$SNW";

CVG.IDL:
// Hash: a91dc81b12c947ec453535e59e0ed161289fa1271b141c7181e6751faa344fa2
// Version: 1.161.0
// -----------------------------------END_HEADER
// Coverage Grid Figure-of-Merit (CVG)
// Description
// H3-indexed coverage-grid figures of merit over an epoch window: per-cell
// revisit, response, gap, and access statistics for a sensor/asset set.
// COMPACT FORMAT: cell metrics are parallel arrays aligned index-for-index
// with CELL_INDEXES (the same columnar philosophy as the OCM v2 state layout)
// so a global grid at high resolution stays cheap to store, query, and render.

/// Coverage Grid Figure-of-Merit
table CVG {
  /// Stable identifier of this coverage computation
  COVERAGE_ID: string (required);
  /// Display name
  NAME: string;
  /// Grid scheme identifier; "H3" for the H3 hexagonal hierarchical grid
  GRID_SCHEME: string;
  /// Grid resolution (H3 resolution 0-15)
  GRID_RESOLUTION: uint8;
  /// Grid cell indexes (H3 cell ids); all metric arrays align to this order
  CELL_INDEXES: [uint64];
  /// Epoch window start (UNIX timestamp) [numeric seconds since
  /// 1970-01-01T00:00:00 UTC]
  WINDOW_START: double;
  /// Epoch window stop (UNIX timestamp) [numeric seconds since
  /// 1970-01-01T00:00:00 UTC]
  WINDOW_STOP: double;
  /// Sampling step in seconds used to compute access intervals
  STEP_SIZE: double;
  /// Sensor identifiers contributing to the coverage set
  SENSOR_IDS: [string];
  /// Asset (satellite) identifiers contributing to the coverage set
  ASSET_IDS: [string];
  /// Per-cell number of access intervals in the window
  ACCESS_COUNTS: [uint32];
  /// Per-cell total access duration in seconds
  ACCESS_TOTAL_S: [double];
  /// Per-cell mean revisit interval in seconds
  REVISIT_MEAN_S: [double];
  /// Per-cell maximum revisit interval in seconds
  REVISIT_MAX_S: [double];
  /// Per-cell mean response time in seconds
  RESPONSE_MEAN_S: [double];
  /// Per-cell maximum response time in seconds
  RESPONSE_MAX_S: [double];
  /// Per-cell maximum coverage gap in seconds
  GAP_MAX_S: [double];
  /// Per-cell fraction of the window with at least one access [0-1]
  COVERAGE_FRACTION: [double];
  /// Unix ms this coverage set was computed
  COMPUTED_AT: uint64;
  /// Ed25519 signature by the producing `$EPM`
  SIGNATURE: [ubyte];
}

root_type CVG;
file_identifier "$CVG";

