MPE.IDL:
// Hash: a0c9f881d7cea39fabf256989601c2c691e0780676c9fa7ef242e2119091ee5d
// Version: 1.0.5
// -----------------------------------END_HEADER
include "../MET/main.fbs";

// Minimum-Propagatable-Element-Set (MPE)
// Description
// Truncated version of the Orbit Mean-Elements Message (OMM). Includes only the Mean Elements required to propagate an orbit.
// Legacy format description can be found here.
// CCSDS Reference documentation: 502x0b2c1e2.

/// One constraint in a maneuver-targeting problem and how well the converged
/// solution satisfies it.
table MPETargeterConstraint {
  /// Constraint identifier, e.g. "SMA", "INC", "RIC_R"
  NAME: string;
  /// Reference frame the constraint is expressed in
  FRAME: string;
  /// Epoch the constraint applies at (UNIX timestamp) [numeric seconds since
  /// 1970-01-01T00:00:00 UTC]; 0 when the constraint anchors to EVENT
  EPOCH: double;
  /// Event the constraint anchors to when EPOCH is 0, e.g. "APOAPSIS"
  EVENT: string;
  /// Target value of the constrained quantity
  TARGET_VALUE: double;
  /// Value achieved by the converged solution
  ACHIEVED_VALUE: double;
  /// Acceptable tolerance on the constrained quantity
  TOLERANCE: double;
  /// Relative weight of this constraint in the corrector
  WEIGHT: double;
}

/// Maneuver-targeter solution and convergence metadata carried with an
/// extended MPE: the solver that produced the targeted element set, its
/// iteration/residual history, and the constraint set it satisfied.
table MPETargeterSolution {
  /// Solver used, e.g. "differential-corrector"
  SOLVER: string;
  /// Dynamics contract the solution was targeted under: SGP4, HPOP, CR3BP
  DYNAMICS: string;
  /// Whether the corrector converged within tolerance
  CONVERGED: bool;
  /// Number of corrector iterations executed
  ITERATIONS: uint32;
  /// RMS of the final-iteration constraint residuals
  RESIDUAL_RMS: double;
  /// Final-iteration residual per constraint, aligned with CONSTRAINTS
  RESIDUALS: [double];
  /// The constraint set the solution was targeted against
  CONSTRAINTS: [MPETargeterConstraint];
  /// Total delta-v of the solved maneuver sequence in m/s
  TOTAL_DELTA_V: double;
  /// Unix ms the solution was produced
  SOLVED_AT: uint64;
}

/// Minimum Propagatable Element Set
table MPE {
  /// Unique ID as a String [no units]
  ENTITY_ID: string;
  /// Epoch of Mean Keplerian elements (UNIX timestamp) [numeric seconds since 1970-01-01T00:00:00 UTC]
  EPOCH: double;
  /// Mean motion in rev/day [M if chosen to represent orbit size for SGP/SGP4 elements]
  MEAN_MOTION: double;
  /// Eccentricity (unitless)
  ECCENTRICITY: double;
  /// Inclination in degrees
  INCLINATION: double;
  /// Right ascension of ascending node in degrees
  RA_OF_ASC_NODE: double;
  /// Argument of pericenter in degrees
  ARG_OF_PERICENTER: double;
  /// Mean anomaly in degrees
  MEAN_ANOMALY: double;
  /// SGP/SGP4 drag-like coefficient (BSTAR) in units of 1/[Earth radii]
  BSTAR: double;
  /// Description of the Mean Element Theory (SGP4, DSST, USM)
  MEAN_ELEMENT_THEORY:meanElementSource = SGP4;
  /// Targeter solution + convergence metadata when this element set is the
  /// product of maneuver targeting (absent for ordinary element sets)
  TARGETER: MPETargeterSolution;
}

root_type MPE;
file_identifier "$MPE";

EPF.IDL:
// Hash: be0efd0be341467a49369ee9d98350a4390d4e172fad96d5c184902ad5a5ae66
// Version: 1.193.1
// -----------------------------------END_HEADER
include "../RFL/main.fbs";

// Aggregate Interference and Flux-Density Compliance (EPF)
// One signed compliance evaluation with sample, contributor, distribution,
// and verdict rows suitable for direct FlatSQL and `$RPT` queries.

/// Quantity constrained by the compliance limit.
enum epfLimitCategory : byte {
  UNSPECIFIED = 0,
  PFD,
  EPFD_DOWN,
  EPFD_UP,
  EPFD_INTERSATELLITE,
  AGGREGATE_I_N,
  DELTA_T_OVER_T
}

/// One source's contribution to one sample.
table EPFContributor {
  CONTRIBUTOR_ID: string (required);
  SAMPLE_INDEX: uint32;
  SOURCE_ENDPOINT_ID: string;
  RFE_ID: string;
  RFB_ID: string;
  PAP_ID: string;
  NORAD_CAT_ID: uint;
  INTERFERENCE_POWER_DBW: double;
  /// Pattern discrimination applied in the victim direction, dB.
  ANTENNA_DISCRIMINATION_DB: double;
  /// Fraction of the victim measurement bandwidth overlapped [0-1].
  SPECTRAL_OVERLAP_FRACTION: double;
  CONTRIBUTION_VALUE: double;
  CONTRIBUTION_UNITS: string;
}

/// FlatSQL-queryable compliance verdict consumed directly by `$RPT`.
table EPFVerdict {
  LIMIT_KIND: epfLimitCategory = UNSPECIFIED;
  COMPLIANT: bool;
  /// Worst margin to the applicable limit, dB. Positive means compliant.
  MARGIN_DB: double;
  PERCENT_TIME_EXCEEDED: double;
  WORST_SAMPLE_INDEX: uint32;
  NOTE: string;
}

/// Aggregate Interference and Flux-Density Compliance
table EPF {
  EPF_ID: string (required);
  NAME: string;
  SCENARIO_ID: string;
  RFL_ID: string;
  ACI_ID: string;
  VICTIM_ENDPOINT_ID: string;
  LIMIT_KIND: epfLimitCategory = UNSPECIFIED;
  LIMIT_MODEL_NAME: string;
  VALUE_UNITS: string (required);

  SAMPLE_COUNT: uint32;
  SAMPLE_EPOCHS: [double] (required);
  SAMPLE_VALUES: [double] (required);
  SAMPLE_LIMIT_VALUES: [double] (required);
  /// Positive means the sample complies with its limit.
  SAMPLE_MARGIN_DB: [double] (required);
  SAMPLE_EXCEEDS_LIMIT: [bool] (required);
  CONTRIBUTORS: [EPFContributor];

  /// Empirical distribution values and their percent-time exceedance. Arrays
  /// are index-aligned and ordered as stated by provenance.
  CDF_VALUES: [double] (required);
  CDF_PERCENT_TIME_EXCEEDED: [double] (required);
  VERDICT: EPFVerdict (required);

  PROVENANCE: RFLProvenance (required);
  COMPUTED_AT: uint64;
  PRODUCER_ID: string (required);
  /// Ed25519 signature over the size-prefixed FlatBuffer with both 64-byte
  /// signature payloads zeroed while preserving their vectors and offsets.
  SIGNATURE: [ubyte] (required);
  /// Ed25519 signature over canonical JSON with IDL field order and
  /// capitalization, no insignificant whitespace, and both signature fields
  /// omitted.
  CANONICAL_JSON_SIGNATURE: [ubyte] (required);
}

root_type EPF;
file_identifier "$EPF";

