// Hash: d0cded4df6be8c22ae401067b43fb86d425b9768ba754a51769bdf9e945eb03b
// Version: 1.136.2
// -----------------------------------END_HEADER
include "../SCN/main.fbs";

/// Scenario controls message discriminator.
enum controlMessageKind : byte {
  UNKNOWN,
  READY,
  SCENARIO_SETUP,
  REQUEST_STATE,
  STATE_RESPONSE,
  OPEN_ASSET_PICKER,
  OPEN_ASSET_PICKER_ACK,
  ASSETS_CHANGED
}

/// State request kind for a control-message request/response pair.
enum stateRequestKind : byte {
  UNKNOWN,
  SCENARIO,
  REFERENCES
}

/// Asset catalog tab requested by a host or embedded scenario controls surface.
enum assetCatalogTab : byte {
  UNKNOWN,
  SATELLITES,
  SENSORS
}

/// Request current state from a scenario controls host.
table SCCRequestState {
  /// Request correlation id echoed by the matching state response.
  REQUEST_ID:string;
  /// State payload requested by the caller.
  REQUEST_KIND:stateRequestKind;
}

/// State response. SCENARIO carries full scenario state; REFERENCES can carry
/// the lighter reference-list response for reference-only requests.
table SCCStateResponse {
  /// Request correlation id from the matching state request.
  REQUEST_ID:string;
  /// State payload represented by this response.
  REQUEST_KIND:stateRequestKind;
  /// Full scenario state for scenario-state responses.
  SCENARIO:SCN;
  /// Reference-list payload for reference-only responses.
  REFERENCES:[SCNReference];
  /// Zero-based focused reference index, or -1 when no index is focused.
  FOCUSED_REFERENCE_INDEX:int = -1;
  /// Human-readable error message when state cannot be returned.
  ERROR_MESSAGE:string;
}

/// Asset-picker request or acknowledgement.
table SCCAssetPicker {
  /// Request correlation id for the asset-picker exchange.
  REQUEST_ID:string;
  /// Initial catalog tab to display in the asset picker.
  CATALOG_TAB:assetCatalogTab;
  /// True when the receiver accepted or completed the picker request.
  ACKNOWLEDGED:bool;
}

/// Startup readiness message.
table SCCReady {
  /// True when the scenario controls surface is ready for messages.
  READY:bool = true;
}

/// Scenario Controls - message-bus envelope for scenario setup, state
/// requests/responses, startup readiness, and asset-picker delegation.
table SCC {
  /// Payload discriminator for the message carried by this envelope.
  MESSAGE_KIND:controlMessageKind;
  /// Optional trace id for correlating messages across systems.
  TRACE_ID:string;
  /// Scenario list carried by setup or selection messages.
  SCENARIOS:[SCN];
  /// Single scenario payload carried by setup or state messages.
  SCENARIO:SCN;
  /// Request-current-state payload.
  REQUEST_STATE:SCCRequestState;
  /// Current-state response payload.
  STATE_RESPONSE:SCCStateResponse;
  /// Asset-picker request or acknowledgement payload.
  ASSET_PICKER:SCCAssetPicker;
  /// Startup readiness payload.
  READY:SCCReady;
}

root_type SCC;
file_identifier "$SCC";

NDS.IDL:
// Hash: 1feffd3a68b818302178dc04c9452182a07f6189fe8b41586f086327083b01bb
// Version: 1.207.0
// -----------------------------------END_HEADER
/// Node Data Statistics (NDS)
/// Description
/// Snapshot of one node's data plane for operator dashboards: the record
/// footprint of every standard held, the ingest progress of every
/// (standard, provider, source, batch) lane together with the producer and the
/// upstream origin of that lane, ingest transitions, topic activity, module
/// runtime counters and trust-engine counters. A node assembles the snapshot
/// on a background lane and serves it from memory so a dashboard read never
/// waits on the store. A STALE snapshot is reported as stale with the AS_OF
/// time of its last true numbers, never as a confident zero.
///
/// Provenance of a lane is structural, never a display string: PRODUCER_PEER_ID
/// is the peer whose signed identity record covers the lane's publications,
/// ORIGIN_ID names the upstream publisher the producer retrieved the records
/// from, and PUBLISHER_RUNG states how far that producer claim has been
/// verified by the reporting node.

/// How far the reporting node has verified the producer of a lane. Append new
/// values only; never reorder or reuse existing values.
enum ndsPublisherRung : byte {
  /// Only a source tag string is known; nothing has been verified.
  SourceTag,
  /// The producer's signed identity record verifies in this node's directory.
  Signed,
  /// The producer additionally carries a verified domain proof.
  Bonded
}

/// Kind of ingest transition surfaced to the dashboard. Append new values
/// only; never reorder or reuse existing values.
enum ndsIngestEventKind : byte {
  Stall,
  Reject,
  Recover
}

/// One standard's record footprint in the node store.
table NDSSchemaStat {
  /// Standard code, e.g. "OMM".
  SCHEMA: string;
  RECORD_COUNT: int64;
  TOTAL_BYTES: int64;
  /// Newest record epoch held, Unix milliseconds; 0 = unknown.
  NEWEST_EPOCH_MS: int64;
  /// Oldest record epoch held, Unix milliseconds; 0 = unknown.
  OLDEST_EPOCH_MS: int64;
}

/// One (standard, provider, source, batch) ingest lane's live progress and
/// provenance.
table NDSSourceStat {
  SCHEMA: string;
  PROVIDER_ID: string;
  SOURCE_NAME: string;
  BATCH_ID: string;
  RECORD_COUNT: int64;
  TOTAL_BYTES: int64;
  /// Unix seconds; 0 = unknown.
  FIRST_INGEST_AT: int64;
  /// Unix seconds; 0 = unknown.
  LAST_INGEST_AT: int64;
  /// Unix seconds; 0 = unknown.
  UPDATED_AT: int64;
  /// Records observed in the current rolling window.
