SCX.IDL:
// Hash: 3d9389c3fdb6aca485fd4046cdca8b13f95b589fd5efa69f8f8081372e434a8d
// Version: 1.155.0
// -----------------------------------END_HEADER
/// Recipient of an on-chain revenue split. The identity binds to an `$EPM`
/// via CHAIN_PROOFS so a payout address is provably the recipient's.
table SplitRecipient {
  /// IPFS CID of the recipient's Entity Profile Message (`$EPM`)
  EPM_CID: string;
  /// Settlement chain, e.g. "ethereum", "solana", "bitcoin"
  CHAIN: string;
  /// On-chain payout address (EVM 0x / SOL base58 / BTC address)
  ADDRESS: string;
  /// Account xpub the address derives from
  XPUB: string;
}

/// On-chain settlement mechanism a buyer's payment targets.
enum settlementMechanism : byte {
  /// Native-asset transfer to a plain address (no split contract)
  NativeTransfer,
  /// ERC-20 / SPL token transfer to a plain address
  Erc20Transfer,
  /// 0xSplits-style splitter contract on an EVM chain
  EthSplitter,
  /// Splitter program on Solana
  SolSplitter,
  /// Direct address payout (e.g. Bitcoin); split settled off-contract
  DirectAddress
}

/// How the purchase reference (`$PUR.REQUEST_ID`) is bound on-chain so a
/// payment can be matched to an order replay-safely.
enum memoBindingScheme : byte {
  /// No on-chain memo binding
  NoMemo,
  /// Bound in EVM transaction calldata
  TxData,
  /// Solana memo program instruction
  SolMemo,
  /// Bitcoin OP_RETURN output
  OpReturn
}

/// Chain Settlement / Smart-Contract Descriptor. The forward description of the
/// exact established splitter contract/program a buyer's wallet targets so
/// payment and platform commission settle atomically on-chain. Referenced by
/// `$CMT.CONTRACTS` and echoed into a store `checkout` quote. Commission is
/// realized by the splitter contract itself when the buyer pays it; there is no
/// off-chain or manual settlement step.
table SCX {
  /// Settlement chain identifier, e.g. "ethereum", "solana", "bitcoin"
  /// (matches `$PUR.PAYMENT_CHAIN`)
  CHAIN: string (required);
  /// EVM chainId; 0 for non-EVM chains
  CHAIN_ID: uint64;
  /// On-chain settlement mechanism
  SETTLEMENT_KIND: settlementMechanism;
  /// Established split standard id, e.g. "0xsplits.v2" (ETH) or the SOL
  /// splitter program name. An audited off-the-shelf standard, not a custom
  /// contract.
  SPLITTER_STANDARD: string;
  /// Deployed splitter contract address (ETH) or splitter program id (SOL) the
  /// buyer's payment routes into
  SPLITTER_ADDRESS: string;
  /// The specific split configuration (recipient set + basis points) registered
  /// with the splitter
  SPLIT_CONFIG_ID: string;
  /// ERC-20 / SPL mint address for stablecoin settlement; empty = native asset
  TOKEN_ADDRESS: string;
  /// Token symbol, e.g. "USDC"
  TOKEN_SYMBOL: string;
  /// Token decimals, e.g. 6 for USDC
  TOKEN_DECIMALS: uint8;
  /// The recipient set the split configuration encodes (platform + publisher…),
  /// mirrored here for independent verification
  SPLIT_RECIPIENTS: [SplitRecipient];
  /// Confirmations required before the payment is accepted
  MIN_CONFIRMATIONS: uint32;
  /// How the order reference is bound on-chain for replay-safe matching
  MEMO_SCHEME: memoBindingScheme;
}

root_type SCX;
file_identifier "$SCX";

CCT.IDL:
// Hash: e55421c6fef3ac32b2713b697e65bd0f517a2f9d3309f319817b5eaa318bad91
// Version: 1.184.1
// -----------------------------------END_HEADER
/// Capability class of a distributable software unit (module, application, or
/// composed flow).
///
/// This enum IS the ratified category vocabulary. A storefront, library, module
/// manifest and search surface all classify against these members and nothing
/// else; a category that is not a member here does not exist. Members name
/// CAPABILITY CLASSES only — what the unit DOES. No member names a vendor,
/// site, organization, product, protocol brand or algorithm implementation;
/// that identity belongs in data fields such as PLG.PUBLISHER_NAME, never in
/// the taxonomy.
///
/// Ordinals are wire values: APPEND ONLY. Never reorder, never remove, never
/// reuse an ordinal. A reorder silently re-labels every published listing.
///
/// UNSPECIFIED deliberately holds ordinal 0 so that a zero-filled or
/// default-constructed classification can never decode as a real category. The
/// pre-existing `pluginCategory` enum in $PLG made the opposite choice — its
/// ordinal 0 is a real family — and had to append an `Unspecified` member at
/// the tail to recover. This enum does not repeat that.
///
/// Each member's canonical display name is stated in its doc comment and is
/// part of the ratified contract: a consumer rendering a category label uses
/// that string verbatim, so every surface spells a category identically. The
/// canonical route slug is the member identifier lowercased with `_` replaced
/// by `-` (PROPAGATION -> "propagation", RF_AND_COMMUNICATIONS ->
/// "rf-and-communications").
enum capabilityClass : ubyte {
  /// No capability class stated. The publisher did not classify the unit.
  /// A consumer MUST render an UNSPECIFIED unit as ungrouped and MUST NOT
  /// infer a class from the unit's name, description or tags.
  /// Display name: "Unspecified".
  UNSPECIFIED,

  /// Advancing an object's state forward or backward in time under a force
  /// model, and interpolating between computed states.
  /// Display name: "Propagation".
  PROPAGATION,

  /// Estimating an object's state or model parameters by fitting to
  /// observations or ephemerides.
  /// Display name: "Orbit Determination".
  ORBIT_DETERMINATION,

  /// Planning, targeting and optimizing trajectory changes, including
  /// station-keeping, transfers and collision-avoidance maneuvers.
  /// Display name: "Maneuver Planning".
  MANEUVER_PLANNING,

  /// Screening for close approaches between objects and quantifying collision
  /// probability and miss distance.
  /// Display name: "Conjunction Assessment".
  CONJUNCTION_ASSESSMENT,

