TBS.IDL:
// Hash: d4e42a32f0daaf17b7e83b48f732eff68d1a5479d09a65ea9a80f0ec1f475bb1
// Version: 1.183.0
// -----------------------------------END_HEADER
/// Radio access technology class of a terrestrial base-station site.
///
/// Members name generation-level access technologies only. A publisher encodes
/// the class ITS SOURCE STATES and never re-derives one from frequency,
/// identifier width, or operator. Ordinals are wire values: append only; never
/// reorder or reuse.
enum tbsRadioClass : byte {
  /// Second-generation circuit-switched cellular access.
  GSM,
  /// Code-division multiple-access cellular access.
  CDMA,
  /// Third-generation wideband code-division cellular access.
  UMTS,
  /// Fourth-generation long-term-evolution cellular access.
  LTE,
  /// Fifth-generation new-radio cellular access.
  NR,
  /// An access technology the source names but this enum does not model. The
  /// source's own term is retained in the provenance entry, never discarded.
  OTHER,
  /// The source publishes no access technology. RADIO defaults here so an
  /// unset field can never be read as GSM, which holds ordinal 0.
  UNKNOWN
}

/// How independent provider reports for one site were reduced to the one
/// published position. Ordinals are wire values: append only; never reorder or
/// reuse.
enum tbsMergeMethod : byte {
  /// Exactly one provider reported the site; nothing was reconciled.
  SINGLE_SOURCE,
  /// The report backed by the largest independent observation count won.
  HIGHEST_SAMPLE_COUNT,
  /// The report with the most recent observation window won.
  MOST_RECENT,
  /// A declared precedence ranking over publishing authorities selected the
  /// winning report, regardless of sample count or recency.
  AUTHORITY_PRECEDENCE,
  /// The published position is computed from the agreeing reports and belongs
  /// to no single provider.
  CENTROID,
  /// The publisher does not state how the reports were reduced. METHOD
  /// defaults here so an unset field can never be read as SINGLE_SOURCE,
  /// which holds ordinal 0.
  UNSPECIFIED
}

/// Replayable provenance for ONE provider's report of ONE site.
///
/// Every provider consulted gets its own entry, including providers that
/// returned nothing, so a consumer can tell "not looked for" from "looked for
/// and returned nothing". Provider identity is DATA: PROVIDER_ID and AUTHORITY
/// carry verbatim what that provider states about itself. The standard names
/// no provider, dataset, or site.
table TBSProvenance {
  /// Publisher-stable, lowercase identifier for the consulted provider,
  /// unique within the publisher's own provider registry. Never a display
  /// name and never a URL.
  PROVIDER_ID:string (required);
  /// The authority under which that provider publishes, verbatim as the
  /// provider states it: a spectrum regulator, a network operator, a
  /// crowd-sourced observation programme, or a research dataset. Never
  /// inferred by the publisher.
  AUTHORITY:string;
  /// Replayable URL identifying the source material.
  SOURCE_URL:string;
  /// The exact query, filter, or request parameters used, so the same rows can
  /// be recovered by repeating the fetch.
  SOURCE_QUERY:string;
  /// RFC 3339 UTC fixed-millisecond retrieval timestamp.
  RETRIEVED_AT:string (required);
  /// Redistribution terms verbatim. Required: there is no encoding for a
  /// redistributed site whose terms are unstated. A provider that publishes no
  /// terms is recorded as publishing no terms; unknown terms are never public
  /// domain and never an implied grant.
  LICENSE:string (required);
  /// URL of the full licence text as that provider publishes it.
  LICENSE_URL:string;
  /// Attribution text the licence requires a redistributor to display.
  ATTRIBUTION:string;
  /// The licence forbids commercial use. Rides PER SOURCE because one record
  /// may merge an open-terms lane beside a non-commercial cross-check, and the
  /// strictest consulted lane governs any derived product.
  NON_COMMERCIAL_ONLY:bool = false;
  /// This provider's own row, cell, or site identifier, verbatim.
  NATIVE_ID:string;
  /// Position this provider reported, in decimal degrees on WGS 84, before
  /// reconciliation. Retained unrounded so the merge stays auditable. Absent
  /// when the provider was consulted and reported no position.
  REPORTED_LATITUDE:double;
  REPORTED_LONGITUDE:double;
  /// This provider's report materially contributed to the published CONSENSUS
  /// position. False marks a provider that was consulted and either returned
  /// nothing or was outvoted; its entry is published either way.
  CONTRIBUTED:bool = false;
}

/// How one site's independent provider reports were reduced to the single
/// published position, and how strongly those reports agreed.
table TBSConsensus {
  METHOD:tbsMergeMethod = UNSPECIFIED;
  /// Providers queried for this site, including those that returned nothing.
  /// Never fewer than the number of SOURCES entries.
  PROVIDERS_CONSULTED:uint;
  /// Providers whose reported position fell within the publisher's agreement
  /// threshold. A value of 1 means the published position rests on a single
  /// report and was never independently corroborated.
  PROVIDERS_AGREEING:uint;
  /// PROVIDER_ID of the report the merge selected, copied verbatim from the
  /// matching SOURCES entry. Absent when METHOD is CENTROID: a computed
  /// position belongs to no single provider.
  WINNING_PROVIDER_ID:string;
  /// Greatest surface distance in metres between any two agreeing reported
  /// positions. Zero is meaningful only when PROVIDERS_AGREEING is 1.
  POSITION_SPREAD_M:double;
  /// The publisher's own confidence in the merged position, on [0,1]. Never a
  /// provider's figure and never a probability from a model this standard does
  /// not name.
  CONFIDENCE:double;
  /// RFC 3339 UTC fixed-millisecond instant at which the merge was performed.
  MERGED_AT:string;
}

/// Terrestrial Base Station Site.
///
/// One record describes ONE terrestrial cellular base-station site as
/// reconciled from every provider the publisher consulted. It is the wire
/// record for terrestrial mobile-network infrastructure, and it is not an
/// emitter model ($RFE), a band specification ($RFB), a geodetic tracking
/// station ($GST), a satellite ground station ($SIT), or an observation.
///
/// A site cannot be re-serialized unattributed. SOURCES and CONSENSUS are both
/// required, so every published position carries the providers it came from and
/// the rule that reconciled them; a consumer that strips attribution has to
/// leave the standard to do it. Unknown values are ABSENT — never zero, never a
/// placeholder, never carried across from a neighbouring site.
///
/// Identity is ID, the publisher's own. The network addressing fields are the
/// mobile network's, are assigned by its operator, and are reused worldwide;
/// none of them is a global key on its own.
table TBS {
  /// Publisher-stable identifier for this site, unique within its record set.
  /// Recommended form: "<mcc>-<mnc>-<area-code>-<cell-id>".
  ID:string (required);
  /// Winning provider's native site identifier, copied verbatim from the
  /// SOURCES entry named by CONSENSUS.WINNING_PROVIDER_ID. Never a substitute
  /// for ID and never stable across providers.
  NATIVE_ID:string;
  RADIO:tbsRadioClass = UNKNOWN;
  /// Mobile country code from the international mobile-subscriber identity
  /// numbering plan. Zero means the source published none.
  MCC:uint;
  /// Mobile network code within MCC. Carried as an integer, so decimal leading
  /// zeros are NOT preserved: a two- versus three-digit network code is
  /// distinguished by the numbering plan of MCC, and the source's own text is
  /// retained verbatim in TBSProvenance.NATIVE_ID. Zero means unpublished.
  MNC:uint;
  /// Location area code, used by GSM-, CDMA- and UMTS-class access. Zero means
  /// unpublished. A site published with a location area code does not also
  /// carry a tracking area code; publishing both asserts two access
  /// generations for one cell.
  LAC:uint;
  /// Tracking area code, used by LTE- and NR-class access. Zero means
  /// unpublished.
  TAC:uint;
  /// Cell identity verbatim from the source. A string because width, radix and
  /// leading zeros are significant and differ by access class: a 16-bit cell
  /// identity, a 28-bit evolved cell identity and a 36-bit new-radio cell
  /// identity are not interchangeable integers, and this field never converts
  /// between them.
  CELL_ID:string;
  /// Reconciled site position in decimal degrees on WGS 84, produced by the
  /// merge described in CONSENSUS. Per-provider positions before
  /// reconciliation live in SOURCES[].REPORTED_LATITUDE/REPORTED_LONGITUDE and
  /// are never overwritten by this value.
  LATITUDE:double;
  LONGITUDE:double;
  /// Radius in metres of the area within which the site's observations were
  /// collected — a positional-uncertainty envelope, not a transmission range,
  /// not a coverage guarantee, and never converted from another unit. Zero
  /// means unpublished.
  RANGE_M:double;
  /// Independent observations behind the winning report. Zero means the source
  /// publishes no observation count, never that the site was never observed.
  SAMPLES:uint;
  /// Mean received signal strength in dBm across those observations, as the
  /// source publishes it. Carried in dBm unconverted; a consumer needing watts
  /// converts at the join, explicitly. Zero means unpublished.
  AVERAGE_SIGNAL_DBM:double;
  /// RFC 3339 UTC fixed-millisecond bounds of the observation window backing
  /// the winning report.
  FIRST_OBSERVED:string;
  LAST_OBSERVED:string;
  /// Network operator name verbatim as the cited source states it. A display
  /// name, never an identifier: consumers must not treat it as a stable key.
  OPERATOR:string;
  /// Operating centre frequency in MHz, following the $RFB convention. A
  /// consumer joining to $IQC, which carries hertz, converts at the join,
  /// explicitly. Zero means unpublished.
  FREQUENCY_MHZ:double;
  /// Site or structure name verbatim when the source publishes one. Never
  /// synthesized from coordinates, operator, or cell identity.
  SITE_NAME:string;
  /// ISO 3166-1 alpha-2 country code, uppercase, as the source states it.
  /// Derived from MCC only when the source itself derives it.
  COUNTRY_CODE:string;
  /// Every provider consulted for this site, including providers that returned
  /// nothing. Required: a site with no named sources is not publishable.
  SOURCES:[TBSProvenance] (required);
  /// How the entries in SOURCES were reduced to LATITUDE/LONGITUDE. Required:
  /// a published position always states the rule that produced it, including
  /// SINGLE_SOURCE.
  CONSENSUS:TBSConsensus (required);
}

root_type TBS;
file_identifier "$TBS";

TDM.IDL:
// Hash: a38b365287a4b3be346777f9c4c8a9b5cd9525f7fb5fcc227faa3f30be05bd2e
// Version: 2.0.4
// -----------------------------------END_HEADER
include "../RFM/main.fbs";

// Based on CCSDS 503.0-B-2 Cor.1 (June 2020), which SUPERSEDES 503.0-B-1
// (November 2007). Field comments citing 503.0-B-1 page numbers are the
// original provenance of fields added under B-1 and are retained as history.
//
// Time Reconstruction:
// Individual observation times can be reconstructed using the step-size formula:
//   time[i] = OBSERVATION_START_TIME + (i * OBSERVATION_STEP_SIZE)
// where i is the zero-based index into the observation arrays.
//
/// One uplink transmitter frequency ramp applying over a closed time interval.
///
/// SDS EXTENSION beyond CCSDS 503.0-B-1: the base standard carries a single
/// TRANSMIT_FREQ_1 per segment, which cannot express a ramped uplink. Deep-space
/// radiometric archives carry an explicit ramp table and the Doppler observables
/// are NOT reconstructible without it. Ramps are optional; a record that omits
/// TRANSMIT_RAMPS is exactly a CCSDS-conformant TDM.
///
/// Frequency over the interval is the linear polynomial
///   f(t) = FREQUENCY_HZ + FREQUENCY_RATE_HZ_PER_S * (t - REFERENCE_TIME)
/// which is the common form of the two archive representations: DSN ODF
/// (TRK-2-18, table 3-5) supplies ramp start frequency, ramp rate, and ramp
/// start/end time, so REFERENCE_TIME equals START_TIME; ESA IFMS supplies a
/// ramp reference time with constant and linear transmission-frequency terms,
/// so REFERENCE_TIME is that reference time and may precede START_TIME.
/// Producers MUST set REFERENCE_TIME explicitly rather than letting a consumer
/// assume which convention was used.
table TDMTransmitRamp {
  /// Start of the interval over which this ramp applies, ISO 8601.
  START_TIME: string;
  /// End of the interval over which this ramp applies, ISO 8601.
  END_TIME: string;
  /// Epoch at which FREQUENCY_HZ is the instantaneous value, ISO 8601.
  REFERENCE_TIME: string;
  /// Transmitted frequency at REFERENCE_TIME, Hz.
  FREQUENCY_HZ: double;
  /// Constant ramp rate over the interval, Hz per second.
  FREQUENCY_RATE_HZ_PER_S: double;
  /// Identifier of the transmitting station the ramp applies to. Must match
  /// the PARTICIPANT_n naming used by the segment when both are present.
  TRANSMITTING_STATION_ID: string;
  /// Uplink band the ramp applies to, using the same vocabulary as
  /// TRANSMIT_BAND (e.g. "S", "X", "Ka", "Ku").
  TRANSMIT_BAND: string;
}

/// ONE CCSDS TDM observation: a single data-section line.
///
/// A TDM data section is NOT a uniform grid. Every line in every published
/// example (CCSDS 503.0-B-2 Cor.1 annex E, 18 figures) has the literal form
///
///     KEYWORD = <epoch> <value>
///
/// and the epochs are chosen INDEPENDENTLY PER KEYWORD. Figure E-17 (ground
/// based radar tracking with RCS) is decisive: RANGE, ANGLE_1, ANGLE_2 and
/// CARRIER_POWER share epochs, while the final RCS line repeats the EARLIER
/// epoch 2011-05-11T10:26:33.7008 after a 10:26:33.9686 line. No single
/// OBSERVATION_START_TIME + i * OBSERVATION_STEP_SIZE grid can express that,
/// which is why the parallel observation arrays on the TDM root cannot
/// round-trip a conformant TDM.
///
/// KEYWORD is the CCSDS data keyword verbatim and case-exact, e.g. "RANGE",
/// "ANGLE_1", "CARRIER_POWER", "RCS", "DOPPLER_INTEGRATED", "PR_N0",
/// "RECEIVE_FREQ_1", "TRANSMIT_PHASE_CT_1", "VLBI_DELAY", "DOR", "MAG",
/// "CLOCK_BIAS", "STEC", "TROPO_DRY", "PRESSURE". Carrying the keyword rather
/// than a fixed field per observable is what lets this form transport the whole
/// 503.0-B-2 data vocabulary, including keywords a future issue adds, without
/// a wire change and without inventing a name the standard does not define.
///
/// Units are those the standard assigns to that keyword; RANGE additionally
/// depends on RANGE_UNITS, which is metadata, not data.
table TDMObservation {
  /// CCSDS data keyword, verbatim and case-exact.
  KEYWORD: string;
  /// Epoch of this single observation, ISO 8601, in the segment TIME_SYSTEM.
  EPOCH: string;
  /// Observed value.
  VALUE: double;
}

/// One TDM metadata + data segment.
///
/// A TDM file may carry MANY segments, each with its own META_START/META_STOP
/// block and its own DATA_START/DATA_STOP block (503.0-B-2 Cor.1 annex E,
/// figures E-16 and E-18). The TDM root models a SINGLE segment, so a
/// multi-segment file cannot be represented without this vector.
table TDMSegment {
  /// Comments carried in this segment's metadata block, in file order.
  COMMENT: [string];
  META_START: string;
  TIME_SYSTEM: string;
  START_TIME: string;
  STOP_TIME: string;
  PARTICIPANT_1: string;
  PARTICIPANT_2: string;
  PARTICIPANT_3: string;
  PARTICIPANT_4: string;
  PARTICIPANT_5: string;
  MODE: string;
  PATH_1: ushort;
  PATH_2: ushort;
  TRANSMIT_BAND: string;
  RECEIVE_BAND: string;
  INTEGRATION_INTERVAL: double;
  INTEGRATION_REF: string;
  TIMETAG_REF: string;
  ANGLE_TYPE: string;
  RANGE_MODE: string;
  RANGE_MODULUS: double;
  CORRECTION_ANGLE_1: double;
  CORRECTION_ANGLE_2: double;
  CORRECTIONS_APPLIED: string;
  DATA_QUALITY: string;
  RECEIVE_DELAY_2: double;
  RECEIVE_DELAY_3: double;
  TRANSMIT_FREQ_1: double;
  TRANSMIT_FREQ_2: double;
  TRANSMIT_FREQ_3: double;
  TRANSMIT_FREQ_4: double;
  TRANSMIT_FREQ_5: double;
  TRANSMIT_FREQ_RATE_1: double;
  TRANSMIT_FREQ_RATE_2: double;
  TRANSMIT_FREQ_RATE_3: double;
  TRANSMIT_FREQ_RATE_4: double;
  TRANSMIT_FREQ_RATE_5: double;
  META_STOP: string;
  DATA_START: string;
  /// The segment's observations, in FILE ORDER. This is the authoritative
  /// data-section representation.
  OBSERVATIONS: [TDMObservation];
  DATA_STOP: string;
  /// Uplink frequency ramp table applying to this segment. SDS EXTENSION;
  /// absent (not empty) for a ramp-free, exactly CCSDS-conformant segment.
  TRANSMIT_RAMPS: [TDMTransmitRamp];
  /// Unique message identifier (503.0-B-2 table 3-2).
  MESSAGE_ID: string;
  /// Free-text tracking-pass identifier (503.0-B-2 table 3-3).
  TRACK_ID: string;
  /// Comma-separated list of the data keywords present in the data section.
  DATA_TYPES: string;
  /// Signal path through the participants as an ordered comma-separated list,
  /// e.g. "1,2,1". Distinct from the numbered PATH_1 / PATH_2 above.
  PATH: string;
  /// Name of the ephemeris used to generate the data, per participant.
  EPHEMERIS_NAME_1: string;
  EPHEMERIS_NAME_2: string;
  EPHEMERIS_NAME_3: string;
  EPHEMERIS_NAME_4: string;
  EPHEMERIS_NAME_5: string;
  /// Units of the RANGE observable: "km", "s" or "RU" (range units).
  /// RANGE is meaningless without it.
  RANGE_UNITS: string;
  /// Reference frame for angle and position data, as the verbatim CCSDS
  /// keyword value (503.0-B-2 annex B).
  REFERENCE_FRAME: string;
  /// Recommended interpolation method for the observations.
  INTERPOLATION: string;
  /// Recommended interpolation degree.
  INTERPOLATION_DEGREE: uint;
  /// Frequency offset applied to the observations, Hz.
  FREQ_OFFSET: double;
  /// Transponder turnaround ratio numerator.
  TURNAROUND_NUMERATOR: int;
  /// Transponder turnaround ratio denominator.
  TURNAROUND_DENOMINATOR: int;
  /// Transmit delays by participant, s.
  TRANSMIT_DELAY_1: double;
  TRANSMIT_DELAY_2: double;
  TRANSMIT_DELAY_3: double;
  TRANSMIT_DELAY_4: double;
  TRANSMIT_DELAY_5: double;
  /// Receive delay for the first participant, s. (RECEIVE_DELAY_2 and
  /// RECEIVE_DELAY_3 already exist on the TDM root.)
  RECEIVE_DELAY_1: double;
  RECEIVE_DELAY_4: double;
  RECEIVE_DELAY_5: double;
  /// Doppler count bias, Hz.
  DOPPLER_COUNT_BIAS: double;
  /// Doppler count scale factor.
  DOPPLER_COUNT_SCALE: uint;
  /// Whether the Doppler counter rolls over (CCSDS YES/NO).
  DOPPLER_COUNT_ROLLOVER: bool;
  /// Corrections that a consumer must apply, or that were applied when
  /// CORRECTIONS_APPLIED is "YES". Units follow the corrected observable.
  CORRECTION_RANGE: double;
  CORRECTION_DOPPLER: double;
  CORRECTION_MAG: double;
  CORRECTION_RCS: double;
  CORRECTION_RECEIVE: double;
  CORRECTION_TRANSMIT: double;
  CORRECTION_ABERRATION_YEARLY: double;
  CORRECTION_ABERRATION_DIURNAL: double;
}

/// Tracking Data Message
table TDM {

  /// Unique identifier for the observation OBSERVER -  [Specific CCSDS Document]
  OBSERVER_ID: string;

  /// Cartesian X coordinate of the OBSERVER location in chosen reference frame
  OBSERVER_X: double;

  /// Cartesian Y coordinate of the OBSERVER location in chosen reference frame 
  OBSERVER_Y: double;

  /// Cartesian Z coordinate of the OBSERVER location in chosen reference frame 
  OBSERVER_Z: double;

  /// Cartesian X coordinate of the OBSERVER velocity in chosen reference frame
  OBSERVER_VX: double;

  /// Cartesian Y coordinate of the OBSERVER velocity in chosen reference frame 
  OBSERVER_VY: double;

  /// Cartesian Z coordinate of the OBSERVER velocity in chosen reference frame 
  OBSERVER_VZ: double;

  /// Reference frame used for OBSERVER location Cartesian coordinates (e.g., ECEF, ECI)
  OBSERVER_POSITION_REFERENCE_FRAME: RFM;

  /// Reference frame used for obs location Cartesian coordinates (e.g., ECEF, ECI)
  OBS_REFERENCE_FRAME: RFM;

  /// Epoch time or observation time, in ISO 8601 UTC format -  CCSDS 503.0-B-1
  EPOCH: string;

  /// Time interval between observations in seconds (required).
  /// Time reconstruction: time[i] = OBSERVATION_START_TIME + (i * OBSERVATION_STEP_SIZE)
  OBSERVATION_STEP_SIZE:double;

  /// Start time for observation time reconstruction (ISO 8601 UTC format).
  OBSERVATION_START_TIME:string;

  /// TDM version number -  CCSDS 503.0-B-1, Page D-9
  CCSDS_TDM_VERS: string;

  /// Comments regarding TDM -  various sections, e.g., Page D-9
  COMMENT: [string];

  /// Date of TDM creation -  CCSDS 503.0-B-1, Page D-9
  CREATION_DATE: string;

  /// Originator of the TDM -  CCSDS 503.0-B-1, Page D-9
  ORIGINATOR: string;

  /// Start of metadata section -  CCSDS 503.0-B-1, Page D-9
  META_START: string;

  /// Time system used -  CCSDS 503.0-B-1, Page D-9
  TIME_SYSTEM: string;

  /// Start time of the data -  CCSDS 503.0-B-1, Page D-9
  START_TIME: string;

  /// Stop time of the data -  CCSDS 503.0-B-1, Page D-9
  STOP_TIME: string;

  /// First participant in the TDM -  CCSDS 503.0-B-1, Page D-9
  PARTICIPANT_1: string;

  /// Second participant in the TDM -  CCSDS 503.0-B-1, Page D-9
  PARTICIPANT_2: string;

  /// Third participant in the TDM (if applicable) -  CCSDS 503.0-B-1, Page D-9
  PARTICIPANT_3: string;

  /// Fourth participant in the TDM (if applicable) -  CCSDS 503.0-B-1, Page D-9
  PARTICIPANT_4: string;

  /// Fifth participant in the TDM (if applicable) -  CCSDS 503.0-B-1, Page D-9, max participants
  PARTICIPANT_5: string;

  /// Mode of TDM -  CCSDS 503.0-B-1, Page D-9
  MODE: string;

  /// First path in TDM -  CCSDS 503.0-B-1, Page D-9
  PATH_1: ushort;

  /// Second path in TDM (if applicable) -  CCSDS 503.0-B-1, Page D-9
  PATH_2: ushort;

  /// Transmit band -  CCSDS 503.0-B-1, Page D-9
  TRANSMIT_BAND: string;

  /// Receive band -  CCSDS 503.0-B-1, Page D-9
  RECEIVE_BAND: string;

  /// Integration interval -  CCSDS 503.0-B-1, Page D-9
  INTEGRATION_INTERVAL: float;

  /// Integration reference -  CCSDS 503.0-B-1, Page D-9
  INTEGRATION_REF: string;

  /// Receive delay for second participant -  CCSDS 503.0-B-1, Page D-9
  RECEIVE_DELAY_2: double;

  /// Receive delay for third participant -  CCSDS 503.0-B-1, Page D-9
  RECEIVE_DELAY_3: double;

  /// Data quality -  CCSDS 503.0-B-1, Page D-9
  DATA_QUALITY: string;

  /// End of metadata section -  CCSDS 503.0-B-1, Page D-9
  META_STOP: string;

  /// Start of data section -  CCSDS 503.0-B-1, Page D-9
  DATA_START: string;

  /// Transmit frequency for first participant -  CCSDS 503.0-B-1, Page D-9
  TRANSMIT_FREQ_1: double;

  /// Receive frequency -  CCSDS 503.0-B-1, Page D-9
  RECEIVE_FREQ: [double];

  /// End of data section -  CCSDS 503.0-B-1, Page D-9
  DATA_STOP: string;

  /// Additional properties as required by the specific application of the TDM...
  /// Reference for time tagging -  CCSDS 503.0-B-1, Page D-10
  TIMETAG_REF: string;

  /// Type of angle data -  CCSDS 503.0-B-1, Page D-12
  /// Can be AZEL, RADEC, XEYN, XSYE, or another value with provided ICD
  ANGLE_TYPE: string;

  /// First angle value -  CCSDS 503.0-B-1, Page D-12
  ANGLE_1: [float];

  /// Second angle value -  CCSDS 503.0-B-1, Page D-12
  ANGLE_2: [float];

  /// Uncertainty of first angle -  CCSDS 503.0-B-1
  ANGLE_UNCERTAINTY_1: float;

  /// Uncertainty of second angle -  CCSDS 503.0-B-1
  ANGLE_UNCERTAINTY_2: float;

  /// Rate of change of range -  CCSDS 503.0-B-1
  RANGE_RATE: double;

  /// Uncertainty in range -  CCSDS 503.0-B-1
  RANGE_UNCERTAINTY: double;

  /// Mode of range data -  CCSDS 503.0-B-1, Page D-10
  RANGE_MODE: string;

  /// Modulus value for range data -  CCSDS 503.0-B-1, Page D-10
  RANGE_MODULUS: double;

  /// First correction angle -  CCSDS 503.0-B-1, Page D-12
  CORRECTION_ANGLE_1: float;

  /// Second correction angle -  CCSDS 503.0-B-1, Page D-12
  CORRECTION_ANGLE_2: float;

  /// Indicator of corrections applied -  CCSDS 503.0-B-1, Page D-12
  CORRECTIONS_APPLIED: string;

  /// Dry component of tropospheric delay -  CCSDS 503.0-B-1, Page D-14
  TROPO_DRY: [double];

  /// Wet component of tropospheric delay -  CCSDS 503.0-B-1, Page D-14
  TROPO_WET: [double];

  /// Slant total electron content -  CCSDS 503.0-B-1, Page D-13
  STEC: [double];

  /// Atmospheric pressure -  CCSDS 503.0-B-1, Page D-14
  PRESSURE: [double];

  /// Relative humidity -  CCSDS 503.0-B-1, Page D-14
  RHUMIDITY: [double];

  /// Ambient temperature -  CCSDS 503.0-B-1, Page D-14
  TEMPERATURE: [double];

  /// Clock bias values -  CCSDS 503.0-B-1, Page D-15
  CLOCK_BIAS: [double];

  /// Clock drift values -  CCSDS 503.0-B-1, Page D-15
  CLOCK_DRIFT: [double];

  /// SDS EXTENSION beyond CCSDS 503.0-B-1. Open-loop (non-coherent) Doppler
  /// quality metrics, one entry per observation, parallel to the other
  /// observation arrays and reconstructed on the same OBSERVATION_START_TIME +
  /// i * OBSERVATION_STEP_SIZE grid.
  ///
  /// Signal-to-noise ratio of the detection.
  SIGNAL_TO_NOISE: [double];

  /// SDS EXTENSION. Normalised spectral maximum of the detection.
  SPECTRAL_MAX: [double];

  /// SDS EXTENSION. 1-sigma noise on the measured Doppler frequency, Hz. The
  /// measured sky frequency itself is carried by RECEIVE_FREQ; this is its
  /// uncertainty, which CCSDS 503.0-B-1 has no field for.
  DOPPLER_NOISE_HZ: [double];

  /// SDS EXTENSION beyond CCSDS 503.0-B-1. Uplink transmitter frequency ramp
  /// table covering this segment, ordered by START_TIME and non-overlapping.
  /// Required in practice for ramped uplinks, where TRANSMIT_FREQ_1 alone
  /// cannot reconstruct the observables. Absent for unramped tracking, which
  /// leaves the record exactly CCSDS-conformant.
  TRANSMIT_RAMPS: [TDMTransmitRamp];

  // ───────────────────────────────────────────────────────────────────────────
  // APPENDED (CCSDS 503.0-B-2 Cor.1 conformance). Append-only: never reorder.
  //
  // WHICH FORM WINS:
  //  1. If SEGMENTS is non-empty, SEGMENTS is authoritative for BOTH metadata
  //     and data, and every other field on this root is ignored by parsers.
  //     This is the only form that can carry a multi-segment TDM.
  //  2. Otherwise, if OBSERVATIONS is non-empty, OBSERVATIONS is authoritative
  //     for the data section and the parallel observation arrays above
  //     (ANGLE_1, ANGLE_2, RECEIVE_FREQ, STEC, TROPO_*, PRESSURE, RHUMIDITY,
  //     TEMPERATURE, CLOCK_BIAS, CLOCK_DRIFT, SIGNAL_TO_NOISE, SPECTRAL_MAX,
  //     DOPPLER_NOISE_HZ) are ignored.
  //  3. Otherwise the legacy uniform-grid arrays apply, with epochs
  //     reconstructed as OBSERVATION_START_TIME + i * OBSERVATION_STEP_SIZE.
  //     That grid is an SDS compaction, NOT a CCSDS construct, and is only
  //     correct when every observable was sampled on one uniform schedule.
  //
  // Do NOT populate more than one form.
  // ───────────────────────────────────────────────────────────────────────────

  /// Data-section observations for a SINGLE-segment TDM, in file order.
  OBSERVATIONS: [TDMObservation];

  /// All metadata+data segments of a MULTI-segment TDM, in file order.
  SEGMENTS: [TDMSegment];

  /// Additional transmit frequencies by participant, Hz. TRANSMIT_FREQ_1
  /// already exists above; 2..5 had no carrier.
  TRANSMIT_FREQ_2: double;
  TRANSMIT_FREQ_3: double;
  TRANSMIT_FREQ_4: double;
  TRANSMIT_FREQ_5: double;
  /// Transmit frequency rates by participant, Hz/s. A constant rate here is
  /// the single-interval degenerate case of TRANSMIT_RAMPS.
  TRANSMIT_FREQ_RATE_1: double;
  TRANSMIT_FREQ_RATE_2: double;
  TRANSMIT_FREQ_RATE_3: double;
  TRANSMIT_FREQ_RATE_4: double;
  TRANSMIT_FREQ_RATE_5: double;

  /// Unique message identifier (503.0-B-2 table 3-2).
  MESSAGE_ID: string;
  /// Free-text tracking-pass identifier (503.0-B-2 table 3-3).
  TRACK_ID: string;
  /// Comma-separated list of the data keywords present in the data section.
  DATA_TYPES: string;
  /// Signal path through the participants as an ordered comma-separated list,
  /// e.g. "1,2,1". Distinct from the numbered PATH_1 / PATH_2 above.
  PATH: string;
  /// Name of the ephemeris used to generate the data, per participant.
  EPHEMERIS_NAME_1: string;
  EPHEMERIS_NAME_2: string;
  EPHEMERIS_NAME_3: string;
  EPHEMERIS_NAME_4: string;
  EPHEMERIS_NAME_5: string;
  /// Units of the RANGE observable: "km", "s" or "RU" (range units).
  /// RANGE is meaningless without it.
  RANGE_UNITS: string;
  /// Reference frame for angle and position data, as the verbatim CCSDS
  /// keyword value (503.0-B-2 annex B).
  REFERENCE_FRAME: string;
  /// Recommended interpolation method for the observations.
  INTERPOLATION: string;
  /// Recommended interpolation degree.
  INTERPOLATION_DEGREE: uint;
  /// Frequency offset applied to the observations, Hz.
  FREQ_OFFSET: double;
  /// Transponder turnaround ratio numerator.
  TURNAROUND_NUMERATOR: int;
  /// Transponder turnaround ratio denominator.
  TURNAROUND_DENOMINATOR: int;
  /// Transmit delays by participant, s.
  TRANSMIT_DELAY_1: double;
  TRANSMIT_DELAY_2: double;
  TRANSMIT_DELAY_3: double;
  TRANSMIT_DELAY_4: double;
  TRANSMIT_DELAY_5: double;
  /// Receive delay for the first participant, s. (RECEIVE_DELAY_2 and
  /// RECEIVE_DELAY_3 already exist on the TDM root.)
  RECEIVE_DELAY_1: double;
  RECEIVE_DELAY_4: double;
  RECEIVE_DELAY_5: double;
  /// Doppler count bias, Hz.
  DOPPLER_COUNT_BIAS: double;
  /// Doppler count scale factor.
  DOPPLER_COUNT_SCALE: uint;
  /// Whether the Doppler counter rolls over (CCSDS YES/NO).
  DOPPLER_COUNT_ROLLOVER: bool;
  /// Corrections that a consumer must apply, or that were applied when
  /// CORRECTIONS_APPLIED is "YES". Units follow the corrected observable.
  CORRECTION_RANGE: double;
  CORRECTION_DOPPLER: double;
  CORRECTION_MAG: double;
  CORRECTION_RCS: double;
  CORRECTION_RECEIVE: double;
  CORRECTION_TRANSMIT: double;
  CORRECTION_ABERRATION_YEARLY: double;
  CORRECTION_ABERRATION_DIURNAL: double;
}

root_type TDM;
file_identifier "$TDM";

PMM.IDL:
// Hash: 744d3f6e56d5fcad680f066862ec3799bfa489734a3ecc79ef7b573b1fd04540
// Version: 1.170.3
// -----------------------------------END_HEADER
// Provider Module Manifest (PMM)
// Description
// The signed, anonymously-fetchable list of WASM modules a single provider
// (one SDN node, identified by one domain and one node key) offers to client
// applications. A client application loads this record AT BOOT, before any
// user session exists, to learn which modules the provider serves, which of
// them the provider declares CORE (loadable with no session), and how to
// verify every artifact byte-for-byte.
//
// Relationship to the neighbouring standards:
//   `$PLG` is the per-module listing (full invoke surface, storefront and
//   protected-delivery detail). `$STF` is the per-dataset listing. `$STO` is a
//   commerce storefront identity (commission terms, settlement chains, IPFS
//   catalog root). `$APP` is the per-application manifest naming the modules
//   ONE app composes. None of them answers "what does this provider node
//   serve, under which key, and what may an anonymous client load" — that is
//   `$PMM`. PMM is deliberately slim: an entry carries the identity, integrity
//   and trust fields a boot-time verifier needs and refers to `$PLG` by
//   `PLUGIN_ID`/`PLG_CID` for everything else.
//
// Trust chain (verify in this order, fail closed at any step):
//   1. artifact bytes  -> `PMMModuleEntry.CONTENT_HASH`
//   2. `CONTENT_HASH`  -> `PMMModuleEntry.ARTIFACT_SIGNATURE` (provider node key)
//   3. manifest        -> `PMM.SIGNATURE` over the canonical statement below
//                         (provider node key)
//   4. node key        -> domain, via the DNS proof named in
//                         `PMMTrustAnchor.DNS_PROOF_RECORD_NAME`
//   5. domain          -> economic weight, via the Adversarial-Security bond
//                         held by `PMMTrustAnchor.BOND_ADDRESSES`
// Steps 1-3 are self-contained in this record. Steps 4-5 are references, so
// this standard does not restate another standard's proof format.
//
// CANONICAL SIGNED STATEMENT (`PMM.SIGNATURE` covers exactly these bytes):
//   UTF-8, LF line endings, no CR, no trailing whitespace, every line
//   LF-terminated including the last. Enum values appear as their IDL symbol
//   names. Booleans appear as `1` or `0`.
//
//     SDN-MODULE-MANIFEST-V1
//     domain:<PROVIDER_DOMAIN>
//     peer:<TRUST.NODE_PEER_ID>
//     key:<TRUST.SIGNING_PUBLIC_KEY>
//     epoch:<EPOCH>
//     expires:<EXPIRES_AT>
//     module:<MODULE_ID> <VERSION> <CONTENT_HASH> <TRUST_TIER> <ACCESS_POLICY> <DEFAULT_ENABLED> <ENTRY_STATE>
//     ...
//
//   One `module:` line per entry in `MODULES`, sorted bytewise ascending by
//   `MODULE_ID`, single ASCII space between fields. A verifier MUST rebuild
//   this statement from the record's own fields and MUST reject the manifest
//   if the rebuilt bytes differ from `SIGNED_STATEMENT` when that field is
//   present, so the carried copy can never become a second source of truth.
//
// ANONYMOUS CORE LOAD (the whole point of the record): an entry is loadable
// with no user session only when `TRUST_TIER == CORE`, `ACCESS_POLICY ==
// ANONYMOUS`, `DEFAULT_ENABLED == true`, `ENTRY_STATE == ACTIVE`, the
// manifest has not expired, and steps 1-4 above verify. On the user's first
// authenticated session such entries are presented already selected; a
// recorded user choice always overrides `DEFAULT_ENABLED` from then on.
// `EPOCH` is monotonic per provider: a client MUST reject a manifest whose
// `EPOCH` is lower than the highest it has already verified for that
// `PROVIDER_DOMAIN` (rollback protection).

include "../EPM/main.fbs";
include "../PLG/main.fbs";

/// Provider-declared standing of a module in its own offering. Append new
/// values only; never reorder or reuse existing values.
enum pmmTrustTier : ubyte {
  /// Not stated. Treated as OPTIONAL by verifiers.
  UNSPECIFIED = 0,
  /// The provider declares this module part of its baseline service. Only a
  /// CORE entry may ever be loaded before a user session exists, and only a
  /// CORE entry is presented pre-selected at first sign-in.
  CORE = 1,
  /// Offered and endorsed by the provider, but never loaded without an
  /// explicit user selection.
  RECOMMENDED = 2,
  /// Offered only.
  OPTIONAL = 3
}

/// What a client must hold before the artifact may be fetched and
/// instantiated. Append new values only; never reorder or reuse existing
/// values.
enum pmmAccessPolicy : ubyte {
  /// No session, no grant: an unauthenticated client may fetch and run it.
  ANONYMOUS = 0,
  /// An authenticated session is required.
  AUTHENTICATED = 1,
  /// An entitlement or license grant is required (see `$ENT`, `$PLK`).
  ENTITLED = 2
}

/// Lifecycle of one manifest entry. Append new values only; never reorder or
/// reuse existing values.
enum pmmEntryState : ubyte {
  /// Served and loadable.
  ACTIVE = 0,
  /// Still served, superseded by another entry. Clients SHOULD migrate.
  DEPRECATED = 1,
  /// No longer served. Clients MUST NOT fetch it.
  WITHDRAWN = 2,
  /// Actively distrusted by the provider (compromise, bad build). Clients
  /// MUST refuse this CONTENT_HASH even if they already hold the bytes.
  REVOKED = 3
}

/// The single key identity every signature in this manifest resolves to, and
/// the two external anchors that give that key its weight: the DNS proof that
/// binds it to the domain, and the Adversarial-Security bond that prices
/// trust in it.
table PMMTrustAnchor {
  /// Domain the node key is bound to. MUST equal `PMM.PROVIDER_DOMAIN` and
  /// MUST equal the origin the manifest was fetched from.
  PROVIDER_DOMAIN: string;
  /// libp2p peer id of the provider node.
  NODE_PEER_ID: string;
  /// BIP-32 account xpub of the node identity, verbatim as advertised in the
  /// node's `$EPM`.
  NODE_XPUB: string;
  /// Hex-encoded public key that verifies `PMM.SIGNATURE` and every
  /// `PMMModuleEntry.ARTIFACT_SIGNATURE`, derived from the node key.
  SIGNING_PUBLIC_KEY: string;
  /// HD derivation path of `SIGNING_PUBLIC_KEY` under `NODE_XPUB`.
  SIGNING_KEY_PATH: string;
  /// Signature algorithm identifier, e.g. "ed25519",
  /// "secp256k1-compact-ethereum". Empty means "ed25519".
  SIGNATURE_ALGORITHM: string;
  /// IPFS CID of the provider node's `$EPM`.
  EPM_CID: string;
  /// Fully-qualified DNS name of the TXT record carrying the signed
  /// domain-to-nodekey proof, e.g. "_sdnkey.example.org". A verifying client
  /// resolves this itself (DNS-over-HTTPS) rather than trusting the copy
  /// below.
  DNS_PROOF_RECORD_NAME: string;
  /// Verbatim TXT value of that proof, carried only so a client can detect
  /// disagreement with what DNS returns. The resolved record always wins.
  DNS_PROOF_TXT: string;
  /// The canonical statement the DNS proof signs, verbatim, when the proof
  /// format keeps it out of the TXT value.
  DNS_PROOF_STATEMENT: string;
  /// Chain addresses derived from this same node key that hold the provider's
  /// Adversarial-Security bond. Each entry proves, through `ChainProof`, that
  /// the address derives from the key that signed this manifest.
  BOND_ADDRESSES: [ChainProof];
  /// Optional URL of a machine-readable bond attestation (bonded value,
  /// duration unspent) for clients that price trust rather than gate on it.
  BOND_ATTESTATION_URL: string;
}

/// One module the provider offers.
table PMMModuleEntry {
  /// Reverse-DNS module identity, e.g. "com.orbpro.sgp4-propagator". Stable
  /// across versions. Required and unique within the manifest.
  MODULE_ID: string (required, key);
  /// `$PLG.PLUGIN_ID` of the full listing for this module, when one is
  /// published.
  PLUGIN_ID: string;
  /// IPFS CID of that `$PLG` record.
  PLG_CID: string;
  /// Display name.
  NAME: string;
  /// Human-readable summary.
  DESCRIPTION: string;
  /// SemVer 2.0.0 version of the offered artifact.
  VERSION: string;
  /// Monotonic publication counter for this MODULE_ID. Increases on every
  /// re-publication, including a rebuild at the same VERSION.
  EPOCH: uint64;
  /// 64 lowercase hexadecimal characters encoding SHA-256 of the module's
  /// portable (pre-AOT, publication-trailer-stripped) WASM bytes. Identical
  /// in meaning to `$APP.APPModuleRef.CONTENT_HASH`: this is the identity
  /// capability and signature policies key on.
  CONTENT_HASH: string;
  /// Size of those portable WASM bytes.
  ARTIFACT_SIZE_BYTES: uint64;
  /// Path, relative to the provider origin, from which the artifact is
  /// fetched. Relative on purpose: the bytes must come from the same origin
  /// whose domain the DNS proof binds.
  ARTIFACT_PATH: string;
  /// IPFS CID of the artifact, for content-addressed retrieval.
  ARTIFACT_CID: string;
  /// Detached signature by the key in `PMMTrustAnchor.SIGNING_PUBLIC_KEY`
  /// over the 32 raw bytes of `CONTENT_HASH`. Lets a client reject an entry
  /// before spending a byte of bandwidth. The artifact's own publication
  /// trailer remains authoritative after download.
  ARTIFACT_SIGNATURE: [ubyte];
  /// Provider-declared standing. Gates anonymous loading.
  TRUST_TIER: pmmTrustTier = UNSPECIFIED;
  /// True when the provider ships this module enabled by default. A recorded
  /// user choice overrides it permanently.
  DEFAULT_ENABLED: bool = false;
  /// What the client must hold to fetch and run it.
  ACCESS_POLICY: pmmAccessPolicy = AUTHENTICATED;
  /// Entry lifecycle.
  ENTRY_STATE: pmmEntryState = ACTIVE;
  /// Opaque runtime-target tags this artifact is built for, e.g. "browser",
  /// "wasmedge". Same vocabulary as `$PLG.RUNTIME_TARGETS`.
  RUNTIME_TARGETS: [string];
  /// SDS schema codes at this module's invoke surface, e.g. "OMM", "OEM".
  REQUIRED_SCHEMAS: [string];
  /// Minimum host permissions the module needs, same vocabulary as
  /// `$PLG.MIN_PERMISSIONS`. Surfaced so a client can show what an
  /// anonymously-loaded CORE module is allowed to do.
  MIN_PERMISSIONS: [string];
  /// SPDX license identifier of the module.
  LICENSE: string;
  /// URL to the module's documentation.
  DOCUMENTATION_URL: string;
  /// URL to the module's icon.
  ICON_URL: string;
  /// `CONTENT_HASH` this entry replaces, when it supersedes an earlier build.
  SUPERSEDES_CONTENT_HASH: string;
  /// RFC 3339 UTC fixed-millisecond timestamp (YYYY-MM-DDTHH:mm:ss.sssZ) of
  /// the last change to this entry.
  UPDATED_AT: string;
  /// Family this module belongs to. Mirrors `$PLG.PLUGIN_TYPE` verbatim and
  /// is the ONLY sanctioned way to group an offering: a client grouping a
  /// catalogue MUST read this field and MUST NOT infer family from the shape
  /// of `MODULE_ID`, which carries no normative structure. Defaults to
  /// `Unspecified`, which a client MUST render as ungrouped — never silently
  /// as `Sensor`. Present here, rather than only on
  /// the linked `$PLG`, so an anonymous client can section the catalogue at
  /// boot without fetching one `$PLG` per module.
  PLUGIN_TYPE: pluginCategory = Unspecified;
  /// The one ratified `$CCT` category this module is shelved under. Mirrors
  /// `$PLG.PRIMARY_CATEGORY` verbatim and SUPERSEDES `PLUGIN_TYPE` as the
  /// sanctioned way to group an offering: `pluginCategory` is single-valued,
  /// holds a real family at ordinal 0, mixes capability families with
  /// node-internal plumbing, and carries a deprecated vendor-derived member.
  /// Present here, rather than only on the linked `$PLG`, so an anonymous
  /// client can section the catalogue at boot without fetching one `$PLG` per
  /// module. `UNSPECIFIED` MUST render as ungrouped, never as a real category.
  ///
  /// SIGNATURE SEAM — normative. Under the `SDN-MODULE-MANIFEST-V1` canonical
  /// statement this field is NOT covered by `PMM.SIGNATURE`, exactly like
  /// `NAME`, `DESCRIPTION` and `ICON_URL`. It is an UNVERIFIED PROVIDER CLAIM
  /// resting on a signed content hash. A consumer that shelves, filters or
  /// counts by this field MUST NOT present the resulting grouping as
  /// authenticated, and MUST keep the verified identity (`MODULE_ID`,
  /// `CONTENT_HASH`, `ARTIFACT_SIGNATURE`, `TRUST_TIER`) visually separable
  /// from provider-supplied presentation. Extending the canonical statement to
  /// cover presentation fields is a `SDN-MODULE-MANIFEST-V2` change that moves
  /// every verifier in lockstep and is not made implicitly by adopting this
  /// field.
  PRIMARY_CATEGORY: capabilityClass = UNSPECIFIED;
  /// Every ratified `$CCT` category this module belongs to, for browse, filter
  /// and per-category counting. Mirrors `$PLG.CATEGORIES`. If nonempty it MUST
  /// include PRIMARY_CATEGORY. Carries the same unsigned-claim caveat as
  /// PRIMARY_CATEGORY.
  CATEGORIES: [capabilityClass];
}

/// Provider Module Manifest — what one provider node offers, signed by that
/// node's key.
table PMM {
  /// Domain of the provider, e.g. "node.example.org". Required. MUST equal
  /// the origin the manifest was served from.
  PROVIDER_DOMAIN: string (required);
  /// Display name of the provider.
  PROVIDER_NAME: string;
  /// Human-readable summary of what the provider serves.
  DESCRIPTION: string;
  /// Monotonic manifest epoch. A client MUST reject an epoch lower than the
  /// highest it has already verified for `PROVIDER_DOMAIN`.
  EPOCH: uint64;
  /// The key identity and its external anchors.
  TRUST: PMMTrustAnchor;
  /// The offered modules.
  MODULES: [PMMModuleEntry];
  /// Canonical absolute URL this manifest is served from.
  CANONICAL_URL: string;
  /// RFC 3339 UTC fixed-millisecond timestamp (YYYY-MM-DDTHH:mm:ss.sssZ)
  /// when the manifest was created.
  CREATED_AT: string;
  /// RFC 3339 UTC fixed-millisecond timestamp (YYYY-MM-DDTHH:mm:ss.sssZ)
  /// when the manifest was last signed.
  UPDATED_AT: string;
  /// RFC 3339 UTC fixed-millisecond timestamp (YYYY-MM-DDTHH:mm:ss.sssZ)
  /// after which a verifier MUST refuse anonymous CORE loading from this
  /// manifest and re-fetch. Required in practice for anonymous trust: an
  /// unexpiring signed manifest cannot be withdrawn.
  EXPIRES_AT: string;
  /// Signature by `TRUST.SIGNING_PUBLIC_KEY` over the canonical statement
  /// defined in this file's header.
  SIGNATURE: [ubyte];
  /// The canonical statement, verbatim. A verifier MUST rebuild it from this
  /// record and reject any difference.
  SIGNED_STATEMENT: string;
}

root_type PMM;
file_identifier "$PMM";

BPF.IDL:
// Hash: 19fcc268d40025fd924c20ccadec91ef5208a6485c0102aae5e8b1c2007756a8
// Version: 1.199.0
// -----------------------------------END_HEADER
include "../PLG/main.fbs";

/// Build Profile ($BPF)
///
/// The authoring-time configuration of one composed build: which variable
/// parts of a build template are embedded, which modules roll in and at what
/// protection tier, the runtime lock the produced artifact enforces, the
/// distribution-control mode, and the template the profile was authored
/// against. It is a CONFIGURATION record, not a grant and not an entitlement:
/// it names no licensee, carries no key material, and confers no rights.
///
/// Related records, and why this is not one of them:
///   - `$PLK` is a per-licensee license key with issuer/licensee identity,
///     activation counts and a validity window. `$BPF` has no licensee.
///   - `$LGR` is a delivery-time grant carrying wrapped content keys and a
///     provider signature. `$BPF` carries neither.
///   - `$PLG` is the module descriptor. `$BPF` REFERENCES it per selected
///     module and never restates a module's manifest.
///   - `$APP` is the launchable-app manifest. It is the portability wrapper
///     for a `$BPF`, never a substitute for it.
///
/// The domain-restriction spelling is deliberately the ratified `$PLK`
/// spelling — `ALLOWED_DOMAINS` / `ALLOWED_TLDS` — so a lock authored here
/// and a lock issued there are the same vocabulary on the wire.

/// Class of variable part a build template exposes as a named slot.
/// Capability classes only; a deployment's own slot names ride in
/// `BPFPart.PART_ID`, never in this vocabulary. Append new values only;
/// never reorder or reuse existing values.
enum bpfPartKind : byte {
  /// The publisher did not classify the part. A consumer renders it by
  /// PART_ID and never infers a class.
  UNSPECIFIED = 0,
  /// The compiled engine binary payload.
  ENGINE_BINARY,
  /// Embedded imagery data.
  IMAGERY_DATA,
  /// Embedded endpoint/locator data.
  URL_DATA,
  /// Embedded end-user documentation.
  DOCUMENTATION,
  /// The cross-origin-isolation loader pair required for shared-memory
  /// execution in a browsing context.
  ISOLATION_LOADER,
  /// Debug source maps.
  SOURCE_MAPS,
  /// A module payload embedded in the artifact.
  MODULE,
  /// A part outside every class above.
  OTHER
}

/// How a selected module's payload is protected inside the produced
/// artifact. Append new values only; never reorder or reuse existing values.
enum bpfProtectionTier : byte {
  /// The publisher did not state a tier. A consumer MUST NOT infer one and
  /// MUST NOT treat this as OPEN.
  UNSPECIFIED = 0,
  /// Plaintext payload; no content-key unwrap is performed.
  OPEN,
  /// Ciphertext payload whose content key is wrapped for a recipient key
  /// carried by the artifact itself.
  ENCRYPTED,
  /// Ciphertext payload whose content key is wrapped for a recipient key
  /// derived at runtime from an operator-supplied distribution key; the
  /// artifact carries no recipient key.
  LICENSED
}

/// Distribution-control mode of the produced artifact. This is a build
/// configuration choice, not a commercial term and not an entitlement.
/// Append new values only; never reorder or reuse existing values.
enum bpfLicenseMode : byte {
  /// The publisher did not state a mode. A consumer MUST NOT infer one.
  UNSPECIFIED = 0,
  /// No distribution control: every embedded payload is readable without a
  /// key supplied at runtime.
  NONE,
  /// The artifact carries the recipient key that unwraps its protected
  /// payloads.
  BUNDLED_KEY,
  /// The recipient key is derived at runtime from an operator-supplied
  /// distribution key; the artifact carries no recipient key.
  LICENSE_KEY
}

/// One variable part of the build template and whether this profile embeds
/// it.
table BPFPart {
  /// Template slot identifier this entry configures, as published by the
  /// template's part manifest. Required, unique within the profile.
  PART_ID: string (required, key);
  /// Capability class of the part.
  KIND: bpfPartKind = UNSPECIFIED;
  /// True when the part is embedded in the produced artifact.
  INCLUDED: bool = false;
  /// 64 lowercase hexadecimal characters encoding SHA-256 of the part's
  /// bytes as published by the template, so a composed artifact can be
  /// verified against the profile that produced it.
  CONTENT_SHA256: string;
  /// Size of the part's bytes in octets, as published by the template.
  BYTE_LENGTH: uint64;
  /// Human-readable summary.
  DESCRIPTION: string;
}

/// One module selected into the build and the tier its payload is protected
/// at.
table BPFModule {
  /// Canonical module identifier. Required, unique within the profile.
  MODULE_ID: string (required, key);
  /// Module version or version range.
  MODULE_VERSION: string;
  /// True when the module is embedded in the produced artifact.
  INCLUDED: bool = false;
  /// Protection tier applied to this module's payload.
  PROTECTION: bpfProtectionTier = UNSPECIFIED;
  /// 64 lowercase hexadecimal characters encoding SHA-256 of the module's
  /// portable (pre-AOT, publication-trailer-stripped) bytes. This is the
  /// identity a capability or signature policy keys on.
  CONTENT_HASH: string;
  /// Published module descriptor, carried when the authoring context holds
  /// it. Advisory: `MODULE_ID` and `CONTENT_HASH` are the identity, and a
  /// consumer MUST NOT prefer a carried descriptor over the module's own
  /// published manifest.
  MODULE_DESCRIPTOR: PLG;
}

/// The runtime restriction the produced artifact enforces on itself.
///
/// AUTHORIZATION. A host is authorized when it equals an `ALLOWED_DOMAINS`
/// entry, OR ends with an `ALLOWED_TLDS` entry, OR equals a `DEV_DOMAINS`
/// entry. Suffix rules are DOT-ANCHORED: `.mil` admits `x.mil` and `a.b.mil`
/// and admits neither `mil` nor `evilmil`; a suffix rule never matches a
/// host that merely contains it (`x.mil.example` is refused).
///
/// UNLOCKED IS EXPLICIT. `ALLOWED_DOMAINS` empty AND `ALLOWED_TLDS` empty
/// means every host is authorized. This is a stated, allowed configuration,
/// which is why this table is required on `BPF`: an absent lock is never
/// read as an unlocked one.
///
/// EXPIRY IS INDEPENDENT of authorization: an unlocked profile still
/// expires. There is deliberately no stored expiry instant — expiry is
/// `COMPILED_AT_MS + TTL_DAYS * 86400000` and a second, storable copy of it
/// could disagree with the two values that produce it.
table BPFRuntimeLock {
  /// Exact hostnames authorized to run the produced artifact. Empty
  /// together with `ALLOWED_TLDS` means unrestricted.
  ALLOWED_DOMAINS: [string];
  /// Dot-anchored hostname suffix rules, each written with its leading dot,
  /// for example `.gov`. Empty together with `ALLOWED_DOMAINS` means
  /// unrestricted.
  ALLOWED_TLDS: [string];
  /// Development hosts authorized in addition to the rules above, so a
  /// locked profile remains runnable in a development context. Kept
  /// separate from `ALLOWED_DOMAINS` because a development exemption and a
  /// deployment authorization are different facts: folded together, a
  /// development host would be indistinguishable from a deployment grant
  /// and would silently persist into a locked artifact.
  DEV_DOMAINS: [string];
  /// Lifetime of the produced artifact in days from `COMPILED_AT_MS`.
  /// Normative range 1 through 365 inclusive; 180 when unstated. A value of
  /// 0 or above 365 is invalid and MUST be rejected, never clamped.
  TTL_DAYS: uint32 = 180;
  /// Milliseconds since the Unix epoch at which the artifact was composed.
  /// 0 means the profile has not been used to compose an artifact yet and
  /// carries no expiry; the composing step stamps it.
  COMPILED_AT_MS: uint64;
}

/// The publisher's attestation over this profile, in BOTH ratified forms.
///
/// PRESENCE IS THE STATEMENT. A profile is SIGNED if and only if this table
/// is present; a profile whose `ATTESTATION` is absent is UNSIGNED, and a
/// consumer marks it as such. There is deliberately no boolean saying so: a
/// self-asserted "signed" flag is attacker-controlled and proves nothing,
/// while presence of the table is checkable.
///
/// FAIL CLOSED. When this table is present, every field below MUST be
/// present and BOTH signatures MUST verify independently against
/// `SIGNING_PUBLIC_KEY`. A profile whose attestation is incomplete, or
/// whose either signature fails, is REJECTED — it is NEVER downgraded to
/// "unsigned and therefore acceptable", which would let stripping one
/// signature launder a tampered profile past an importer that admits
/// unsigned input.
table BPFAttestation {
  /// The signer's LITERAL Ed25519 public key, 64 lowercase hexadecimal
  /// characters. A derivation ancestor is structurally absent from this
  /// standard: publishing one lets any holder of a child key walk the
  /// signer's whole key tree. Rotation is republication.
  SIGNING_PUBLIC_KEY: string (required);
  /// RFC 3339 UTC fixed-millisecond timestamp (YYYY-MM-DDTHH:mm:ss.sssZ)
  /// at which the attestation was produced.
  SIGNED_AT: string;
  /// Ed25519 signature over the size-prefixed FlatBuffer with both 64-byte
  /// signature payloads zeroed while preserving their vectors and offsets.
  SIGNATURE: [ubyte] (required);
  /// Ed25519 signature over canonical JSON with IDL field order and
  /// capitalization, no insignificant whitespace, and both signature fields
  /// omitted.
  CANONICAL_JSON_SIGNATURE: [ubyte] (required);
}

/// Build Profile — one saved, portable build configuration.
///
/// PORTABILITY. The export unit is a `$REC` collection carrying this record
/// and, optionally, an `$APP` manifest that names it through an `APPDataRef`
/// with `SDS_TYPE: "BPF"`. The `$APP` wrapper is launcher metadata and
/// carries no authority; all authority over a profile lives in
/// `ATTESTATION`. A bare size-prefixed `$BPF` buffer is also a complete,
/// valid export.
table BPF {
  /// Stable profile identity, unique per author. Required.
  PROFILE_ID: string (required);
  /// Display name of the profile. Required.
  NAME: string (required);
  /// Human-readable summary.
  DESCRIPTION: string;
  /// RFC 3339 UTC fixed-millisecond timestamp (YYYY-MM-DDTHH:mm:ss.sssZ)
  /// when the profile was created.
  CREATED_AT: string;
  /// RFC 3339 UTC fixed-millisecond timestamp (YYYY-MM-DDTHH:mm:ss.sssZ)
  /// when the profile was last updated.
  UPDATED_AT: string;
  /// 64 lowercase hexadecimal characters encoding SHA-256 of the build
  /// template this profile was authored against. Required: a profile that
  /// does not say which template it configures cannot be validated against
  /// one. A consumer holding a different template MAY still import the
  /// profile but MUST mark it as authored against another template and MUST
  /// NOT silently re-map its parts.
  TEMPLATE_SHA256: string (required);
  /// Template slots and their inclusion decisions. A slot the template
  /// exposes and this vector omits is NOT included.
  PARTS: [BPFPart];
  /// Modules selected into the build and their protection tiers.
  MODULES: [BPFModule];
  /// The runtime restriction the produced artifact enforces. Required, so
  /// that an unlocked build is a stated configuration rather than a missing
  /// one.
  RUNTIME_LOCK: BPFRuntimeLock (required);
  /// Distribution-control mode of the produced artifact.
  LICENSE_MODE: bpfLicenseMode = UNSPECIFIED;
  /// Publisher attestation. Absent means the profile is unsigned; see
  /// `BPFAttestation` for the fail-closed rule when it is present.
  ATTESTATION: BPFAttestation;
}

root_type BPF;
file_identifier "$BPF";

