FSO.IDL:
// Hash: 7698d54cba61bbb638104d37211cc2dbb15e446aefcfedfb4a66d0c46c70b90f
// Version: 1.164.0
// -----------------------------------END_HEADER
attribute "aligned_max_count";
attribute "aligned_max_length";

/// FlatSQL node operation selected by an FSO control frame. These operations
/// execute inside the independently instantiated FlatSQL WASM node; a host
/// routes the bytes but never implements an operation.
enum flatSqlNodeOperation : ubyte {
  NONE,
  APPEND_RECORDS,
  QUERY_RECORDS,
  CONFIGURE_INDEX,
  UPSERT_VIEW,
  COMPACT,
  CONFIGURE_RETENTION,
  SNAPSHOT,
  RELOAD
}

/// FlatSQL operation outcome carried on the typed output port. Invocation ABI
/// errors remain in PIV; this status reports database-operation semantics.
enum flatSqlNodeStatus : ubyte {
  UNSPECIFIED,
  OK,
  ACCEPTED,
  YIELDED,
  COMPLETE,
  INVALID_ARGUMENT,
  NOT_CONFIGURED,
  NOT_FOUND,
  CONFLICT,
  RESOURCE_EXHAUSTED,
  INTERNAL_ERROR
}

/// One canonical SDS file-identifier to FlatSQL table binding. A configured
/// node rebuilds these bindings before replaying durable record bytes.
table FSOTableBinding {
  FILE_IDENTIFIER:string (aligned_max_length: 4);
  TABLE_NAME:string (aligned_max_length: 128);
}

/// FlatSQL Operation — generic control, policy, and status record for the
/// independently packaged FlatSQL WASM node.
///
/// Bulk records, query results, snapshots, and WAL chunks travel separately as
/// FSB frames so operations remain streamable and no host needs to interpret a
/// database payload. SCHEMA_IDL is canonical SDS/FlatBuffers IDL supplied to
/// the node for schema-derived table/index construction.
table FSO {
  OPERATION:flatSqlNodeOperation = NONE;
  REQUEST_ID:ulong;

  DATABASE_NAME:string (aligned_max_length: 128);
  /// UTF-8 FlatBuffers IDL bytes. A byte vector is used because the aligned
  /// compiler intentionally limits fixed inline strings to 255 bytes.
  SCHEMA_IDL:[ubyte] (aligned_max_count: 262144);
  TABLE_BINDINGS:[FSOTableBinding] (aligned_max_count: 64);

  TABLE_NAME:string (aligned_max_length: 128);
  INDEX_NAME:string (aligned_max_length: 128);
  /// UTF-8 index expression bytes.
  INDEX_EXPRESSION:[ubyte] (aligned_max_count: 2048);
  VIEW_NAME:string (aligned_max_length: 128);
  /// UTF-8 SQL/query bytes.
  QUERY:[ubyte] (aligned_max_count: 16384);
  PARAMETERS:[ubyte] (aligned_max_count: 65536);
  PARAMETER_COUNT:uint;
  /// UTF-8 upsert-key expression bytes.
  UPSERT_KEY_EXPRESSION:[ubyte] (aligned_max_count: 2048);

  RETENTION_MAX_RECORDS:ulong;
  RETENTION_MAX_AGE_MILLIS:ulong;
  COMPACTION_TARGET_BYTES:ulong;

  STATUS:flatSqlNodeStatus = UNSPECIFIED;
  AFFECTED_RECORDS:ulong;
  RESULT_BYTES:ulong;
  ERROR_CODE:string (aligned_max_length: 128);
  /// UTF-8 diagnostic bytes.
  MESSAGE:[ubyte] (aligned_max_count: 4096);
}

root_type FSO;
file_identifier "$FSO";

VAM.IDL:
// Hash: 9404498379bf58d974e496c7b3740bdf9fe8e2002643bf29c318700a22b2108c
// Version: 1.150.0
// -----------------------------------END_HEADER
/// Role of one visual asset variant.
enum visualAssetVariantKind : byte {
  SOURCE,
  OPTIMIZED,
  LOD,
  ALTERNATE
}

/// Lifecycle state. Append new values only; never reorder or reuse existing values.
enum visualAssetReviewState : byte {
  DISCOVERED,
  METADATA_VALIDATED,
  LICENSE_CLEARED,
  STAGED,
  REVIEW_OPEN,
  APPROVED,
  REJECTED,
  CHANGES_REQUESTED,
  OPTIMIZED,
  PUBLISHED,
  SUPERSEDED
}

/// License gate.
enum visualAssetLicenseClass : byte {
  USABLE_NOW,
  CANDIDATE_NEEDS_LICENSE,
  MANUAL_REVIEW
}

/// Permission determination: UNKNOWN means no determination, ALLOWED means the license permits it, and PROHIBITED means the license explicitly forbids it.
enum visualAssetPermissionDecision : byte {
  UNKNOWN,
  ALLOWED,
  PROHIBITED
}

/// Up axis.
enum visualAssetUpAxis : byte {
  X_UP,
  Y_UP,
  Z_UP
}

/// Review decision.
enum visualAssetDecisionKind : byte {
  NONE,
  APPROVE,
  REJECT,
  REQUEST_CHANGES,
  APPROVE_METADATA_ONLY,
  ESCALATE_LICENSE,
  SELECT_ALTERNATE
}

/// Reviewer authorization role. Append new values only; never reorder or reuse existing values.
enum visualAssetReviewerRole : byte {
  VIEWER,
  REVIEWER,
  ADMIN
}

/// Three-dimensional vector.
table VAMVector3 {
  X:double;
  Y:double;
  Z:double;
}

/// Scale with identity defaults for every component.
table VAMScale3 {
  X:double = 1.0;
  Y:double = 1.0;
  Z:double = 1.0;
}

/// Rotation quaternion.
table VAMQuaternion {
  X:double;
  Y:double;
  Z:double;
  W:double = 1.0;
}

/// Transform from source coordinates into canonical meters. Absent SCALE and omitted scale components mean identity scale; translation and bounds use VAMVector3 zero defaults.
table VAMTransform {
  TRANSLATION:VAMVector3;
  ROTATION:VAMQuaternion;
  SCALE:VAMScale3;
  UP_AXIS:visualAssetUpAxis = Y_UP;
  SOURCE_UNITS:string;
  METERS_PER_SOURCE_UNIT:double = 1.0;
  ORIGIN_NOTE:string;
}

/// Coordinate pin or general structured annotation in canonical model-meter coordinates. POSITION is absent for a general note.
table VAMAnnotation {
  ID:string (required);
  KIND:string (required);
  MESSAGE:string (required);
  POSITION:VAMVector3;
}

/// Provenance and license metadata for an asset source.
table VAMSource {
  SOURCE_RECORD_ID:string (required);
  SOURCE_NAME:string;
  SOURCE_URL:string (required);
  /// RFC 3339 UTC fixed-millisecond timestamp (YYYY-MM-DDTHH:mm:ss.sssZ) when the source was observed.
  OBSERVED_AT:string;
  LICENSE_CLASS:visualAssetLicenseClass = MANUAL_REVIEW;
  LICENSE_NAME:string;
  ATTRIBUTION:string;
  REDISTRIBUTION_PERMISSION:visualAssetPermissionDecision = UNKNOWN;
  DERIVATIVE_PERMISSION:visualAssetPermissionDecision = UNKNOWN;
  /// 64 lowercase hexadecimal characters encoding SHA-256 of canonical UTF-8 JSON source-metadata bytes.
  SOURCE_METADATA_SHA256:string;
  NOTES:string;
}

/// Geometry, material, texture, and bounds measurements.
table VAMMetrics {
  TRIANGLE_COUNT:uint64;
  VERTEX_COUNT:uint64;
  PRIMITIVE_COUNT:uint;
  DRAW_CALL_COUNT:uint;
  MATERIAL_COUNT:uint;
  TEXTURE_COUNT:uint;
  TEXTURE_BYTES:uint64;
  ANIMATION_COUNT:uint;
  BOUNDING_BOX_MIN:VAMVector3;
  BOUNDING_BOX_MAX:VAMVector3;
  DIMENSIONS_METERS:VAMVector3;
}

/// Validation result for one asset variant.
table VAMValidation {
  STATUS:string;
  VALIDATOR_NAME:string;
  VALIDATOR_VERSION:string;
  /// RFC 3339 UTC fixed-millisecond timestamp (YYYY-MM-DDTHH:mm:ss.sssZ) when validation completed.
  VALIDATED_AT:string;
  ERRORS:[string];
  WARNINGS:[string];
}

/// One named quality score and its basis.
table VAMQualityDimension {
  NAME:string (required);
  SCORE:double;
  BASIS:string;
}

/// One source, optimized, LOD, or alternate visual representation.
table VAMVariant {
  ID:string (required);
  PARENT_VARIANT_ID:string;
  VARIANT_KIND:visualAssetVariantKind = SOURCE;
  LOD_LEVEL:uint;
  FILE_NAME:string;
  /// IANA media type of the exact variant bytes.
  MEDIA_TYPE:string;
  BYTE_LENGTH:uint64;
  /// 64 lowercase hexadecimal characters encoding SHA-256 of the exact variant file bytes.
  BYTE_SHA256:string;
  /// CIDv1 containing a multihash of the exact variant file bytes.
  CID:string;
  MULTIFORMAT_ADDRESS:string;
  /// MAJOR.MINOR glTF specification version, such as 2.0.
  GLTF_VERSION:string;
  GENERATOR:string;
  CONVERSION_TOOL:string;
  /// CONVERSION_VERSION is the exact version identifier reported by CONVERSION_TOOL without normalization.
  CONVERSION_VERSION:string;
  CONVERSION_PROFILE:string;
  /// 64 lowercase hexadecimal characters encoding SHA-256 of the exact conversion input bytes.
  INPUT_SHA256:string;
  SOURCE:VAMSource;
  TRANSFORM:VAMTransform;
  METRICS:VAMMetrics;
  VALIDATION:VAMValidation;
  QUALITY:[VAMQualityDimension];
  REVIEW_STATE:visualAssetReviewState = DISCOVERED;
  SUPERSEDES_VARIANT_ID:string;
  /// Priority within the VAM; zero is highest priority and ranks must be unique within a VAM.
  RANK:uint;
}

/// Exact approved alternate asset bytes and reviewed state.
table VAMApprovedAlternate {
  VARIANT_ID:string (required);
  /// Nonempty CIDv1 identifying the exact approved alternate bytes.
  CID:string (required);
  /// SHA-256 of the exact approved alternate bytes as 64 lowercase hexadecimal characters.
  BYTE_SHA256:string (required);
  REVIEWED_TRANSFORM:VAMTransform (required);
  RANK:uint;
}

/// Signed binary-backed review decision over a specific candidate. This table exists only for a submitted decision; DECISION NONE and APPROVE_METADATA_ONLY are not accepted VAMReview evidence.
/// The review-envelope projection contains these uppercase schema field names in schema declaration order: REVIEWER_ID; CAPABILITY_ID when present; DECISION encoded as its unsigned enum integer; CANDIDATE_ID; CANDIDATE_CID when present; CANDIDATE_SHA256; DECIDED_AT; REASONS; COMMENT when present; SIGNATURE_TYPE; PREVIOUS_DECISION_SHA256 when present; REVIEWER_ROLE encoded as its unsigned enum integer; REPOSITORY; ISSUE_NUMBER; ENTITY_ID; VAM_ID; NONCE; REVIEWED_TRANSFORM when present; CANONICAL_VARIANT_ID when present; ALTERNATE_VARIANT_IDS; ANNOTATIONS; and APPROVED_ALTERNATES.
/// Projection order is descriptive; RFC 8785 sorts object keys during canonicalization.
/// Absent optional fields are omitted and arrays preserve order; nested VAMTransform and VAMAnnotation use uppercase schema field names and numeric enums. Nested VAMApprovedAlternate uses uppercase schema field names, numeric RANK, and transforms normalized by decoding schema defaults. A verifier reconstructs exactly this projection, applies RFC 8785 JSON Canonicalization Scheme (JCS), hashes the UTF-8 serialization bytes, compares the digest, then verifies SIGNATURE over the raw 32-byte digest.
/// Before trusting DECISION, a verifier must enforce binary decision invariants; repository, issue, entity, and VAM equality; nonce single use; role authorization; and exact candidate binding. CAPABILITY_ID, REPOSITORY, ISSUE_NUMBER, ENTITY_ID, VAM_ID, and NONCE MUST be present and nonempty for any new binary-backed signed decision and are required by the binary validation profile; their wire slots are optional only for backward compatibility.
/// Legacy buffers lacking those six fields remain decodable but are not valid new publication approvals. For these compatibility fields, the projection omits absent optionals only when decoding legacy records; the new validation profile rejects absence before signature trust. APPROVE requires CANDIDATE_CID; every binary decision requires exact CANDIDATE_SHA256.
/// Under the validation profile, when DECISION is APPROVE, CANDIDATE_CID MUST be present; REVIEWED_TRANSFORM and CANONICAL_VARIANT_ID MUST be present; and CANONICAL_VARIANT_ID MUST equal CANDIDATE_ID. These fields remain optional on the wire for compatibility.
/// The enclosing VAM.ID MUST equal VAM_ID; the enclosing VAM.ENTITY_ID MUST equal review ENTITY_ID; and the enclosing VAM.CANONICAL_VARIANT_ID MUST equal review CANONICAL_VARIANT_ID.
/// The referenced VAMVariant.ID MUST equal CANDIDATE_ID; that variant CID and BYTE_SHA256 MUST equal signed CANDIDATE_CID and CANDIDATE_SHA256; and its TRANSFORM MUST be field-for-field equal to REVIEWED_TRANSFORM after decoding schema defaults.
/// The enclosing VAM.ALTERNATE_VARIANT_IDS MUST exactly equal signed review ALTERNATE_VARIANT_IDS, with the same IDs in the same order; empty equals empty.
/// Each alternate ID MUST resolve to an existing VAMVariant; alternate IDs MUST be distinct and MUST NOT equal CANONICAL_VARIANT_ID. The referenced alternates retain their signed canonical rank ordering as represented by the manifest list.
/// APPROVED_ALTERNATES MUST correspond one-for-one with ALTERNATE_VARIANT_IDS in the same order; each descriptor VARIANT_ID MUST equal the corresponding alternate ID. Empty ALTERNATE_VARIANT_IDS requires empty APPROVED_ALTERNATES.
/// Each descriptor CID, BYTE_SHA256, REVIEWED_TRANSFORM, and RANK MUST be field-for-field equal to the resolved VAMVariant. BYTE_SHA256 MUST be 64 lowercase hexadecimal characters and CID MUST be nonempty.
/// The publication validator rejects any omission or mismatch before signature trust or publication. Any alternate byte, CID, BYTE_SHA256, transform, or rank change requires a new signed review and envelope.
table VAMReview {
  REVIEWER_ID:string (required);
  CAPABILITY_ID:string;
  DECISION:visualAssetDecisionKind = NONE;
  CANDIDATE_ID:string (required);
  /// Optional CIDv1 containing a multihash of exact candidate bytes; metadata-only candidates may not have a CID.
  CANDIDATE_CID:string;
  /// 64 lowercase hexadecimal SHA-256 of exact candidate bytes, required for every binary-backed decision.
  CANDIDATE_SHA256:string (required);
  /// RFC 3339 UTC fixed-millisecond timestamp (YYYY-MM-DDTHH:mm:ss.sssZ) when the decision was made.
  DECIDED_AT:string (required);
  REASONS:[string];
  COMMENT:string;
  /// 64 lowercase hexadecimal characters encoding SHA-256 of the RFC 8785 JCS serialization of the projected review object, excluding ENVELOPE_SHA256 and SIGNATURE.
  ENVELOPE_SHA256:string (required);
  /// Signature over the raw 32-byte SHA-256 digest represented by ENVELOPE_SHA256.
  SIGNATURE:[ubyte] (required);
  /// Signature algorithm and profile; initially Ed25519.
  SIGNATURE_TYPE:string (required);
  /// 64 lowercase hexadecimal characters encoding SHA-256 of the prior projected review object's RFC 8785 JCS serialization, excluding its ENVELOPE_SHA256 and SIGNATURE.
  PREVIOUS_DECISION_SHA256:string;
  REVIEWER_ROLE:visualAssetReviewerRole = VIEWER;
  /// Canonical repository identifier in owner/name form.
  REPOSITORY:string;
  /// Positive base-10 issue number digits with no leading zero.
  ISSUE_NUMBER:string;
  ENTITY_ID:string;
  VAM_ID:string;
  /// Unique opaque identifier containing at least 128 bits of entropy.
  NONCE:string;
  REVIEWED_TRANSFORM:VAMTransform;
  CANONICAL_VARIANT_ID:string;
  ALTERNATE_VARIANT_IDS:[string];
  ANNOTATIONS:[VAMAnnotation];
  APPROVED_ALTERNATES:[VAMApprovedAlternate];
}

/// Signed metadata-only review. DECISION validation MUST equal APPROVE_METADATA_ONLY; no candidate binary or CID fields exist.
/// The metadata-review signed projection contains uppercase schema field names in schema declaration order: REVIEWER_ID; CAPABILITY_ID; REVIEWER_ROLE encoded as its unsigned enum integer; REPOSITORY; ISSUE_NUMBER; ENTITY_ID; VAM_ID; NONCE; DECISION encoded as its unsigned enum integer; CANDIDATE_ID; CANDIDATE_METADATA_SHA256; DECIDED_AT; REASONS; COMMENT when present; ANNOTATIONS; SIGNATURE_TYPE; and PREVIOUS_DECISION_SHA256 when present.
/// Absent optional fields are omitted and arrays preserve order. A verifier reconstructs exactly this projection, applies RFC 8785 JCS, hashes the UTF-8 serialization bytes, compares ENVELOPE_SHA256, and verifies SIGNATURE over the raw 32-byte digest. ENVELOPE_SHA256 and SIGNATURE are excluded from the projection.
/// The verifier must also enforce repository, issue, entity, and VAM equality; nonce single use; role authorization; exact metadata binding; and DECISION equal to APPROVE_METADATA_ONLY before trusting the decision.
table VAMMetadataOnlyReview {
  REVIEWER_ID:string (required);
  CAPABILITY_ID:string (required);
  REVIEWER_ROLE:visualAssetReviewerRole = VIEWER;
  REPOSITORY:string (required);
  ISSUE_NUMBER:string (required);
  ENTITY_ID:string (required);
  VAM_ID:string (required);
  NONCE:string (required);
  DECISION:visualAssetDecisionKind = APPROVE_METADATA_ONLY;
  CANDIDATE_ID:string (required);
  /// 64 lowercase hexadecimal SHA-256 of the RFC 8785 JCS canonical JSON VAMSource projection using uppercase field names.
  /// The VAMSource projection always includes SOURCE_RECORD_ID and SOURCE_URL; includes SOURCE_NAME, OBSERVED_AT, LICENSE_NAME, ATTRIBUTION, SOURCE_METADATA_SHA256, and NOTES only when present; and always includes LICENSE_CLASS, REDISTRIBUTION_PERMISSION, and DERIVATIVE_PERMISSION as unsigned enum integers. It contains no other fields.
  /// A verifier reconstructs this projection from the candidate SOURCE and compares the digest before trusting DECISION.
  CANDIDATE_METADATA_SHA256:string (required);
  DECIDED_AT:string (required);
  REASONS:[string];
  COMMENT:string;
  ANNOTATIONS:[VAMAnnotation];
  ENVELOPE_SHA256:string (required);
  SIGNATURE:[ubyte] (required);
  SIGNATURE_TYPE:string (required);
  PREVIOUS_DECISION_SHA256:string;
}

/// Visual Asset Manifest — ranked visual representations for one stable entity.
table VAM {
  ID:string (required);
  /// SemVer 2.0.0 manifest-format version, not a content revision.
  VERSION:string;
  ENTITY_ID:string (required);
  ENTITY_KIND:string;
  /// Identifies the approved canonical variant; alternate variants preserve their ranks.
  CANONICAL_VARIANT_ID:string;
  ALTERNATE_VARIANT_IDS:[string];
  /// MUST be sorted ascending RANK. Ranks must be unique; tie-break bytewise ID only for invalid or legacy duplicate ranks.
  VARIANTS:[VAMVariant];
  REVIEW:VAMReview;
  REVIEW_STATE:visualAssetReviewState = DISCOVERED;
  /// RFC 3339 UTC fixed-millisecond timestamp (YYYY-MM-DDTHH:mm:ss.sssZ) when the manifest was created.
  CREATED_AT:string;
  /// RFC 3339 UTC fixed-millisecond timestamp (YYYY-MM-DDTHH:mm:ss.sssZ) when the manifest was last updated.
  UPDATED_AT:string;
  /// CIDv1 containing a multihash of the exact superseded VAM bytes.
  SUPERSEDES_VAM_CID:string;
  /// CIDv1 containing a multihash of the exact referenced DPM bytes.
  DPM_CID:string;
  /// Mutually exclusive with REVIEW; metadata-only decisions use METADATA_REVIEW.
  METADATA_REVIEW:VAMMetadataOnlyReview;
}

root_type VAM;
file_identifier "$VAM";

DPM.IDL:
// Hash: bef01cefae37f338f92f8bdf2332978f3e95ab7f95c1fe3c7f2bf9f54b31d526
// Version: 1.0.9
// -----------------------------------END_HEADER
/// Dataset Publication Manifest.
///
/// A DPM is the immutable, signed manifest for one dataset publication. A
/// provider creates it after ingesting source data, normalizing records into
/// SDS FlatBuffers, and deciding which exact product is authoritative for that
/// publication window. The DPM is the retrieval and verification contract for
/// that product: it binds the provider identity, dataset/update identifiers,
/// canonical FILE_ID, source batch provenance, published assets, byte lengths,
/// byte hashes, schema hashes, query replay metadata, completeness roots,
/// optional encryption metadata, and provider signature into one object.
///
/// For content-addressed publications, the DPM lists the data shard, query
/// index, manifest, and auxiliary assets by CID or multiformat address. For
/// provider-mediated publications, it records the signed query protocol and
/// Merkle/completeness roots that returned records must prove against before a
/// subscriber imports them. The DPM is not the network notification itself:
/// subscribers usually discover it from a signed PNM whose CID points at the
/// DPM or a compact DPM digest, then fetch and verify the DPM before resolving
/// any listed asset or accepting any provider response.

/// Published artifact role within a dataset update.
enum publicationAssetKind : byte {
  DATA_SHARD,
  QUERY_INDEX,
  MANIFEST,
  OTHER,
  /// A $CES catalog embedding shard (dense per-object vector table).
  EMBEDDING_SHARD,
  /// A $QEM query encoder model (pruned static token-embedding table).
  QUERY_ENCODER_MODEL
}

/// Transport profile used to resolve a dataset update asset.
enum dpmTransportKind : byte {
  /// Asset bytes are resolved by content address, usually an IPFS CID.
  CONTENT_ADDRESS,
  /// Asset bytes are resolved from the provider through a signed SDN query
  /// protocol. This mode is used when the update is not published as a
  /// globally discoverable file.
  SDN_QUERY,
  /// Asset bytes are resolved by another protocol named in TRANSPORT_PROTOCOL.
  OTHER
}

/// Completeness-capable signed index over a dataset update.
table DPMCompletenessIndex {
  /// Stable index name, e.g. file_id, norad_cat_id, epoch, source_batch. Every
  /// completeness-verifiable dataset update SHOULD include a file_id index so
  /// subscribers can prove that all returned records belong to the announced
  /// FILE_ID partition. The file_id index is the preferred completeness anchor
  /// for provider-mediated data that is not published as a discoverable file.
  INDEX_NAME: string;
  /// Deterministic ordering expression for the index. Providers and
  /// subscribers MUST use this ordering when building or verifying range
  /// proofs. A query is completeness-verifiable only when its predicate can be
  /// expressed against one or more declared indexes.
  CANONICAL_ORDER: string;
  /// SHA-256 or Merkle root of the ordered index, lowercase hex. This root is
  /// signed by the DPM provider signature and is the verifier's commitment for
  /// inclusion and range-completeness proofs. To verify a provider-mediated
  /// response, the subscriber recomputes each returned leaf, walks the supplied
  /// sibling hashes using MERKLE_PROFILE, confirms the root equals INDEX_ROOT,
  /// confirms the leaf material includes the DPM.FILE_ID partition when this is
  /// the file_id index, and confirms any range-boundary proofs required by
  /// CANONICAL_ORDER.
  INDEX_ROOT: string;
  /// Hash profile for leaves and internal nodes, e.g.
  /// SDN-MERKLE-SHA256-v1. Profiles define domain separators, leaf material,
  /// pair ordering, duplicate handling, and odd-leaf promotion.
  MERKLE_PROFILE: string;
  /// Whether this index can prove that no matching records were omitted for a
  /// supported range query. Inclusion proofs alone prove authenticity, not
  /// completeness.
  SUPPORTS_RANGE_COMPLETENESS: bool;
}

/// One immutable asset or provider-mediated query contract published for a
/// dataset update.
table DPMAsset {
  /// Asset role.
  ASSET_KIND: publicationAssetKind = OTHER;
  /// Transport profile for this asset. CONTENT_ADDRESS assets use CID and
  /// MULTIFORMAT_ADDRESS. SDN_QUERY assets use TRANSPORT_PROTOCOL plus the
  /// signed DPM query and root fields; they are not required to be published as
  /// discoverable IPFS files.
  TRANSPORT_KIND: dpmTransportKind = CONTENT_ADDRESS;
  /// Optional IPFS CIDv1/multihash content identifier. This field is required
  /// for CONTENT_ADDRESS assets and SHOULD be empty for SDN_QUERY assets whose
  /// bytes are retrieved through a provider protocol.
  CID: string;
  /// Multiformat address. For CONTENT_ADDRESS this is usually /ipfs/{CID}. For
  /// SDN_QUERY this MAY be a provider peer multiaddr, relay hint, or empty when
  /// provider routing is resolved from the DPM provider identity.
  MULTIFORMAT_ADDRESS: string;
  /// File name or logical artifact name.
  FILE_NAME: string;
  /// Canonical publication/update partition identity for this asset. FILE_ID is
  /// not a display filename; it is the stable identifier used everywhere this
  /// update is referenced: PNMs, DPMs, assets, manifests, entitlements, query
  /// requests, subscriber caches, replay, audit, and completeness proofs.
  /// Example:
  /// provider-slug:gp:OMM.fbs:2026-05-06T03:00:00Z.
  FILE_ID: string;
  /// Provider protocol name/version used to fetch this asset when
  /// TRANSPORT_KIND is SDN_QUERY, e.g. /sdn/dataset-query/1.0.0. The protocol
  /// response MUST be verifiable against DATA_ROOT, INDEXES, QUERY, and the
  /// provider signature in this DPM.
  TRANSPORT_PROTOCOL: string;
  /// Byte length of the published object.
  BYTE_LENGTH: uint64;
  /// SHA-256 hash of the exact published bytes, lowercase hex.
  BYTE_SHA256: string;
  /// Merkle root over canonical records in this asset, lowercase hex. For
  /// provider-mediated query delivery, subscribers verify returned records and
  /// proof paths against this root before importing data. The proof material is
  /// carried by the provider query response, not by the DPM itself; this field
  /// is the signed root that makes those proofs meaningful.
  DATA_ROOT: string;
  /// SDS schema name for data artifacts, e.g. OMM.fbs, CAT.fbs, SPW.fbs.
  SCHEMA_NAME: string;
  /// Hash of the SDS schema used to encode this object.
  SCHEMA_HASH: string;
  /// Optional content-key identifier for encrypted artifacts.
  CONTENT_KEY_ID: string;
}

/// Source batch metadata bound into the dataset publication.
table DPMSourceBatch {
  /// Provider-controlled source name.
  SOURCE_NAME: string;
  /// Original source URL.
  SOURCE_URL: string;
  /// SHA-256 hash of raw source bytes, lowercase hex.
  SOURCE_SHA256: string;
  /// HTTP ETag observed during retrieval.
  HTTP_ETAG: string;
  /// HTTP Last-Modified value observed during retrieval.
  HTTP_LAST_MODIFIED: string;
  /// Retrieval timestamp in ISO 8601 UTC.
  RETRIEVED_AT: string;
  /// Parser or transform version.
  PARSER_VERSION: string;
  /// Number of normalized records emitted from this source.
  RECORD_COUNT: uint64;
  /// Warnings or policy notes produced during normalization.
  WARNINGS: [string];
  /// SPDX license identifier governing the source data, e.g. CC-BY-4.0 or
  /// CC-BY-SA-4.0. Machine-readable license provenance is REQUIRED before any
  /// record derived from this batch may be republished; share-alike terms
  /// propagate from this batch to every derived record.
  LICENSE: string;
  /// Canonical URL of the license text.
  LICENSE_URL: string;
  /// Attribution/citation string the source license requires downstream
  /// republication to carry.
  CITATION: string;
}

/// Canonical query metadata that can replay the dataset selection.
table DPMQueryBinding {
  /// Canonical query text or canonical JSON representation.
  CANONICAL_QUERY: string (required);
  /// SHA-256 hash of CANONICAL_QUERY, lowercase hex.
  QUERY_SHA256: string (required);
  /// SHA-256 hash of the ordered result bytes, lowercase hex.
  RESULT_SHA256: string (required);
  /// Query engine or profile name, e.g. FlatSQL.
  QUERY_ENGINE: string;
  /// Query engine version or profile version.
  QUERY_ENGINE_VERSION: string;
  /// Canonical ordering of result records before RESULT_SHA256 or DATA_ROOT is
  /// computed. Providers MUST stream records in this order unless each chunk
  /// includes enough proof material to restore and verify the canonical order.
  CANONICAL_ORDER: string;
  /// Query protocol name/version for provider-mediated retrieval, e.g.
  /// /sdn/dataset-query/1.0.0. A subscriber verifies the PNM and DPM, opens this
  /// protocol to the provider, submits the signed query or a permitted subset,
  /// and imports only responses that verify against the signed roots. Responses
  /// MUST include enough Merkle proof material for each returned record and, for
  /// completeness-verifiable range queries, the declared range-boundary proofs.
  QUERY_PROTOCOL: string;
  /// SDS schema names selected by the query.
  SCHEMA_NAMES: [string];
  /// Provider peer IDs selected by the query.
  PROVIDER_IDS: [string];
  /// Source names selected by the query.
  SOURCE_NAMES: [string];
  /// Batch IDs selected by the query.
  BATCH_IDS: [string];
  /// Inclusive query window start in ISO 8601 UTC.
  WINDOW_START: string;
  /// Inclusive query window end in ISO 8601 UTC.
  WINDOW_END: string;
}

/// Encryption metadata for protected dataset artifacts.
table DPMEncryptionBinding {
  /// Whether any artifact in this manifest is encrypted.
  ENCRYPTED: bool;
  /// Encryption algorithm, e.g. AES-256-GCM.
  ALGORITHM: string;
  /// Content-key identifier.
  CONTENT_KEY_ID: string;
  /// Key epoch or rotation label.
  KEY_EPOCH: string;
  /// Policy or listing identifier bound as AAD.
  POLICY_ID: string;
  /// SHA-256 hash of canonical encryption AAD, lowercase hex.
  AAD_SHA256: string;
}

/// Immutable signed publication contract for one dataset update. DPM records
/// are the authoritative product manifests consumed by subscribers, pinning
/// nodes, archive nodes, and query gateways. A valid DPM answers: who published
/// this update, which dataset and FILE_ID it represents, which source batches
/// produced it, which exact bytes or provider-mediated query responses are
/// authorized, how those bytes are addressed, how records and indexes are
/// hashed, whether content-key metadata applies, and which provider signature
/// commits to the manifest. PNM announces the current DPM; DPM defines what
/// must be fetched, verified, imported, pinned, or archived.
table DPM {
  /// Manifest format version.
  VERSION: string;
  /// Stable dataset identifier.
  DATASET_ID: string (required);
  /// Dataset update or batch identifier.
  UPDATE_ID: string (required);
  /// Canonical publication/update partition identity. FILE_ID is the key used
  /// everywhere a subscriber, provider, PNM, asset, entitlement, cache, audit
  /// log, or query protocol refers to this exact update. It is not merely a
  /// human filename and it is not the FlatBuffer file_identifier. For
  /// completeness-verifiable streams, all returned records MUST belong to this
  /// FILE_ID and prove inclusion under this DPM's signed roots, normally through
  /// a declared file_id completeness index. Use this field for all update
  /// addressing instead of inventing per-protocol IDs; provider responses,
  /// Merkle leaves, proof paths, PNM.FILE_ID, and DPMAsset.FILE_ID must all bind
  /// to the same value.
  FILE_ID: string;
  /// Provider peer ID.
  PROVIDER_PEER_ID: string (required);
  /// Provider EPM CID.
  PROVIDER_EPM_CID: string;
  /// Publication timestamp in ISO 8601 UTC.
  PUBLISH_TIMESTAMP: string (required);
  /// Published shard, index, and auxiliary artifacts.
  ASSETS: [DPMAsset];
  /// Source batches used to build the dataset.
  SOURCES: [DPMSourceBatch];
  /// Replayable query binding.
  QUERY: DPMQueryBinding;
  /// Signed completeness-capable indexes. Inclusion proofs prove that returned
  /// records are authentic members of DATA_ROOT. Range-completeness proofs also
  /// prove that no matching records were omitted, but only for predicates
  /// expressible against these declared indexes.
  INDEXES: [DPMCompletenessIndex];
  /// Encryption/key metadata.
  ENCRYPTION: DPMEncryptionBinding;
  /// Provider signature over the canonical manifest bytes or manifest digest.
  PROVIDER_SIGNATURE: [ubyte];
  /// Signature algorithm, e.g. Ed25519.
  SIGNATURE_TYPE: string;
}

root_type DPM;
file_identifier "$DPM";

