STF.IDL:
// Hash: 16f6cbfd9328aac34201b55ed9b77675183631e17f388158811b39b92385d110
// Version: 1.0.5
// -----------------------------------END_HEADER
include "../CCT/main.fbs";

/// Access type for data listings
enum accessCategory : byte {
  /// One-time purchase
  OneTime,
  /// Recurring subscription
  Subscription,
  /// Real-time streaming access
  Streaming,
  /// Query-based access
  Query
}

/// Payment method accepted
enum paymentMethod : byte {
  /// Ethereum cryptocurrency
  Crypto_ETH,
  /// Solana cryptocurrency
  Crypto_SOL,
  /// Bitcoin cryptocurrency
  Crypto_BTC,
  /// Internal SDN credits system
  SDN_Credits,
  /// Fiat payment via Stripe
  Fiat_Stripe,
  /// Free/open data
  Free,
  /// Usage-based billing settled after metered delivery
  UsageBased,
  /// Enterprise/offline invoicing
  Enterprise
}

/// Listing kind for marketplace entries.
///
/// This is the listing's DELIVERY KIND, not its capability category, and the
/// two are not interchangeable. A storefront shelf, a browse row and a search
/// facet are driven by `$CCT` `capabilityClass` via STF.PRIMARY_CATEGORY /
/// STF.CATEGORIES; `listingCategory` only says whether the offering is
/// delivered as a data stream or as a module artifact.
enum listingCategory : byte {
  DataStream,
  WasmModule,
  /// Provider-operated service.
  Service
}

/// Field-level stream policy bound into protected delivery and grants.
table GrantFieldStreamPolicy {
  POLICY_ID: string;
  POLICY_VERSION: uint32;
  STREAM_ID: string;
  SCHEMA_CODE: string;
  ALLOWED_FIELD_PATHS: [string];
  REDACTED_FIELD_PATHS: [string];
  KEY_EPOCH: string;
  GRANT_SCOPE: string;
  ALLOWED_OPERATIONS: [string];
}

/// Immutable encrypted artifact/window metadata for protected delivery.
table ProtectedDeliveryBinding {
  ENCRYPTED_CID: string;
  MANIFEST_CID: string;
  CONTENT_HASH: string;
  CONTENT_KEY_ID: string;
  LICENSE_MODULE_ID: string;
  MODULE_ID: string;
  MODULE_VERSION: string;
  REQUIRED_SCOPES: [string];
  GRANT_SCOPE: string;
  DELIVERY_PROTOCOL: string;
  FIELD_STREAM_POLICY: GrantFieldStreamPolicy;
}

/// Provider reputation summary surfaced in marketplace listings.
table ProviderReputation {
  TOTAL_SALES: uint64;
  AVERAGE_RATING_X10: uint16;
  TOTAL_RATINGS: uint32;
  UPTIME_PERCENTAGE_X100: uint16;
  AVG_DELIVERY_LATENCY_MS: uint32;
  DISPUTE_COUNT: uint32;
  PROVIDER_SINCE: uint64;
}

/// Spatial coverage definition
table SpatialCoverage {
  /// Type of coverage: "global", "region", "object_list"
  TYPE: string;
  /// Regions covered, e.g., ["LEO", "GEO", "MEO"]
  REGIONS: [string];
  /// Specific NORAD IDs or catalog numbers
  OBJECT_IDS: [string];
  /// Minimum altitude in kilometers for altitude-bounded offerings
  MIN_ALTITUDE_KM: double;
  /// Maximum altitude in kilometers for altitude-bounded offerings
  MAX_ALTITUDE_KM: double;
  /// Bounding box as [min_lat, min_lon, max_lat, max_lon]
  GEO_BOUNDS: [double];
}

/// Temporal coverage definition
table TemporalCoverage {
  /// Start epoch in ISO 8601 format
  START_EPOCH: string;
  /// End epoch in ISO 8601 format
  END_EPOCH: string;
  /// Update frequency: "realtime", "hourly", "daily"
  UPDATE_FREQUENCY: string;
  /// Days of historical data available
  HISTORICAL_DEPTH: uint32;
  /// Typical provider latency in seconds
  LATENCY_SECONDS: uint32;
}

/// Data coverage combining spatial and temporal
table DataCoverage {
  /// Spatial coverage definition
  SPATIAL: SpatialCoverage;
  /// Temporal coverage definition
  TEMPORAL: TemporalCoverage;
}

/// Pricing tier for a listing
table PricingTier {
  /// Tier name, e.g., "Basic", "Pro", "Enterprise"
  NAME: string;
  /// Price in smallest unit (cents, satoshis, etc.)
  PRICE_AMOUNT: uint64;
  /// Currency code: "USD", "ETH", "SOL", "SDN_CREDITS"
  PRICE_CURRENCY: string;
  /// Duration in days (0 = one-time purchase)
  DURATION_DAYS: uint32;
  /// Rate limit in requests per hour
  RATE_LIMIT: uint32;
  /// List of features included in this tier
  FEATURES: [string];
  /// Maximum records returned per request
  MAX_RECORDS_PER_REQUEST: uint32;
  /// Human-readable tier description
  DESCRIPTION: string;
}

/// Storefront Listing - Data marketplace listing
table STF {
  /// Unique identifier for the listing
  LISTING_ID: string (required);
  /// Peer ID of the data provider
  PROVIDER_PEER_ID: string (required);
  /// IPFS CID of provider's EPM (Entity Profile Message)
  PROVIDER_EPM_CID: string;

  /// Title of the data listing
  TITLE: string (required);
  /// Detailed description of the data offering
  DESCRIPTION: string;
  /// SDS data types offered, e.g., ["OMM", "CDM", "TLE"]
  DATA_TYPES: [string];
  /// Coverage information (spatial and temporal)
  COVERAGE: DataCoverage;
  /// IPFS CID of sample data
  SAMPLE_CID: string;

  /// Type of access offered
  ACCESS_TYPE: accessCategory;
  /// Whether encryption is required for data delivery
  ENCRYPTION_REQUIRED: bool;

  /// Available pricing tiers
  PRICING: [PricingTier];
  /// Payment methods accepted
  ACCEPTED_PAYMENTS: [paymentMethod];

  /// Unix timestamp when listing was created
  CREATED_AT: uint64;
  /// Unix timestamp when listing was last updated
  UPDATED_AT: uint64;
  /// Whether the listing is currently active
  ACTIVE: bool;

  /// Ed25519 signature from provider
  SIGNATURE: [ubyte];
  /// Listing category: data stream or WASM module
  LISTING_KIND: listingCategory;
  /// Search tags
  TAGS: [string];
  /// Number of records in sample data, when available
  SAMPLE_RECORD_COUNT: uint32;
  /// Supported delivery methods
  DELIVERY_METHODS: [string];
  /// Protected delivery metadata for encrypted artifacts or streams
  PROTECTED_DELIVERY: ProtectedDeliveryBinding;
  /// Provider reputation summary
  REPUTATION: ProviderReputation;
  /// Listing version
  VERSION: uint32;
  /// Unix timestamp when the listing expires, or 0 for no expiry
  EXPIRES_AT: uint64;
  /// Terms document CID
  TERMS_CID: string;
  /// License label or SPDX-style identifier
  LICENSE: string;
  /// Peer ID this listing was sourced from when discovered remotely
  SOURCE_PEER_ID: string;

  /// The one ratified `$CCT` category this listing is shelved under, using the
  /// same vocabulary and semantics as PLG.PRIMARY_CATEGORY and
  /// APP.PRIMARY_CATEGORY. Before this field existed a listing carried no
  /// capability category at all — only DATA_TYPES and TAGS — so a storefront
  /// shelf and a library shelf were grouped by two unrelated systems. A
  /// consumer MUST group listings by this field and MUST NOT re-derive a
  /// category from DATA_TYPES, TAGS or TITLE, none of which are a controlled
  /// vocabulary.
  ///
  /// Distinct from LISTING_KIND, which is the delivery kind (data stream vs
  /// module artifact), and from ACCESS_TYPE, which is the commercial access
  /// model. UNSPECIFIED means the provider did not classify the listing; a
  /// consumer renders it ungrouped and never guesses.
  PRIMARY_CATEGORY: capabilityClass = UNSPECIFIED;
  /// Every ratified `$CCT` category this listing belongs to, for browse,
  /// filter and per-category counting. A listing MAY carry several. If
  /// nonempty it MUST include PRIMARY_CATEGORY. Codes MUST NOT repeat.
  CATEGORIES: [capabilityClass];
}

root_type STF;
file_identifier "$STF";

MEM.IDL:
// Hash: 83a57e55c3a302f1bc901f7df0ed9051f7844ad0784fb12a1e0a6aa343dc4a51
// Version: 1.202.0
// -----------------------------------END_HEADER
/// Measurement classes supported by a tracking error model. Values are
/// capability classes; append new members only and never reuse a value.
enum memMeasurementType : ushort {
  UNSPECIFIED = 0,
  RANGE = 1,
  RANGE_RATE = 2,
  DOPPLER = 3,
  AZIMUTH_ELEVATION = 4,
  X_EAST_Y_NORTH = 5,
  X_SOUTH_Y_EAST = 6,
  RIGHT_ASCENSION_DECLINATION = 7,
  POSITION_VECTOR = 8,
  SEQUENTIAL_RANGE = 9,
  PSEUDONOISE_RANGE = 10,
  TIME_CORRELATED_PHASE = 11,
  RELAY_RANGE = 12,
  RELAY_DOPPLER = 13,
  RELAY_DIFFERENCED_DOPPLER = 14,
  BISTATIC_RANGE = 15,
  SKIN_RANGE = 16,
  CROSSLINK_RANGE = 17,
  CROSSLINK_RANGE_RATE = 18,
  LASER_RANGE = 19,
  TIME_DIFFERENCE_OF_ARRIVAL = 20,
  FREQUENCY_DIFFERENCE_OF_ARRIVAL = 21
}

enum memEditingAction : ubyte {
  UNSPECIFIED = 0,
  ACCEPT = 1,
  REJECT = 2
}

enum memEditingReason : ubyte {
  UNSPECIFIED = 0,
  ACCEPTED = 1,
  OUTSIDE_EPOCH_WINDOW = 2,
  OUTSIDE_VALUE_WINDOW = 3,
  SIGMA_THRESHOLD = 4,
  INVALID_GEOMETRY = 5,
  MISSING_MEDIA_INPUT = 6,
  HARDWARE_UNAVAILABLE = 7,
  DUPLICATE = 8,
  PROVIDER_FLAGGED = 9
}

enum memTroposphereModel : ubyte {
  UNSPECIFIED = 0,
  NONE = 1,
  HOPFIELD_SAASTAMOINEN = 2,
  MARINI = 3
}

enum memIonosphereModel : ubyte {
  UNSPECIFIED = 0,
  NONE = 1,
  TOTAL_ELECTRON_CONTENT = 2,
  REFERENCE_PROFILE = 3
}

/// Noise, bias and editing rules for one observable. Standard deviations and
/// biases use the observable's SI unit. ANGLE observables use radians.
table MEMErrorModel {
  MODEL_ID: string (required);
  MEASUREMENT_TYPE: memMeasurementType = UNSPECIFIED;
  NOISE_SIGMA: double;
  BIAS: double;
  BIAS_SIGMA: double;
  CORRELATION_TIME_SECONDS: double;
  MINIMUM_ACCEPTED_VALUE: double;
  MAXIMUM_ACCEPTED_VALUE: double;
  SIGMA_EDIT_THRESHOLD: double;
  ACCEPT_START_EPOCH: string;
  ACCEPT_STOP_EPOCH: string;
  TROPOSPHERE_MODEL: memTroposphereModel = UNSPECIFIED;
  IONOSPHERE_MODEL: memIonosphereModel = UNSPECIFIED;
  APPLY_LIGHT_TIME: bool = true;
  APPLY_BODY_ROTATION: bool = true;
}

/// One deterministic editing decision. The observation identity is carried
/// from the tracking-data input so rejected sets can be compared exactly.
table MEMEditingDecision {
  OBSERVATION_ID: string (required);
  ACTION: memEditingAction = UNSPECIFIED;
  REASON: memEditingReason = UNSPECIFIED;
  PREFIT_RESIDUAL: double;
  NORMALIZED_RESIDUAL: double;
  ITERATION: uint;
}

/// Dual-form signature. Presence means both signatures are required and both
/// MUST verify independently; an invalid member rejects the record rather
/// than downgrading it to unsigned.
table MEMAttestation {
  SIGNING_PUBLIC_KEY: string (required);
  SIGNED_AT: string;
  SIGNATURE: [ubyte] (required);
  CANONICAL_JSON_SIGNATURE: [ubyte] (required);
}

/// Measurement Error Model. JSON projections preserve these IDL-capitalized
/// field names exactly. The FlatBuffer signature covers the size-prefixed
/// buffer with both signature vectors zeroed; the canonical-JSON signature
/// covers RFC 8785 canonical JSON with both signature fields omitted.
table MEM {
  ERROR_MODELS: [MEMErrorModel];
  EDITING_LEDGER: [MEMEditingDecision];
  RANDOM_SEED: ulong;
  TRACE_ID: string;
  ATTESTATION: MEMAttestation;
}

root_type MEM;
file_identifier "$MEM";

ICN.IDL:
// Hash: 7c4a9fa2d60d9807512aa0a1e76a30bb5522439c8c904b54ba10fc1d772faa59
// Version: 1.206.1
// -----------------------------------END_HEADER
/// Ingest Connector.
///
/// An ICN describes one configured source of records entering an ingest flow.
/// Connector lifecycle STATUS is independent of any `$STF` listing status;
/// changing one never implies a change to the other.

/// Transport or source shape used by an ingest connector. Append new values
/// only; never reorder or reuse existing values.
enum icnConnectorKind : byte {
  /// Files are supplied through a bounded upload session.
  UploadSession,
  /// Records are pulled from an HTTPS endpoint.
  HttpsPull,
  /// A directory is scanned for settled files.
  FilesystemWatch
}

/// Lifecycle state of an ingest connector. Append new values only; never
/// reorder or reuse existing values.
enum icnConnectorStatus : byte {
  /// Configuration exists but has not been validated.
  Draft,
  /// Configuration passed validation but is not ingesting.
  Validated,
  /// Connector is ingesting according to its configured trigger.
  Active,
  /// Connector is intentionally suspended.
  Paused,
  /// Connector requires attention after a failed operation.
  Error,
  /// Connector is permanently out of service.
  Retired
}

/// Disposition of a source file after verified ingest. Append new values only;
/// never reorder or reuse existing values.
enum icnPostIngestAction : byte {
  /// Keep the source file at its original location.
  LeaveInPlace,
  /// Move the source file to an archive location.
  Archive,
  /// Delete the source file only after the ingested records are verified.
  DeleteAfterVerification
}

/// Authentication shape for an HTTPS pull. Append new values only; never
/// reorder or reuse existing values.
enum icnAuthKind : byte {
  /// No authentication header is sent.
  None,
  /// A bearer token is resolved from CREDENTIAL_REFERENCE.
  BearerToken,
  /// A credential is sent under AUTH_HEADER_NAME.
  ApiKeyHeader
}

/// Ingest Connector - Configuration and lifecycle of one ingest source.
table ICN {
  /// Stable connector identifier.
  CONNECTOR_ID: string (required);
  /// Transport or source shape used by this connector.
  KIND: icnConnectorKind;
  /// Target SDS schema filename, e.g. "OMM.fbs".
  TARGET_SCHEMA: string;
  /// Connector lifecycle state, independent of any `$STF` listing status.
  STATUS: icnConnectorStatus;
  /// Human-readable detail about the current status.
  STATUS_MESSAGE: string;
  /// HTTPS endpoint from which records are pulled.
  ENDPOINT_URL: string;
  /// HTTP method used for an endpoint request.
  HTTP_METHOD: string;
  /// Authentication shape used for an endpoint request.
  AUTH_KIND: icnAuthKind;
  /// Header name used when AUTH_KIND is ApiKeyHeader.
  AUTH_HEADER_NAME: string;
  /// Credential-store key resolved only at execution time. A secret never
  /// appears in an ICN record.
  CREDENTIAL_REFERENCE: string;
  /// Interval in milliseconds between endpoint polls.
  POLL_INTERVAL_MS: uint32;
  /// Directory scanned by a filesystem-watch connector.
  DIRECTORY_PATH: string;
  /// File-selection pattern applied within DIRECTORY_PATH.
  FILE_PATTERN: string;
  /// Interval in milliseconds between directory scans.
  SCAN_INTERVAL_MS: uint32;
  /// Minimum unchanged time in milliseconds before a file is ingested.
  SETTLE_DELAY_MS: uint32;
  /// Disposition of a source file after verified ingest.
  POST_INGEST_ACTION: icnPostIngestAction;
  /// Identifier of the bounded upload session.
  UPLOAD_SESSION_ID: string;
  /// Number of files accepted into the upload session.
  UPLOAD_FILE_COUNT: uint32;
  /// Total uploaded byte count across all session files.
  UPLOAD_TOTAL_BYTES: uint64;
  /// Content hash covering the uploaded session payload.
  UPLOAD_CONTENT_HASH: string;
  /// Detected source serialization or container format.
  DETECTED_FORMAT: string;
  /// Number of records detected in the validation sample.
  SAMPLE_RECORD_COUNT: uint32;
  /// Unix timestamp in milliseconds of the last successful ingest.
  LAST_INGEST_AT: uint64;
  /// Unix timestamp in milliseconds of the last ingest error.
  LAST_ERROR_AT: uint64;
  /// Human-readable detail about the last ingest error.
  LAST_ERROR: string;
  /// Unix timestamp in milliseconds when this connector was created.
  CREATED_AT: uint64;
  /// Unix timestamp in milliseconds when this connector was last updated.
  UPDATED_AT: uint64;
  /// Peer identifier of the provider that issued this connector record.
  PROVIDER_PEER_ID: string;
  /// Provider signature over the connector record.
  PROVIDER_SIGNATURE: [ubyte];

  /// Upstream publisher the connector retrieves records from, as a host name
  /// or stable identifier.
  ORIGIN_ID: string;
  /// Display name of the upstream publisher.
  ORIGIN_NAME: string;
  /// Stable dataset identifier within the origin, e.g. "gp-full-catalog".
  DATASET_ID: string;
  /// Provider identifier the lane's records are stored under.
  PROVIDER_ID: string;
  /// Source name the lane's records are stored under.
  SOURCE_NAME: string;
  /// Licence under which the upstream publisher offers the records.
  LICENSE: string;
  LICENSE_URL: string;
  /// Citation the upstream publisher asks for.
  CITATION: string;
  /// Minimum interval between fetches of the same dataset, milliseconds.
  MIN_FETCH_INTERVAL_MS: uint64;
  /// Unix milliseconds when the next fetch is eligible.
  NEXT_ELIGIBLE_AT: uint64;
  /// HTTP status of the last fetch.
  LAST_HTTP_STATUS: uint16;
  /// Entity tag returned by the last fetch.
  LAST_SOURCE_ETAG: string;
  /// Last-Modified value returned by the last fetch.
  LAST_SOURCE_LAST_MODIFIED: string;
  /// Batch identifier of the last ingest.
  LAST_BATCH_ID: string;
  /// Records parsed by the last ingest.
  LAST_RECORD_COUNT: uint64;
  /// Records newly inserted by the last ingest.
  LAST_INSERTED_COUNT: uint64;
  /// Duration of the last fetch and ingest, milliseconds.
  LAST_DURATION_MS: uint64;
  /// Fetches attempted over the connector's lifetime.
  FETCH_COUNT: uint64;
  /// Ingests completed over the connector's lifetime.
  INGEST_COUNT: uint64;
  /// Content identifier of the last publication manifest emitted.
  LAST_PUBLICATION_CID: string;
  /// Content identifier of the last publish notification emitted.
  LAST_PNM_CID: string;
  /// Feed head the connector last advanced to.
  FEED_HEAD: string;
  /// Standard codes the connector emits, e.g. ["OMM", "MPE"].
  EMITS_SCHEMAS: [string];
}

root_type ICN;
file_identifier "$ICN";

